INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af90c196-d5f3-4b4b-a11a-e7565c1c2ede', '銅雀臺', '銅雀台', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["嬌愛更何日，高臺空數層。","含啼暎雙袖，不忍看西陵。","漳水東流無復來，百花輦路爲蒼苔。","青樓月夜長寂寞，碧雲日莫空裴回。","君不見鄴中萬事非昔時，古人不在今人悲。","春風不逐君王去，草色年年舊宮路。","宮中歌舞已浮雲，空指行日往來處。"]', '["嬌愛更何日，高台空數層。","含啼暎雙袖，不忍看西陵。","漳水东流無复来，百花輦路爲蒼苔。","青楼月夜长寂寞，碧云日莫空裴回。","君不见鄴中万事非昔时，古人不在今人悲。","春风不逐君王去，草色年年旧宮路。","宮中歌舞已浮云，空指行日往来处。"]', '诗', 'shi', '', NULL, '銅雀臺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95549428-993a-4bb5-8df5-5314a1d1a0b7', '雞鳴曲', '雞鳴曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雞初鳴，明星照東屋。","雞再鳴，紅霞生海腹。","百官待漏雙闕前，聖人亦挂山龍服。","寶釵命婦燈下起，環珮玲瓏曉光裏。","直內初燒玉案香，司更尚滴銅壺水。","金吾衞裏直郎妻，到明不睡聽晨雞。","天頭日月相送迎，夜棲旦鳴人不迷。"]', '["雞初鳴，明星照东屋。","雞再鳴，紅霞生海腹。","百官待漏雙闕前，聖人亦挂山龙服。","寶釵命婦灯下起，环珮玲瓏晓光裏。","直內初燒玉案香，司更尚滴銅壺水。","金吾衞裏直郎妻，到明不睡听晨雞。","天头日月相送迎，夜棲旦鳴人不迷。"]', '诗', 'shi', '', NULL, '雞鳴曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6506d657-132c-4a38-8f74-f806603d7be4', '送衣曲', '送衣曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["去秋送衣渡黃河，今秋送衣上隴坂。","婦人不知道徑處，但問新移軍近遠。","半年著道經雨濕，開籠見風衣領急。","舊來十月初點衣，與郎著向營中集。","絮時厚厚綿纂纂，貴欲征人身上暖。","願身莫著裹屍歸，願妾不死長送衣。"]', '["去秋送衣渡黄河，今秋送衣上隴坂。","婦人不知道徑处，但问新移軍近远。","半年著道經雨濕，开籠见风衣領急。","旧来十月初点衣，與郎著向營中集。","絮时厚厚綿纂纂，貴欲征人身上暖。","願身莫著裹屍归，願妾不死长送衣。"]', '诗', 'shi', '', NULL, '送衣曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad76797-2f87-4dce-ac75-4d14e9a04b6a', '斜路行', '斜路行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["世間娶容非娶婦，中庭牡丹勝松樹。","九衢大道人不行，走馬奔車逐斜路。","斜路行熟直路荒，東西豈是橫太行。","南樓彈弦北戶舞，行人到此多回徨。","頭白如絲面如繭，亦學少年行不返。","縱令自解思故鄉，輪折蹄穿白日晚。","誰將古曲換斜音，回取行人斜路心。"]', '["世间娶容非娶婦，中庭牡丹勝松樹。","九衢大道人不行，走马奔车逐斜路。","斜路行熟直路荒，东西豈是橫太行。","南楼彈弦北戶舞，行人到此多回徨。","头白如絲面如繭，亦学少年行不返。","縱令自解思故乡，輪折蹄穿白日晚。","誰將古曲換斜音，回取行人斜路心。"]', '诗', 'shi', '', NULL, '斜路行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff401cb-6ddc-4559-a19a-075a15f132f1', '織錦曲', '织錦曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["大女身爲織錦戶，名在縣家供進簿。","長頭起樣呈作官，聞道官家中苦難。","回花側葉與人別，唯恐秋天絲線乾。","紅縷葳蕤紫茸軟，蝶飛參差花宛轉。","一梭聲盡重一梭，玉腕不停羅袖卷。","窗中夜久睡髻偏，橫釵欲墮垂著肩。","合衣臥時參沒後，停燈起在雞鳴前。","一匹千金亦不賣，限日未成宮裏怪。","錦江水涸貢轉多，宮中盡著單絲羅。","莫言山積無盡日，百丈高樓一曲歌。"]', '["大女身爲织錦戶，名在縣家供進簿。","长头起樣呈作官，闻道官家中苦难。","回花側葉與人別，唯恐秋天絲線乾。","紅縷葳蕤紫茸軟，蝶飞參差花宛轉。","一梭声尽重一梭，玉腕不停羅袖卷。","窗中夜久睡髻偏，橫釵欲墮垂著肩。","合衣臥时參沒後，停灯起在雞鳴前。","一匹千金亦不賣，限日未成宮裏怪。","錦江水涸貢轉多，宮中尽著單絲羅。","莫言山積無尽日，百丈高楼一曲歌。"]', '诗', 'shi', '', NULL, '織錦曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90abcad7-1574-4787-835d-802f9afd9437', '擣衣曲', '擣衣曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["月明中庭擣衣石，掩帷下堂來擣帛。","婦姑相對神力生，雙揎白腕調杵聲。","高樓敲玉節會成，家家不睡皆起聽。","秋天丁丁復凍凍，玉釵低昂衣帶動。","夜深月落冷如刀，濕著一雙纖手痛。","回編易裂看生熟，鴛鴦紋成水波曲。","重燒熨斗帖兩頭，與郎裁作迎寒裘。"]', '["月明中庭擣衣石，掩帷下堂来擣帛。","婦姑相对神力生，雙揎白腕調杵声。","高楼敲玉節會成，家家不睡皆起听。","秋天丁丁复凍凍，玉釵低昂衣带动。","夜深月落冷如刀，濕著一雙纖手痛。","回編易裂看生熟，鴛鴦紋成水波曲。","重燒熨斗帖兩头，與郎裁作迎寒裘。"]', '诗', 'shi', '', NULL, '擣衣曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9de0db-ce2e-4f00-8736-7eea7b2dcadb', '秋夜曲二首 一', '秋夜曲二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天清漏長霜泊泊，蘭綠收榮桂膏涸。","高樓雲鬟弄嬋娟，古瑟暗斷秋風弦。","玉關遙隔萬里道，金刀不翦雙淚泉。","香囊火死香氣少，向帷合眼何時曉。","城烏作營啼野月，秦州少婦生離別。"]', '["天清漏长霜泊泊，蘭綠收榮桂膏涸。","高楼云鬟弄嬋娟，古瑟暗斷秋风弦。","玉关遙隔万里道，金刀不翦雙泪泉。","香囊火死香氣少，向帷合眼何时晓。","城烏作營啼野月，秦州少婦生離別。"]', '诗', 'shi', '', NULL, '秋夜曲二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eb1dc7c-cb19-43e4-96d6-12b78af04b91', '秋夜曲二首 二', '秋夜曲二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["秋燈向壁掩洞房，良人此夜直明光。","天河悠悠漏水長，南樓北斗兩相當。"]', '["秋灯向壁掩洞房，良人此夜直明光。","天河悠悠漏水长，南楼北斗兩相當。"]', '诗', 'shi', '', NULL, '秋夜曲二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb9f6d7-d085-49dc-9124-4b47f27575eb', '題台州隱靜寺', '題台州隐静寺', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["隱靜靈仙寺天鑿，杯度飛來建巖壑。","五峰直上插銀河，一澗當空瀉寥廓。","崆峒黯淡碧琉璃，白雲吞吐紅蓮閣。","不知勢壓天幾重，鐘聲常聞月中落。"]', '["隐静靈仙寺天鑿，杯度飞来建巖壑。","五峰直上插銀河，一澗當空瀉寥廓。","崆峒黯淡碧琉璃，白云吞吐紅蓮閣。","不知勢壓天幾重，鐘声常闻月中落。"]', '诗', 'shi', '', NULL, '題台州隱靜寺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef994740-d876-4ef2-871b-2f4e337676d6', '送人遊塞', '送人游塞', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["初晴天墮絲，晚色上春枝。","城下路分處，邊頭人去時。","停車數行日，勸酒問回期。","亦是茫茫客，還從此別離。"]', '["初晴天墮絲，晚色上春枝。","城下路分处，邊头人去时。","停车數行日，勸酒问回期。","亦是茫茫客，還從此別離。"]', '诗', 'shi', '', NULL, '送人遊塞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a610134-8296-4b06-8db8-44806faa9a56', '塞上逢故人', '塞上逢故人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["百戰一身在，相逢白髮生。","何時得鄉信，每日算歸程。","走馬登寒壠，驅羊入廢城。","羌笳三兩曲，人醉海西營。"]', '["百戰一身在，相逢白髮生。","何时得乡信，每日算归程。","走马登寒壠，驱羊入廢城。","羌笳三兩曲，人醉海西營。"]', '诗', 'shi', '', NULL, '塞上逢故人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170cddac-82c2-423c-a1ed-f9f1e21b3e10', '南中', '南中', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天南多鳥聲，州縣半無城。","野市依蠻姓，山邨逐水名。","瘴煙沙上起，陰火雨中生。","獨有求珠客，年年入海行。"]', '["天南多鸟声，州縣半無城。","野市依蠻姓，山邨逐水名。","瘴煙沙上起，陰火雨中生。","独有求珠客，年年入海行。"]', '诗', 'shi', '', NULL, '南中 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3287bda-4b03-491e-af7a-63ee23c2b71d', '汴路水驛', '汴路水驛', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["晚泊水邊驛，柳塘初起風。","蛙鳴蒲葉下，魚入稻花中。","去舍已云遠，問程猶向東。","近來多怨別，不與少年同。"]', '["晚泊水邊驛，柳塘初起风。","蛙鳴蒲葉下，鱼入稻花中。","去舍已云远，问程猶向东。","近来多怨別，不與少年同。"]', '诗', 'shi', '', NULL, '汴路水驛 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d925f9e-839f-4683-a033-b927a43d1938', '淮南使廻留別竇侍御', '淮南使廻留別竇侍御', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["戀戀春恨結，綿綿淮草深。","病身愁至夜，遠道畏逢陰。","忽逐酒盃會，暫同風景心。","從今一分散，還是曉枝禽。"]', '["戀戀春恨結，綿綿淮草深。","病身愁至夜，远道畏逢陰。","忽逐酒盃會，暫同风景心。","從今一分散，還是晓枝禽。"]', '诗', 'shi', '', NULL, '淮南使廻留別竇侍御 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d4539c-2111-475f-9834-b502125a482b', '汴路即事', '汴路即事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["千里河煙直，青槐夾岸長。","天涯同此路，人語各殊方。","草市迎江貨，津橋稅海商。","廻看故宮柳，憔悴不成行。"]', '["千里河煙直，青槐夾岸长。","天涯同此路，人語各殊方。","草市迎江貨，津橋稅海商。","廻看故宮柳，憔悴不成行。"]', '诗', 'shi', '', NULL, '汴路即事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca5edd9f-b86c-46df-a7bc-9ada960961ec', '山居', '山居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["屋在瀑泉西，茅簷下有溪。","閉門留野鹿，分食養山雞。","桂熟長收子，蘭生不作畦。","初開洞中路，深處轉松梯。"]', '["屋在瀑泉西，茅簷下有溪。","閉门留野鹿，分食養山雞。","桂熟长收子，蘭生不作畦。","初开洞中路，深处轉松梯。"]', '诗', 'shi', '', NULL, '山居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4765f562-e574-40e2-85d5-bc946bd3d7c5', '醉後憶山中故人', '醉後憶山中故人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["花開草復秋，雲水自悠悠。","因醉暫無事，在山難免愁。","遇晴須看月，鬬健且登樓。","暗想山中伴，如今盡白頭。"]', '["花开草复秋，云水自悠悠。","因醉暫無事，在山难免愁。","遇晴須看月，鬬健且登楼。","暗想山中伴，如今尽白头。"]', '诗', 'shi', '', NULL, '醉後憶山中故人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a21cac65-f792-4c23-b9dd-2a26b0f4cb79', '送流人', '送流人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["見說長沙去，無親亦共愁。","陰雲鬼門夜，寒雨瘴江秋。","水國山魈引，蠻鄉洞主留。","漸看歸處遠，垂白住炎州。"]', '["见说长沙去，無親亦共愁。","陰云鬼门夜，寒雨瘴江秋。","水国山魈引，蠻乡洞主留。","漸看归处远，垂白住炎州。"]', '诗', 'shi', '', NULL, '送流人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6032689f-fa7e-4cce-986b-bcd9e827845e', '貧居', '貧居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["眼底貧家計，多時總莫嫌。","蠹生騰藥紙，字暗換書籤。","避雨拾黃葉，遮風下黑簾。","近來身不健，時就六壬占。"]', '["眼底貧家計，多时總莫嫌。","蠹生腾藥紙，字暗換书籤。","避雨拾黄葉，遮风下黑簾。","近来身不健，时就六壬占。"]', '诗', 'shi', '', NULL, '貧居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1cfbf4-0e02-42ae-a6d2-5308cc780b44', '過趙居士擬置草堂處所', '過趙居士擬置草堂处所', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["休師竹林北，空可兩三間。","雖愛獨居好，終來相伴閑。","猶嫌近前樹，爲礙看南山。","的有深耕處，春初須早還。"]', '["休師竹林北，空可兩三间。","雖愛独居好，終来相伴闲。","猶嫌近前樹，爲礙看南山。","的有深耕处，春初須早還。"]', '诗', 'shi', '', NULL, '過趙居士擬置草堂處所 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a81a19-8085-4d98-9f51-bdbc98b2b594', '新開望山處', '新开望山处', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新開望山處，今朝減病眠。","應移千里道，猶自數峰偏。","故欲遮春巷，還來遶暮天。","老夫行步弱，免到寺門前。"]', '["新开望山处，今朝減病眠。","應移千里道，猶自數峰偏。","故欲遮春巷，還来遶暮天。","老夫行步弱，免到寺门前。"]', '诗', 'shi', '', NULL, '新開望山處 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b716f4f8-b3d6-49b7-82a1-258948fa11ce', '題東華觀', '題东华观', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["路盡煙水外，院門題上清。","鶴雛靈解語，瓊葉軟無聲。","白髮道心熟，黃衣仙骨輕。"]', '["路尽煙水外，院门題上清。","鹤雛靈解語，瓊葉軟無声。","白髮道心熟，黄衣仙骨轻。"]', '诗', 'shi', '', NULL, '題東華觀 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71571557-6ab0-4cd7-b9f6-f5d3b991e7b2', '飯僧', '飯僧', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["別屋炊香飯，薰辛不入家。","溫泉調葛麵，淨手摘藤花。","蒲鮓除青葉，芹虀帶紫芽。","願師常伴食，消氣有薑茶。"]', '["別屋炊香飯，薰辛不入家。","溫泉調葛麵，淨手摘藤花。","蒲鮓除青葉，芹虀带紫芽。","願師常伴食，消氣有薑茶。"]', '诗', 'shi', '', NULL, '飯僧 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e2115b-2005-4ef0-8116-9731c8974e5b', '照鏡', '照镜', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["忽自見憔悴，壯年人亦疑。","髮緣多病落，力爲不行衰。","暖手揉雙目，看圖引四肢。","老來真愛道，所恨覺還遲。"]', '["忽自见憔悴，壯年人亦疑。","髮緣多病落，力爲不行衰。","暖手揉雙目，看圖引四肢。","老来真愛道，所恨覺還遲。"]', '诗', 'shi', '', NULL, '照鏡 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff29f941-f02a-4e39-a913-c8e8e4b30256', '歸昭應留別城中', '归昭應留別城中', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["喜得近京城，官卑意亦榮。","竝牀歡未定，離室思還生。","計拙偷閑住，經過買日行。","如無自來分，一驛是遙程。"]', '["喜得近京城，官卑意亦榮。","竝牀歡未定，離室思還生。","計拙偷闲住，經過買日行。","如無自来分，一驛是遙程。"]', '诗', 'shi', '', NULL, '歸昭應留別城中 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76a9e8e-c640-40b3-bf3d-dc0ca2985fe4', '答寄芙蓉冠子', '答寄芙蓉冠子', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一學芙蓉葉，初開映水幽。","雖經小兒手，不稱老夫頭。","枕上眠常戴，風前醉恐柔。","明年有閨閣，此樣必難求。"]', '["一学芙蓉葉，初开映水幽。","雖經小兒手，不稱老夫头。","枕上眠常戴，风前醉恐柔。","明年有閨閣，此樣必难求。"]', '诗', 'shi', '', NULL, '答寄芙蓉冠子 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b31ad9c-80b8-4451-853b-dddffb7869d8', '長安春遊', '长安春游', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["騎馬傍閑坊，新衣著雨香。","桃花紅粉醉，柳樹白雲狂。","不覺愁春去，何曾得日長。","牡丹相次發，城裏又須忙。"]', '["騎马傍闲坊，新衣著雨香。","桃花紅粉醉，柳樹白云狂。","不覺愁春去，何曾得日长。","牡丹相次發，城裏又須忙。"]', '诗', 'shi', '', NULL, '長安春遊 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d331180-0118-4958-aaca-e3592921811b', '冬夜感懷', '冬夜感懷', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["晚年恩愛少，耳目靜於僧。","竟夜不聞語，空房唯有燈。","氣噓寒被濕，霜入破窗凝。","斷得人間事，長如此亦能。"]', '["晚年恩愛少，耳目静於僧。","竟夜不闻語，空房唯有灯。","氣噓寒被濕，霜入破窗凝。","斷得人间事，长如此亦能。"]', '诗', 'shi', '', NULL, '冬夜感懷 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67affe1-5356-4f31-ae7a-aa5ce2d4156d', '初到昭應呈同僚', '初到昭應呈同僚', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["白髮初爲吏，有慙年少郎。","自知身上拙，不稱世間忙。","秋雨懸牆綠，暮山宮樹黃。","同官若容許，長借老僧房。"]', '["白髮初爲吏，有慙年少郎。","自知身上拙，不稱世间忙。","秋雨懸牆綠，暮山宮樹黄。","同官若容許，长借老僧房。"]', '诗', 'shi', '', NULL, '初到昭應呈同僚 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e4aa1a-c2f4-42d5-b201-a79b0d8229ae', '縣丞廳即事', '縣丞廳即事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宮殿半山上，人家高下居。","古廳眠受魘，老吏語多虛。","雨水洗荒竹，溪沙填廢渠。","聖朝收外府，皆自九天除。"]', '["宮殿半山上，人家高下居。","古廳眠受魘，老吏語多虛。","雨水洗荒竹，溪沙填廢渠。","聖朝收外府，皆自九天除。"]', '诗', 'shi', '', NULL, '縣丞廳即事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('689890f4-b6bf-444c-8377-2ef92457a284', '閑居即事', '闲居即事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["老病貪光景，尋常不下簾。","妻愁耽酒僻，人怪考詩嚴。","小婢偷紅紙，嬌兒弄白髯。","有時看舊卷，未免意中嫌。"]', '["老病貪光景，尋常不下簾。","妻愁耽酒僻，人怪考诗嚴。","小婢偷紅紙，嬌兒弄白髯。","有时看旧卷，未免意中嫌。"]', '诗', 'shi', '', NULL, '閑居即事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5320c3fa-65c0-4a38-bf28-8979e634bdac', '林居', '林居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["荒林四面通，門在野田中。","頑僕長如客，貧居未勝蓬。","舊綿衣不煖，新草屋多風。","唯去山南近，閑親販藥翁。"]', '["荒林四面通，门在野田中。","頑僕长如客，貧居未勝蓬。","旧綿衣不煖，新草屋多风。","唯去山南近，闲親販藥翁。"]', '诗', 'shi', '', NULL, '林居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b527b410-01c6-48d3-927a-75a83d29e133', '原上新居十三首 一', '原上新居十三首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新占原頭地，本無山可歸。","荒藤生葉晚，老杏著花稀。","廚舍近泥竈，家人初飽薇。","弟兄今四散，何日更相依。"]', '["新占原头地，本無山可归。","荒藤生葉晚，老杏著花稀。","廚舍近泥竈，家人初飽薇。","弟兄今四散，何日更相依。"]', '诗', 'shi', '', NULL, '原上新居十三首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5209a20-95ea-4d32-8c8c-5f923d3a83a1', '原上新居十三首 二', '原上新居十三首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一家榆柳新，四面遠無鄰。","人少愁聞病，莊孤幸得貧。","耕牛長願飽，樵僕每憐勤。","終日憂衣食，何由[脫]此身。"]', '["一家榆柳新，四面远無鄰。","人少愁闻病，莊孤幸得貧。","耕牛长願飽，樵僕每怜勤。","終日憂衣食，何由[脫]此身。"]', '诗', 'shi', '', NULL, '原上新居十三首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3732f10-c783-447f-be17-1e6368c107c7', '原上新居十三首 三', '原上新居十三首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長安無舊識，百里是天涯。","寂寞思逢客，荒涼喜見花。","訪僧求賤藥，將馬中豪家。","乍得新蔬菜，朝盤忽覺奢。"]', '["长安無旧識，百里是天涯。","寂寞思逢客，荒涼喜见花。","訪僧求賤藥，將马中豪家。","乍得新蔬菜，朝盤忽覺奢。"]', '诗', 'shi', '', NULL, '原上新居十三首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a676b731-62c9-4e8b-9ca1-5b543cb1aa7a', '原上新居十三首 四', '原上新居十三首 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雞鳴村舍遙，花發亦蕭條。","野竹初生笋，溪田未得苗。","家貧僮僕瘦，春冷菜蔬焦。","甘分長如此，無名在聖朝。"]', '["雞鳴村舍遙，花發亦蕭條。","野竹初生笋，溪田未得苗。","家貧僮僕瘦，春冷菜蔬焦。","甘分长如此，無名在聖朝。"]', '诗', 'shi', '', NULL, '原上新居十三首 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('913c9b6d-d12a-4fb7-b56a-2fca16d7074c', '原上新居十三首 五', '原上新居十三首 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春來梨棗盡，啼哭小兒飢。","鄰富雞常去，莊貧客漸稀。","借牛畊地晚，賣樹納錢遲。","牆下當官路，依山補竹籬。"]', '["春来梨棗尽，啼哭小兒飢。","鄰富雞常去，莊貧客漸稀。","借牛畊地晚，賣樹納錢遲。","牆下當官路，依山補竹籬。"]', '诗', 'shi', '', NULL, '原上新居十三首 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b17bd7e-2016-4e0d-8975-ff7a3e9b7d5d', '原上新居十三首 六', '原上新居十三首 六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自埽一間房，唯鋪獨臥牀。","野羹溪菜滑，山紙水苔香。","陳藥初和白，新經未入黃。","近來心力少，休讀養生方。"]', '["自埽一间房，唯鋪独臥牀。","野羹溪菜滑，山紙水苔香。","陳藥初和白，新經未入黄。","近来心力少，休读養生方。"]', '诗', 'shi', '', NULL, '原上新居十三首 六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c7bedba-c2eb-4bba-ae14-eb6e3c6bb708', '原上新居十三首 七', '原上新居十三首 七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["擬作讀經人，空房置淨巾。","鎖茶藤篋密，曝藥竹牀新。","老病應隨業，因緣不離身。","焚香向居士，無計出諸塵。"]', '["擬作读經人，空房置淨巾。","鎖茶藤篋密，曝藥竹牀新。","老病應隨業，因緣不離身。","焚香向居士，無計出諸塵。"]', '诗', 'shi', '', NULL, '原上新居十三首 七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e74f786-a48a-477c-a887-601347607cdb', '原上新居十三首 八', '原上新居十三首 八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["移家近住邨，貧苦自安存。","細問梨果植，遠求花藥根。","倩人開廢井，趂犢入新園。","長愛當山立，黃昏不閉門。"]', '["移家近住邨，貧苦自安存。","細问梨果植，远求花藥根。","倩人开廢井，趂犢入新园。","长愛當山立，黄昏不閉门。"]', '诗', 'shi', '', NULL, '原上新居十三首 八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b5ed30e-8934-448f-855c-22420981dc3c', '原上新居十三首 九', '原上新居十三首 九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["和煖遶林行，新貧足喜聲。","埽渠憂竹旱，澆地引蘭生。","山客憑栽樹，家僮使入城。","門前粉壁上，書著縣官名。"]', '["和煖遶林行，新貧足喜声。","埽渠憂竹旱，澆地引蘭生。","山客憑栽樹，家僮使入城。","门前粉壁上，书著縣官名。"]', '诗', 'shi', '', NULL, '原上新居十三首 九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc4e7eb-372c-4b4e-86e1-c578c85bf9ae', '原上新居十三首 十', '原上新居十三首 十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["住處鐘鼓外，免爭當路橋。","身閑時却困，兒病可來嬌。","雞睡日陽暖，蜂狂花豔燒。","長安足門戶，疊疊看登朝。"]', '["住处鐘鼓外，免爭當路橋。","身闲时却困，兒病可来嬌。","雞睡日陽暖，蜂狂花豔燒。","长安足门戶，叠叠看登朝。"]', '诗', 'shi', '', NULL, '原上新居十三首 十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6dff067-8bb1-488f-a875-388a885e1a1e', '原上新居十三首 十一', '原上新居十三首 十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["近來年紀到，世事總無心。","古碣憑人搨，閑詩任客吟。","送經還野苑，移石入幽林。","谷口春風惡，梨花蓋地深。"]', '["近来年紀到，世事總無心。","古碣憑人搨，闲诗任客吟。","送經還野苑，移石入幽林。","谷口春风惡，梨花蓋地深。"]', '诗', 'shi', '', NULL, '原上新居十三首 十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8661bc2-6231-467f-a0ea-00e9cc151d28', '原上新居十三首 十二', '原上新居十三首 十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["嬾更學諸餘，林中埽地居。","膩衣穿不洗，白髮短慵梳。","苦相常多淚，勞生自悟虛。","閑行人事絕，親故亦無書。"]', '["嬾更学諸餘，林中埽地居。","膩衣穿不洗，白髮短慵梳。","苦相常多泪，勞生自悟虛。","闲行人事絕，親故亦無书。"]', '诗', 'shi', '', NULL, '原上新居十三首 十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5569d79a-ee47-493e-9582-558649e6d148', '原上新居十三首 十三', '原上新居十三首 十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["住處去山近，傍園麋鹿行。","野桑穿井長，荒竹過牆生。","新識鄰里面，未諳邨社情。","石田無力及，賤賃與人耕。"]', '["住处去山近，傍园麋鹿行。","野桑穿井长，荒竹過牆生。","新識鄰里面，未諳邨社情。","石田無力及，賤賃與人耕。"]', '诗', 'shi', '', NULL, '原上新居十三首 十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c508294-ca48-4936-a8c2-770107340b73', '送李評事使蜀', '送李評事使蜀', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["勸酒不依巡，明朝萬里人。","轉江雲棧細，近驛板橋新。","石冷啼猿影，松昏戲鹿塵。","少年爲客好，況是益州春。"]', '["勸酒不依巡，明朝万里人。","轉江云棧細，近驛板橋新。","石冷啼猿影，松昏戲鹿塵。","少年爲客好，況是益州春。"]', '诗', 'shi', '', NULL, '送李評事使蜀 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed188d5-5225-4dc9-a6c4-a0f563debecd', '新修道居', '新修道居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["世間無所入，學道處新成。","兩面有山色，六時聞磬聲。","閑加經遍數，老愛字分明。","若得離煩惱，焚香過一生。"]', '["世间無所入，学道处新成。","兩面有山色，六时闻磬声。","闲加經遍數，老愛字分明。","若得離煩惱，焚香過一生。"]', '诗', 'shi', '', NULL, '新修道居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68e6b2b5-5a33-40a2-8396-b5b339e5ffdf', '贈洪誓師', '贈洪誓師', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["老僧真古畫，閑坐語中聽。","識病方書聖，諳山草木靈。","人來多施藥，願滿不持經。","相伴尋溪竹，秋苔襪履青。"]', '["老僧真古畫，闲坐語中听。","識病方书聖，諳山草木靈。","人来多施藥，願满不持經。","相伴尋溪竹，秋苔襪履青。"]', '诗', 'shi', '', NULL, '贈洪誓師 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d6a9a4-7c86-48b3-82d4-1a77459910a4', '題法雲禪院僧', '題法云禪院僧', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["不剃頭多日，禪來白髮長。","合邨迎住寺，同學乞修房。","覺少持經力，憂無養病糧。","上山猶得在，自解衲衣裳。"]', '["不剃头多日，禪来白髮长。","合邨迎住寺，同学乞修房。","覺少持經力，憂無養病糧。","上山猶得在，自解衲衣裳。"]', '诗', 'shi', '', NULL, '題法雲禪院僧 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32bc0af6-a95d-426f-b82e-515b24a19b32', '贈溪翁', '贈溪翁', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["溪田借四鄰，不省解憂身。","看日和仙藥，書符救病人。","伴僧齋過夏，中酒臥經旬。","應得丹砂力，春來黑髮新。"]', '["溪田借四鄰，不省解憂身。","看日和仙藥，书符救病人。","伴僧斋過夏，中酒臥經旬。","應得丹砂力，春来黑髮新。"]', '诗', 'shi', '', NULL, '贈溪翁 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da6446b-3c9d-4633-9fa5-77f28f08b288', '謝李續主簿', '謝李續主簿', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["館舍幸相近，因風及病身。","一官雖隔水，四韵是同人。","衰臥朦朧曉，貧居冷落春。","少年無不好，莫恨滿頭塵。"]', '["館舍幸相近，因风及病身。","一官雖隔水，四韵是同人。","衰臥朦朧晓，貧居冷落春。","少年無不好，莫恨满头塵。"]', '诗', 'shi', '', NULL, '謝李續主簿 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f8a7344-8981-46af-acdf-48ce14c9ce5e', '寒食', '寒食', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["田舍清明日，家家出火遲。","白衫眠古巷，紅索搭高枝。","紗帶生難結，銅釵重欲垂。","斬新衣踏盡，還似去年時。"]', '["田舍清明日，家家出火遲。","白衫眠古巷，紅索搭高枝。","紗带生难結，銅釵重欲垂。","斬新衣踏尽，還似去年时。"]', '诗', 'shi', '', NULL, '寒食 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2886c09d-4cb4-43cd-a608-20d0c55892d8', '貽小尼師', '貽小尼師', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新剃青頭髮，生來未埽眉。","身輕禮拜穩，心慢記經遲。","喚起猶侵曉，催齋已過時。","春晴堦下立，私地弄花枝。"]', '["新剃青头髮，生来未埽眉。","身轻禮拜穩，心慢記經遲。","喚起猶侵晓，催斋已過时。","春晴堦下立，私地弄花枝。"]', '诗', 'shi', '', NULL, '貽小尼師 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0a4993-92cd-441c-9de5-b501acd4101c', '惜歡', '惜歡', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["當歡須且歡，過後買應難。","歲去停燈守，花開把火看。","狂來欺酒淺，愁盡覺天寬。","次第頭皆白，齊年人已殘。"]', '["當歡須且歡，過後買應难。","歲去停灯守，花开把火看。","狂来欺酒淺，愁尽覺天寬。","次第头皆白，齊年人已殘。"]', '诗', 'shi', '', NULL, '惜歡 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037361bc-7010-45e5-8818-d5cf63da147c', '山中惜花', '山中惜花', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["忽看花漸稀，罪過酒醒時。","尋覓風來處，驚張夜落時。","遊絲纏故蘂，宿夜守空枝。","開取當軒地，年年樹底期。"]', '["忽看花漸稀，罪過酒醒时。","尋覓风来处，驚張夜落时。","游絲纏故蘂，宿夜守空枝。","开取當軒地，年年樹底期。"]', '诗', 'shi', '', NULL, '山中惜花 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41e61ce-7618-475f-96e1-9b9491696f4a', '和武門下傷韋令孔雀', '和武门下傷韋令孔雀', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["孤號秋閣陰，韋令在時禽。","覓伴海山黑，思鄉橘柚深。","舉頭聞舊曲，顧尾惜殘金。","顦顇不飛去，重君池上心。"]', '["孤號秋閣陰，韋令在时禽。","覓伴海山黑，思乡橘柚深。","舉头闻旧曲，顧尾惜殘金。","顦顇不飞去，重君池上心。"]', '诗', 'shi', '', NULL, '和武門下傷韋令孔雀 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd29e82-2daa-46ea-accd-ffaeb0642e75', '題所賃宅牡丹花', '題所賃宅牡丹花', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["賃宅得花饒，初開恐是妖。","粉光深紫膩，肉色退紅嬌。","且願風留著，惟愁日炙燋。","可憐零落蘂，收取作香燒。"]', '["賃宅得花饒，初开恐是妖。","粉光深紫膩，肉色退紅嬌。","且願风留著，惟愁日炙燋。","可怜零落蘂，收取作香燒。"]', '诗', 'shi', '', NULL, '題所賃宅牡丹花 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7fb06b2-a9ea-4271-a01d-cab3ca65376b', '隱者居', '隐者居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["山人住處高。","看日上蟠桃，雪縷青山脈。","雲生白鶴毛，朱書護身咒。","水噀斷邪刀，何物中長食。","胡麻慢火熬。"]', '["山人住处高。","看日上蟠桃，雪縷青山脈。","云生白鹤毛，朱书護身咒。","水噀斷邪刀，何物中长食。","胡麻慢火熬。"]', '诗', 'shi', '', NULL, '隱者居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0afd3bc9-7bed-4bad-ad80-20e5d730ffaa', '昭應官舍', '昭應官舍', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["繞廳春草合，知道縣家閑。","行見雨遮院，臥看人上山。","避風新浴後，請假未醒間。","朝客輕卑吏，從他不往還。"]', '["繞廳春草合，知道縣家闲。","行见雨遮院，臥看人上山。","避风新浴後，請假未醒间。","朝客轻卑吏，從他不往還。"]', '诗', 'shi', '', NULL, '昭應官舍 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c4b92a4-cee6-42ee-8135-c9f00960cd76', '送嚴大夫赴桂州', '送嚴大夫赴桂州', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["嶺頭分界候，一半屬湘潭。","水驛門旗出，山巒洞主參。","辟邪犀角重，解酒荔枝甘。","莫歎京華遠，安南更有南。"]', '["嶺头分界候，一半屬湘潭。","水驛门旗出，山巒洞主參。","辟邪犀角重，解酒荔枝甘。","莫歎京华远，安南更有南。"]', '诗', 'shi', '', NULL, '送嚴大夫赴桂州 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea646ac3-707d-4278-ae94-151dbfec3d65', '望行人', '望行人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自從江樹秋，日日望江樓。","夢見離珠浦，書來在桂州。","不同魚比目，終恨水分流。","久不開明鏡，多應是白頭。"]', '["自從江樹秋，日日望江楼。","梦见離珠浦，书来在桂州。","不同鱼比目，終恨水分流。","久不开明镜，多應是白头。"]', '诗', 'shi', '', NULL, '望行人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eedd100-e0e3-4dd3-9d6c-dfa2ef4090aa', '塞上', '塞上', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["漫漫復淒淒，黃沙暮漸迷。","人當故鄉立，馬過舊營嘶。","斷雁逢冰磧，回軍占雪溪。","夜來山下哭，應是送降奚。"]', '["漫漫复淒淒，黄沙暮漸迷。","人當故乡立，马過旧營嘶。","斷雁逢冰磧，回軍占雪溪。","夜来山下哭，應是送降奚。"]', '诗', 'shi', '', NULL, '塞上 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60b400e0-ad92-455c-bd50-e6c2f1cfaf88', '杜中丞書院新移小竹', '杜中丞书院新移小竹', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["此地本無竹，遠從山寺移。","經年求養法，隔日記澆時。","嫩綠卷新葉，殘黃收故枝。","色輕寒不動，聲與靜相宜。","愛護出常數，稀稠看自知。","貧來緣未有，客散獨行遲。"]', '["此地本無竹，远從山寺移。","經年求養法，隔日記澆时。","嫩綠卷新葉，殘黄收故枝。","色轻寒不动，声與静相宜。","愛護出常數，稀稠看自知。","貧来緣未有，客散独行遲。"]', '诗', 'shi', '', NULL, '杜中丞書院新移小竹 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b8f479-c19c-42d9-ab71-4bc9d67136a7', '同于汝錫賞白牡丹', '同于汝錫賞白牡丹', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["曉日花初吐，春寒白未凝。","月光裁不得，蘇合點難勝。","柔膩於雲葉，新鮮掩鶴膺。","統心黃倒暈，側莖紫重稜。","乍斂看如睡，初開問欲譍。","竝香幽蕙死，比豔美人憎。","價數千金貴，形相兩眼疼。","自知顏色好，愁被彩光凌。"]', '["晓日花初吐，春寒白未凝。","月光裁不得，蘇合点难勝。","柔膩於云葉，新鲜掩鹤膺。","統心黄倒暈，側莖紫重稜。","乍斂看如睡，初开问欲譍。","竝香幽蕙死，比豔美人憎。","價數千金貴，形相兩眼疼。","自知顏色好，愁被彩光凌。"]', '诗', 'shi', '', NULL, '同于汝錫賞白牡丹 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07767a89-9e4b-4fd7-a149-d87ece400a3e', '送吳郎中赴忠州', '送吳郎中赴忠州', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["西臺復南省，清白上天知。","家每因窮散，官多爲直移。","遙邊過驛近，買藥出城遲。","朝野憑人別，親情伴酒悲。","故園愁去後，白髮想迴時。","何處忠州界，山頭卓望旗。"]', '["西台复南省，清白上天知。","家每因窮散，官多爲直移。","遙邊過驛近，買藥出城遲。","朝野憑人別，親情伴酒悲。","故园愁去後，白髮想迴时。","何处忠州界，山头卓望旗。"]', '诗', 'shi', '', NULL, '送吳郎中赴忠州 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bd7eeb9-42b1-4c44-8ac5-93cce080ddc4', '照鏡', '照镜', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["終日自纏繞，此身無適緣。","萬愁生旅夜，百病湊衰年。","少睡憎明屋，慵行待暖天。","癢頭梳有蝨，風耳炙聞蟬。","搖白方多錯，迴金法不全。","家貧何所戀，時在老僧邊。"]', '["終日自纏繞，此身無適緣。","万愁生旅夜，百病湊衰年。","少睡憎明屋，慵行待暖天。","癢头梳有蝨，风耳炙闻蟬。","搖白方多錯，迴金法不全。","家貧何所戀，时在老僧邊。"]', '诗', 'shi', '', NULL, '照鏡 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9dba129-cabd-4083-9fe5-d3ace11ed2d4', '秋日送杜虔州', '秋日送杜虔州', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["憶得宿新宅，別來餘蕙香。","初聞守郡遠，一日臥空牀。","野驛煙火濕，路人消息狂。","山樓添鼓角，村柵立旗槍。","晚渚露荷敗，早衙風桂涼。","謝家章句出，江月少輝光。"]', '["憶得宿新宅，別来餘蕙香。","初闻守郡远，一日臥空牀。","野驛煙火濕，路人消息狂。","山楼添鼓角，村柵立旗槍。","晚渚露荷敗，早衙风桂涼。","謝家章句出，江月少輝光。"]', '诗', 'shi', '', NULL, '秋日送杜虔州 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfd67f3-45f7-404f-a5b2-f25e123508ea', '送鄭權尚書南海', '送鄭權尚书南海', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["七郡雙旌貴，人皆不憶廻。","戍頭龍腦鋪，關口象牙堆。","勅設熏鑪出，蠻辭咒節開。","市喧山賊破，金賤海船來。","白氎家家織，紅蕉處處栽。","已將身報國，莫起望鄉臺。"]', '["七郡雙旌貴，人皆不憶廻。","戍头龙腦鋪，关口象牙堆。","勅設熏鑪出，蠻辞咒節开。","市喧山賊破，金賤海船来。","白氎家家织，紅蕉处处栽。","已將身報国，莫起望乡台。"]', '诗', 'shi', '', NULL, '送鄭權尚書南海 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebf0dea4-9e91-44d1-aefc-af34b36b8277', '題別遺愛草堂兼呈李十使君', '題別遺愛草堂兼呈李十使君', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["曾住鑪峰下，書堂對藥臺。","斬新蘿徑合，依舊竹牕開。","砌水親看決，池荷手自栽。","五年方蹔至，一宿又須回。","縱未長歸得，猶勝不到來。","君家白鹿洞，聞道亦生苔。"]', '["曾住鑪峰下，书堂对藥台。","斬新蘿徑合，依旧竹牕开。","砌水親看決，池荷手自栽。","五年方蹔至，一宿又須回。","縱未长归得，猶勝不到来。","君家白鹿洞，闻道亦生苔。"]', '诗', 'shi', '', NULL, '題別遺愛草堂兼呈李十使君 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e7315fd-cae3-4fa8-84d1-bcc1e8dc300a', '賞牡丹', '賞牡丹', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["此花名價別，開豔益皇都。","香遍苓菱死，紅燒躑躅枯。","軟光籠細脈，妖色暖鮮膚。","滿蘂攢黃粉，含稜縷絳蘇。","好和薰御服，堪畫入宮圖。","晚態愁新婦，殘粧望病夫。","教人知箇數，留客賞斯須。","一夜輕風起，千金買亦無。"]', '["此花名價別，开豔益皇都。","香遍苓菱死，紅燒躑躅枯。","軟光籠細脈，妖色暖鲜膚。","满蘂攢黄粉，含稜縷絳蘇。","好和薰御服，堪畫入宮圖。","晚態愁新婦，殘粧望病夫。","教人知箇數，留客賞斯須。","一夜轻风起，千金買亦無。"]', '诗', 'shi', '', NULL, '賞牡丹 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb4a72fa-c1f2-4ce1-936b-ae3c6c947faf', '贈王樞密', '贈王樞密', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["三朝行坐鎮相隨，今上春宮見小時。","脫下御衣先賜著，進來龍馬每教騎。","長承密旨歸家少，獨奏邊機出殿遲。","自是姓同親向說，九重爭得外人知。"]', '["三朝行坐鎮相隨，今上春宮见小时。","脫下御衣先賜著，進来龙马每教騎。","长承密旨归家少，独奏邊機出殿遲。","自是姓同親向说，九重爭得外人知。"]', '诗', 'shi', '', NULL, '贈王樞密 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('819e5bd5-ce98-460f-8c8a-508dd91722a7', '早秋過龍武李將軍書齋', '早秋過龙武李將軍书斋', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["高樹蟬聲秋巷裏，朱門冷靜似閑居。","重裝墨畫數莖竹，長著香薰一架書。","語笑侍兒知禮數，吟哦野客任狂疎。","就中愛讀英雄傳，欲立功勳恐不如。"]', '["高樹蟬声秋巷裏，朱门冷静似闲居。","重裝墨畫數莖竹，长著香薰一架书。","語笑侍兒知禮數，吟哦野客任狂疎。","就中愛读英雄傳，欲立功勳恐不如。"]', '诗', 'shi', '', NULL, '早秋過龍武李將軍書齋 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9525f6-c284-4172-82b9-636057029200', '江陵即事', '江陵即事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["瘴雲梅雨不成泥，十里津樓壓大堤。","蜀女下沙迎水客，巴童傍驛賣山雞。","寺多紅藥燒人眼，地足青苔染馬蹄。","夜半獨眠愁在遠，北看歸路隔蠻溪。"]', '["瘴云梅雨不成泥，十里津楼壓大堤。","蜀女下沙迎水客，巴童傍驛賣山雞。","寺多紅藥燒人眼，地足青苔染马蹄。","夜半独眠愁在远，北看归路隔蠻溪。"]', '诗', 'shi', '', NULL, '江陵即事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0824f0c-e549-40e8-b9a5-5f3b4ca18bc7', '題花子贈渭州陳判官', '題花子贈渭州陳判官', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["膩如雲母輕如粉，豔勝香黃薄勝蟬。","點綠斜蒿新葉嫩，添紅石竹晚花鮮。","鴛鴦比翼人初帖，蛺蝶重飛樣未傳。","況復蕭郎有情思，可憐春日鏡臺前。"]', '["膩如云母轻如粉，豔勝香黄薄勝蟬。","点綠斜蒿新葉嫩，添紅石竹晚花鲜。","鴛鴦比翼人初帖，蛺蝶重飞樣未傳。","況复蕭郎有情思，可怜春日镜台前。"]', '诗', 'shi', '', NULL, '題花子贈渭州陳判官 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b546d9e2-8528-4aef-9b4c-3ccedfe647d1', '送從姪擬赴江陵少尹', '送從姪擬赴江陵少尹', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["江陵少尹好閑官，親故皆來勸自寬。","無事日長貧不易，有才年少屈終難。","沙頭欲買紅螺盞，渡口多呈白角盤。","應向章華臺下醉，莫衝雲雨夜深寒。"]', '["江陵少尹好闲官，親故皆来勸自寬。","無事日长貧不易，有才年少屈終难。","沙头欲買紅螺盞，渡口多呈白角盤。","應向章华台下醉，莫衝云雨夜深寒。"]', '诗', 'shi', '', NULL, '送從姪擬赴江陵少尹 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1c0571b-40e4-43a1-9561-53f27eb82192', '華清宮感舊', '华清宮感旧', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["塵到朝元邊使急，千官夜發六龍回。","輦前月照羅衫淚，馬上風吹蠟燭灰。","公主妝樓金鎖澀，貴妃湯殿玉蓮開。","有時雲外聞天樂，知是先皇沐浴來。"]', '["塵到朝元邊使急，千官夜發六龙回。","輦前月照羅衫泪，马上风吹蠟燭灰。","公主妝楼金鎖澀，貴妃湯殿玉蓮开。","有时云外闻天乐，知是先皇沐浴来。"]', '诗', 'shi', '', NULL, '華清宮感舊 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d98471-ce0f-453e-bf72-f0bb99823825', '九仙公主舊莊', '九仙公主旧莊', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["仙居五里外門西，石路親回御馬蹄。","天使來栽宮裏樹，羅衣自買院前溪。","野牛行傍澆花井，本主分將灌藥畦。","樓上鳳皇飛去後，白雲紅葉屬山雞。"]', '["仙居五里外门西，石路親回御马蹄。","天使来栽宮裏樹，羅衣自買院前溪。","野牛行傍澆花井，本主分將灌藥畦。","楼上鳳皇飞去後，白云紅葉屬山雞。"]', '诗', 'shi', '', NULL, '九仙公主舊莊 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd3d8c0-1ed1-4f37-8580-5d4b67100e91', '郭家溪亭', '郭家溪亭', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["高亭望見長安樹，春草岡西舊院斜。","光動綠煙遮岸行，粉開紅豔塞溪花。","野泉聞洗親王馬，古柳曾停貴主車。","妝閣書樓傾側盡，雲山新賣與官家。"]', '["高亭望见长安樹，春草岡西旧院斜。","光动綠煙遮岸行，粉开紅豔塞溪花。","野泉闻洗親王马，古柳曾停貴主车。","妝閣书楼傾側尽，云山新賣與官家。"]', '诗', 'shi', '', NULL, '郭家溪亭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7545545f-e9d3-4382-a987-89262e9fd3ae', '題金家竹溪', '題金家竹溪', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["少年因病離天仗，乞得歸家自養身。","買斷竹溪無別主，散分泉水與新鄰。","山頭鹿下長驚犬，池面魚行不怕人。","鄉使到來常欵語，還聞世上有功臣。"]', '["少年因病離天仗，乞得归家自養身。","買斷竹溪無別主，散分泉水與新鄰。","山头鹿下长驚犬，池面鱼行不怕人。","乡使到来常欵語，還闻世上有功臣。"]', '诗', 'shi', '', NULL, '題金家竹溪 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00e1a8d-1d74-436a-8331-8624fd11038a', '題應聖觀', '題應聖观', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["精思堂上畫三身，回作仙宮度美人。","賜額御書金字貴，行香天樂羽衣新。","空廊鳥啄花甎縫，小殿蟲緣玉像塵。","頭白女冠猶說得，薔薇不似已前春。"]', '["精思堂上畫三身，回作仙宮度美人。","賜額御书金字貴，行香天乐羽衣新。","空廊鸟啄花甎縫，小殿蟲緣玉像塵。","头白女冠猶说得，薔薇不似已前春。"]', '诗', 'shi', '', NULL, '題應聖觀 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05d134f-f7c0-487e-972d-94bbe2618421', '同于汝錫遊降聖觀', '同于汝錫游降聖观', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["秦時桃樹滿山坡，騎鹿先生降大羅。","路盡溪頭逢地少，門連內裏見天多。","荒泉壞簡朱砂暗，古塔殘經篆字訛。","聞說開元齋醮日，曉移行漏帝親過。"]', '["秦时桃樹满山坡，騎鹿先生降大羅。","路尽溪头逢地少，门連內裏见天多。","荒泉壞簡朱砂暗，古塔殘經篆字訛。","闻说开元斋醮日，晓移行漏帝親過。"]', '诗', 'shi', '', NULL, '同于汝錫遊降聖觀 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72cf81fc-6d8c-41e2-b6f8-f7496dfdfbe7', '逍遙翁溪亭', '逍遙翁溪亭', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["逍遙翁在此裴回，帝改溪名起石臺。","車馬到春常借問，子孫因選暫歸來。","稀疎野竹人移折，零落蕉花雨打開。","無主青山何所直，賣供官稅不如灰。"]', '["逍遙翁在此裴回，帝改溪名起石台。","车马到春常借问，子孫因選暫归来。","稀疎野竹人移折，零落蕉花雨打开。","無主青山何所直，賣供官稅不如灰。"]', '诗', 'shi', '', NULL, '逍遙翁溪亭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4240c8a-839e-4e98-b130-f652b553649a', '尋李山人不遇', '尋李山人不遇', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["山客長須少在時，溪中放鶴洞中碁。","生金有氣尋還遠，仙藥成窠見即移。","莫爲無家陪寺食，應緣將米寄人炊。","從頭石上留名去，獨向南峰問老師。"]', '["山客长須少在时，溪中放鹤洞中碁。","生金有氣尋還远，仙藥成窠见即移。","莫爲無家陪寺食，應緣將米寄人炊。","從头石上留名去，独向南峰问老師。"]', '诗', 'shi', '', NULL, '尋李山人不遇 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9dec966-d9d8-4189-8c9e-4003a3b74981', '題石甕寺', '題石甕寺', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["青崖白石夾城東，泉脈鐘聲內裏通。","地壓龍蛇山色別，屋連宮殿匠名同。","簷燈經夏紗籠黑，溪葉先秋臘樹紅。","天子親題詩總在，畫扉長鏁碧龕中。"]', '["青崖白石夾城东，泉脈鐘声內裏通。","地壓龙蛇山色別，屋連宮殿匠名同。","簷灯經夏紗籠黑，溪葉先秋臘樹紅。","天子親題诗總在，畫扉长鏁碧龕中。"]', '诗', 'shi', '', NULL, '題石甕寺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b945c419-d274-4b24-b2f4-6098bd7413dd', '早登西禪寺閣', '早登西禪寺閣', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["上方臺殿第三層，朝壁紅窗日氣凝。","煙霧開時分遠寺，山川晴處見崇陵。","沙灣漾水圖新粉，綠野荒阡暈色繒。","莫說城南月燈閣，自諸樓看總難勝。"]', '["上方台殿第三層，朝壁紅窗日氣凝。","煙霧开时分远寺，山川晴处见崇陵。","沙灣漾水圖新粉，綠野荒阡暈色繒。","莫说城南月灯閣，自諸楼看總难勝。"]', '诗', 'shi', '', NULL, '早登西禪寺閣 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe949c81-1d23-4cb2-b163-be7405a84d91', '題江寺兼求藥子', '題江寺兼求藥子', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["隋朝舊寺楚江頭，深謝師僧引客遊。","空賞野花無過夜，若看琪樹即須秋。","紅珠落地求誰與，青角垂階自不收。","願乞野人三兩粒，歸家將助小庭幽。"]', '["隋朝旧寺楚江头，深謝師僧引客游。","空賞野花無過夜，若看琪樹即須秋。","紅珠落地求誰與，青角垂階自不收。","願乞野人三兩粒，归家將助小庭幽。"]', '诗', 'shi', '', NULL, '題江寺兼求藥子 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b8ac5d5-09f9-4a42-9e7c-453445ad25a4', '題詵法師院', '題詵法師院', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["三年說戒龍宮裏，巡禮還來向水行。","多愛貧窮人遠請，長修破落寺先成。","秋天盆底新荷色，夜地房前小竹聲。","僧院不求諸處好，轉經唯有一窗明。"]', '["三年说戒龙宮裏，巡禮還来向水行。","多愛貧窮人远請，长修破落寺先成。","秋天盆底新荷色，夜地房前小竹声。","僧院不求諸处好，轉經唯有一窗明。"]', '诗', 'shi', '', NULL, '題詵法師院 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f93ba4fe-2aa4-4afb-9481-dc36cfaedd57', '酬于汝錫曉雪見寄', '酬于汝錫晓雪见寄', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["欲明天色白漫漫，打葉穿簾雪未乾。","薄落堦前人踏盡，差池樹裏鳥銜殘。","旋銷迎暖沾牆少，斜舞遮春到地難。","勞動更裁新樣綺，紅燈一夜剪刀寒。"]', '["欲明天色白漫漫，打葉穿簾雪未乾。","薄落堦前人踏尽，差池樹裏鸟銜殘。","旋銷迎暖沾牆少，斜舞遮春到地难。","勞动更裁新樣綺，紅灯一夜剪刀寒。"]', '诗', 'shi', '', NULL, '酬于汝錫曉雪見寄 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2367a6c8-4685-4c38-98c8-bb4bafac2ab5', '從軍後寄山中友人', '從軍後寄山中友人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["愛仙無藥住溪貧，脫却山衣事漢臣。","夜半聽雞梳白髮，天明走馬入紅塵。","村童近去嫌腥食，野鶴高飛避俗人。","勞動先生遠相示，別來弓箭不離身。"]', '["愛仙無藥住溪貧，脫却山衣事漢臣。","夜半听雞梳白髮，天明走马入紅塵。","村童近去嫌腥食，野鹤高飞避俗人。","勞动先生远相示，別来弓箭不離身。"]', '诗', 'shi', '', NULL, '從軍後寄山中友人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a2699ac-c6ea-4674-b778-637a98cd6152', '寄汴州令狐相公', '寄汴州令狐相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["三軍江口擁雙旌，虎帳長開自教兵。","機鏁惡徒狂寇盡，恩驅老將壯心生。","水門向晚茶商鬧，橋市通宵酒客行。","秋日梁王池閣好，新歌散入管絃聲。"]', '["三軍江口擁雙旌，虎帳长开自教兵。","機鏁惡徒狂寇尽，恩驱老將壯心生。","水门向晚茶商鬧，橋市通宵酒客行。","秋日梁王池閣好，新歌散入管絃声。"]', '诗', 'shi', '', NULL, '寄汴州令狐相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3591dc7-e041-4163-9dfc-dd9dcd3ec49f', '別李贊侍御', '別李贊侍御', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["同受艱難驃騎營，半年中聽揭槍聲。","草頭送酒驅村樂，賊裏看花著探兵。","講易工夫尋已聖，說詩門戶別來情。","薦書自入無消息，賣盡寒衣却出城。"]', '["同受艱难驃騎營，半年中听揭槍声。","草头送酒驱村乐，賊裏看花著探兵。","講易工夫尋已聖，说诗门戶別来情。","薦书自入無消息，賣尽寒衣却出城。"]', '诗', 'shi', '', NULL, '別李贊侍御 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee87f4d0-417a-4108-9d5a-f61c24d0b36d', '和蔣學士新授章服', '和蔣学士新授章服', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["五色箱中絳服春，笏花成就白魚新。","看宣賜處驚回眼，著謝恩時便稱身。","瑞草唯承天上露，紅鸞不受世間塵。","翰林同賀文章出，驚動茫茫下界人。"]', '["五色箱中絳服春，笏花成就白鱼新。","看宣賜处驚回眼，著謝恩时便稱身。","瑞草唯承天上露，紅鸾不受世间塵。","翰林同賀文章出，驚动茫茫下界人。"]', '诗', 'shi', '', NULL, '和蔣學士新授章服 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead7332c-f399-449c-889e-f3813b14423a', '歲晚自感', '歲晚自感', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["人皆欲得長年少，無那排門白髮催。","一向破除愁不盡，百方回避老須來。","草堂未辦終須置，松樹難成亦且栽。","瀝酒願從今日後，更逢二十度花開。"]', '["人皆欲得长年少，無那排门白髮催。","一向破除愁不尽，百方回避老須来。","草堂未辦終須置，松樹难成亦且栽。","瀝酒願從今日後，更逢二十度花开。"]', '诗', 'shi', '', NULL, '歲晚自感 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8b6873-1bd9-434a-9c2f-0cd0c0f3e6ac', '昭應官舍', '昭應官舍', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["癡頑終日羨人閑，却喜因官得近山。","斜對寺樓分寂寂，遠從溪路借潺潺。","眇身多病唯親藥，空院無錢不要關。","文案把來看未會，雖書一字甚慙顏。"]', '["癡頑終日羨人闲，却喜因官得近山。","斜对寺楼分寂寂，远從溪路借潺潺。","眇身多病唯親藥，空院無錢不要关。","文案把来看未會，雖书一字甚慙顏。"]', '诗', 'shi', '', NULL, '昭應官舍 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e00d2a-c1fc-44ca-a10f-8bbf23f15341', '寄舊山僧', '寄旧山僧', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["因依老宿發心初，半學修心半讀書。","雪後每常同席臥，花時未省兩山居。","獵人箭底求傷雁，釣戶竿頭乞活魚。","一向風塵取煩惱，不知衰病日難除。"]', '["因依老宿發心初，半学修心半读书。","雪後每常同席臥，花时未省兩山居。","獵人箭底求傷雁，釣戶竿头乞活鱼。","一向风塵取煩惱，不知衰病日难除。"]', '诗', 'shi', '', NULL, '寄舊山僧 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('990fcce5-9eed-4401-b5b4-e72eb0b05d5f', '武陵春日', '武陵春日', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["尋春何事却悲涼，春到他鄉憶故鄉。","秦女洞桃欹澗碧，楚王堤柳舞煙黃。","波濤入夢家山遠，名利關身客路長。","不似冥心叩塵寂，玉編金軸有仙方。"]', '["尋春何事却悲涼，春到他乡憶故乡。","秦女洞桃欹澗碧，楚王堤柳舞煙黄。","波濤入梦家山远，名利关身客路长。","不似冥心叩塵寂，玉編金軸有仙方。"]', '诗', 'shi', '', NULL, '武陵春日 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e782fa05-af72-4dc1-a505-2bad2d9f324b', '寄分司張郎中', '寄分司張郎中', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一別京華年歲久，卷中多見嶺南詩。","聲名已壓衆人上，愁思未平雙鬢知。","江郡遷移猶遠地，仙官榮龐是分司。","青天白日當頭上，會有求閑不得時。"]', '["一別京华年歲久，卷中多见嶺南诗。","声名已壓衆人上，愁思未平雙鬢知。","江郡遷移猶远地，仙官榮龐是分司。","青天白日當头上，會有求闲不得时。"]', '诗', 'shi', '', NULL, '寄分司張郎中 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed11808-e156-4106-8758-d2cf0293d999', '上武元衡相公', '上武元衡相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["旌旗坐鎮蜀江雄，帝命重開舊閤崇。","襃貶唐書天曆上，捧持堯日慶雲中。","孤情逈出鸞皇遠，健思潛搜海嶽空。","長得蕭何爲國相，自西流水盡朝宗。"]', '["旌旗坐鎮蜀江雄，帝命重开旧閤崇。","襃貶唐书天曆上，捧持堯日慶云中。","孤情逈出鸾皇远，健思潛搜海嶽空。","长得蕭何爲国相，自西流水尽朝宗。"]', '诗', 'shi', '', NULL, '上武元衡相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b69e6a11-7091-4bfa-9fe3-5d5058996fc4', '上張弘靖相公', '上張弘靖相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["傳封三世盡河東，家占中條第一峰。","旱歲天教作霖雨，明時帝用補山龍。","草開舊路沙痕在，日照新池鳳跡重。","卑散自知霄漢隔，若爲門下賜從容。"]', '["傳封三世尽河东，家占中條第一峰。","旱歲天教作霖雨，明时帝用補山龙。","草开旧路沙痕在，日照新池鳳跡重。","卑散自知霄漢隔，若爲门下賜從容。"]', '诗', 'shi', '', NULL, '上張弘靖相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22f55472-b760-42db-b097-663f3c7e1833', '上裴度舍人', '上裴度舍人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["小松雙對鳳池開，履跡衣香逼上台。","天意皆從彩毫出，宸心盡向紫煙來。","非時玉案呈宣旨，每日金堦謝賜回。","仙侶何因記名姓，縣丞頭白走塵埃。"]', '["小松雙对鳳池开，履跡衣香逼上台。","天意皆從彩毫出，宸心尽向紫煙来。","非时玉案呈宣旨，每日金堦謝賜回。","仙侶何因記名姓，縣丞头白走塵埃。"]', '诗', 'shi', '', NULL, '上裴度舍人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2b9baa-2749-4d57-8b3c-31090d1da8f6', '上杜元穎相公', '上杜元穎相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["學士金鑾殿後居，天中行坐侍龍輿。","承恩不許離牀謝，密詔常教倚案書。","馬上喚遮紅觜鴨，船頭看釣赤鱗魚。","閑曹散吏無相識，猶記荆州拜謁初。"]', '["学士金鑾殿後居，天中行坐侍龙輿。","承恩不許離牀謝，密詔常教倚案书。","马上喚遮紅觜鴨，船头看釣赤鱗鱼。","闲曹散吏無相識，猶記荆州拜謁初。"]', '诗', 'shi', '', NULL, '上杜元穎相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4feeb63c-0bcd-4c01-abcd-b83d88e00b8c', '贈盧汀諫議', '贈盧汀諫議', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["青蛾不得在牀前，空室焚香獨自眠。","功證詩篇離景象，藥成官位屬神仙。","閑過寺觀長衝夜，立送封章直上天。","近見蘭臺諸吏說，御詩新集未教傳。"]', '["青蛾不得在牀前，空室焚香独自眠。","功證诗篇離景象，藥成官位屬神仙。","闲過寺观长衝夜，立送封章直上天。","近见蘭台諸吏说，御诗新集未教傳。"]', '诗', 'shi', '', NULL, '贈盧汀諫議 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b591b7-15eb-4bc8-aa66-1052cd87b22a', '賀楊巨源博士拜虞部員外', '賀楊巨源博士拜虞部員外', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["合歸蘭署已多時，上得金梯亦未遲。","兩省郎官開道路，九州山澤屬曹司。","諸生拜別收書卷，舊客看來讀制詞。","殘著幾丸仙藥在，分張還遣病夫知。"]', '["合归蘭署已多时，上得金梯亦未遲。","兩省郎官开道路，九州山澤屬曹司。","諸生拜別收书卷，旧客看来读制词。","殘著幾丸仙藥在，分張還遣病夫知。"]', '诗', 'shi', '', NULL, '賀楊巨源博士拜虞部員外 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c442e8aa-bce5-4547-a996-eef296a0b427', '贈郭將軍', '贈郭將軍', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["承恩新拜上將軍，當直巡更近五雲。","天下表章經院過，宮中語笑隔牆聞。","密封計策非時奏，別賜衣裳到處薰。","向晚臨堦看號簿，眼前風景任支分。"]', '["承恩新拜上將軍，當直巡更近五云。","天下表章經院過，宮中語笑隔牆闻。","密封計策非时奏，別賜衣裳到处薰。","向晚臨堦看號簿，眼前风景任支分。"]', '诗', 'shi', '', NULL, '贈郭將軍 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e384c76b-0d89-437d-adc0-1b176fa74c24', '贈田將軍', '贈田將軍', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["初從學院別先生，便領偏師得戰名。","大小獨當三百陣，縱橫祗用五千兵。","回殘匹帛歸天庫，分好旌旗入禁營。","自執金吾長上直，蓬萊宮裏夜巡更。"]', '["初從学院別先生，便領偏師得戰名。","大小独當三百陣，縱橫祗用五千兵。","回殘匹帛归天庫，分好旌旗入禁營。","自執金吾长上直，蓬萊宮裏夜巡更。"]', '诗', 'shi', '', NULL, '贈田將軍 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b122f204-a414-43f7-ad88-14de3eb1b44a', '贈胡泟將軍', '贈胡泟將軍', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["書生難得是金吾，近日登科記總無。","半夜進儺當玉殿，未明排仗到銅壺。","朱牌面上分官契，黃紙頭邊押勅符。","恐要蕃中新道路，指揮重畫五城圖。"]', '["书生难得是金吾，近日登科記總無。","半夜進儺當玉殿，未明排仗到銅壺。","朱牌面上分官契，黄紙头邊押勅符。","恐要蕃中新道路，指揮重畫五城圖。"]', '诗', 'shi', '', NULL, '贈胡泟將軍 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a67eb88-3d0d-4513-9852-5b191649c806', '留別田尚書', '留別田尚书', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["擬報平生未殺身，難離門館起居頻。","不看匣裏釵頭古，猶戀機中錦樣新。","一旦甘爲漳岸老，全家却作杜陵人。","朝天路在驪山下，專望紅旗拜舊塵。"]', '["擬報平生未殺身，难離门館起居頻。","不看匣裏釵头古，猶戀機中錦樣新。","一旦甘爲漳岸老，全家却作杜陵人。","朝天路在驪山下，專望紅旗拜旧塵。"]', '诗', 'shi', '', NULL, '留別田尚書 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27973e2a-78d5-4b23-9cbc-b7aefa810514', '送唐大夫罷節歸山', '送唐大夫罷節归山', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["年少平戎老學仙，表求骸骨乞生全。","不堪腰下懸金印，已向雲西寄玉田。","旄節抱歸官路上，公卿送到國門前。","人間雞犬同時去，遙聽笙歌隔水煙。"]', '["年少平戎老学仙，表求骸骨乞生全。","不堪腰下懸金印，已向云西寄玉田。","旄節抱归官路上，公卿送到国门前。","人间雞犬同时去，遙听笙歌隔水煙。"]', '诗', 'shi', '', NULL, '送唐大夫罷節歸山 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af79842b-d31a-453d-bc9a-a3e2c124ba1a', '送司空神童', '送司空神童', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["杏花壇上授書時，不廢中庭趂蝶飛。","暗寫五經收部秩，初年七歲著衫衣。","秋堂白髮先生別，古巷青襟舊伴歸。","獨向鳳城持薦表，萬人叢裏有光輝。"]', '["杏花壇上授书时，不廢中庭趂蝶飞。","暗寫五經收部秩，初年七歲著衫衣。","秋堂白髮先生別，古巷青襟旧伴归。","独向鳳城持薦表，万人叢裏有光輝。"]', '诗', 'shi', '', NULL, '送司空神童 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('593b85ac-836c-4dc5-9df9-80896aed57b1', '送振武張尚書', '送振武張尚书', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["回天轉地是將軍，扶助春宮上五雲。","撫背恩雖同骨肉，擁旄名未敵功勳。","盡收壯勇填兵數，不向蕃渾奪馬羣。","閑即單于臺下獵，威聲直到海西聞。"]', '["回天轉地是將軍，扶助春宮上五云。","撫背恩雖同骨肉，擁旄名未敵功勳。","尽收壯勇填兵數，不向蕃渾奪马羣。","闲即單于台下獵，威声直到海西闻。"]', '诗', 'shi', '', NULL, '送振武張尚書 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7550390-cba4-483d-bf2b-c004ba1a63c5', '送吳諫議上饒州', '送吳諫議上饒州', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鄱陽太守是真人，琴在牀頭籙在身。","曾向先皇邊諫事，還應上帝處稱臣。","養生自有年支藥，稅戶應停月進銀。","淨掃水堂無侍女，下街唯共鶴殷勤。"]', '["鄱陽太守是真人，琴在牀头籙在身。","曾向先皇邊諫事，還應上帝处稱臣。","養生自有年支藥，稅戶應停月進銀。","淨掃水堂無侍女，下街唯共鹤殷勤。"]', '诗', 'shi', '', NULL, '送吳諫議上饒州 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04435e69-cfbe-4e0c-9907-e35330d414c6', '贈閻少保', '贈閻少保', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["髭鬚雖白體輕健，九十三來却少年。","問事愛知天寶裏，識人皆是武皇前。","玉裝劒珮身長帶，絹寫方書子不傳。","侍女常時教合藥，亦聞私地學求仙。"]', '["髭鬚雖白體轻健，九十三来却少年。","问事愛知天寶裏，識人皆是武皇前。","玉裝劒珮身长带，絹寫方书子不傳。","侍女常时教合藥，亦闻私地学求仙。"]', '诗', 'shi', '', NULL, '贈閻少保 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5111a8b-8b91-486a-b966-db944fd58d56', '送魏州李相公', '送魏州李相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["百代功勳一日成，三年五度換雙旌。","閑來不對人論戰，難處長先自請行。","旗下可聞誅敗將，陣頭多是用降兵。","當朝面受新恩去，算料妖星不敢生。"]', '["百代功勳一日成，三年五度換雙旌。","闲来不对人論戰，难处长先自請行。","旗下可闻誅敗將，陣头多是用降兵。","當朝面受新恩去，算料妖星不敢生。"]', '诗', 'shi', '', NULL, '送魏州李相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42668b3c-bf4c-495d-80c2-92cf24df6196', '贈索暹將軍', '贈索暹將軍', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["渾身著箭瘢猶在，萬槊千刀總過來。","輪劒直衝生馬隊，抽旗旋踏死人堆。","聞休鬬戰心還癢，見說煙塵眼即開。","泪滴先皇堦下土，南衙班裏趁朝回。"]', '["渾身著箭瘢猶在，万槊千刀總過来。","輪劒直衝生马隊，抽旗旋踏死人堆。","闻休鬬戰心還癢，见说煙塵眼即开。","泪滴先皇堦下土，南衙班裏趁朝回。"]', '诗', 'shi', '', NULL, '贈索暹將軍 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63bccd5f-9e37-4f51-bc36-f0a48fa62203', '贈王屋道士赴詔', '贈王屋道士赴詔', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["玉皇符詔下天壇，玳瑁頭簪白角冠。","鶴遣院中童子養，鹿憑山下老人看。","法成不怕刀槍利，體實常欺石榻寒。","能斷世間腥血昧，長生只要一丸丹。"]', '["玉皇符詔下天壇，玳瑁头簪白角冠。","鹤遣院中童子養，鹿憑山下老人看。","法成不怕刀槍利，體實常欺石榻寒。","能斷世间腥血昧，长生只要一丸丹。"]', '诗', 'shi', '', NULL, '贈王屋道士赴詔 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8dd62f-12f1-4d0f-9ebc-88645fe3a2e5', '贈王處士', '贈王处士', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["松樹當軒雪滿地，青山掩障碧紗幮。","鼠來案上常偷水，鶴在牀前亦看碁。","道士寫將行氣法，家童授與步虛詞。","世間有似君應少，便乞從今作我師。"]', '["松樹當軒雪满地，青山掩障碧紗幮。","鼠来案上常偷水，鹤在牀前亦看碁。","道士寫將行氣法，家童授與步虛词。","世间有似君應少，便乞從今作我師。"]', '诗', 'shi', '', NULL, '贈王處士 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0891e43-57ed-4936-9681-06025f00aa9e', '洛中張籍新居', '洛中張籍新居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["最是城中閑靜處，更回門向寺前開。","雲山且喜重重見，親故應須得得來。","借倩學生排藥合，留連處士乞松栽。","自君移到無多日，牆上人名滿綠苔。"]', '["最是城中闲静处，更回门向寺前开。","云山且喜重重见，親故應須得得来。","借倩学生排藥合，留連处士乞松栽。","自君移到無多日，牆上人名满綠苔。"]', '诗', 'shi', '', NULL, '洛中張籍新居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28175d3-b929-4a82-832b-4d2443c4c0c5', '題裴處士碧虛溪居', '題裴处士碧虛溪居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鳥聲真似深山裏，平地人間自不同。","春圃紫芹長卓卓，暖泉青草一叢叢。","松臺前後花皆別，竹崦高低水盡通。","細問來時從近遠，溪名載入縣圖中。"]', '["鸟声真似深山裏，平地人间自不同。","春圃紫芹长卓卓，暖泉青草一叢叢。","松台前後花皆別，竹崦高低水尽通。","細问来时從近远，溪名載入縣圖中。"]', '诗', 'shi', '', NULL, '題裴處士碧虛溪居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0a586a-0e00-4330-988a-512a42903ffc', '送阿史那將軍安西迎舊使靈櫬', '送阿史那將軍安西迎旧使靈櫬', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["漢家都護邊頭沒，舊將麻衣萬里迎。","陰地背行山下火，風天錯到磧西城。","單于送葬還垂淚，部曲招魂亦道名。","却入杜陵秋巷裏，路人來去讀銘旌。"]', '["漢家都護邊头沒，旧將麻衣万里迎。","陰地背行山下火，风天錯到磧西城。","單于送葬還垂泪，部曲招魂亦道名。","却入杜陵秋巷裏，路人来去读銘旌。"]', '诗', 'shi', '', NULL, '送阿史那將軍安西迎舊使靈櫬 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34fe5b48-7725-4c09-9b11-f27111088ec1', '贈崔禮駙馬', '贈崔禮駙马', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鳳皇樓閣連宮樹，天子崔郎自愛貧。","金埒減添栽藥地，玉鞭平與賣書人。","家中弦管聽常少，分外詩篇看即新。","一月一回陪內宴，馬蹄猶壓踏香塵。"]', '["鳳皇楼閣連宮樹，天子崔郎自愛貧。","金埒減添栽藥地，玉鞭平與賣书人。","家中弦管听常少，分外诗篇看即新。","一月一回陪內宴，马蹄猶壓踏香塵。"]', '诗', 'shi', '', NULL, '贈崔禮駙馬 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90db08ad-b913-4456-a6a0-eebbfea52433', '贈太清盧道士', '贈太清盧道士', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["上清道士未昇天，南岳中華作散仙。","書賣八分通字學，丹燒九轉定人年。","修行近日形如鶴，導引多時骨似綿。","想向諸山尋禮遍，却回還守老君前。"]', '["上清道士未昇天，南岳中华作散仙。","书賣八分通字学，丹燒九轉定人年。","修行近日形如鹤，導引多时骨似綿。","想向諸山尋禮遍，却回還守老君前。"]', '诗', 'shi', '', NULL, '贈太清盧道士 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301333cd-30ee-48f4-ba6f-9f4b2ad0d331', '送宮人入道', '送宮人入道', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["休梳叢鬢洗紅妝，頭戴芙蓉出未央。","弟子抄將歌遍疊，宮人分散舞衣裳。","問師初得經中字，入靜猶燒內裏香。","發願蓬萊見王母，却歸人世施仙方。"]', '["休梳叢鬢洗紅妝，头戴芙蓉出未央。","弟子抄將歌遍叠，宮人分散舞衣裳。","问師初得經中字，入静猶燒內裏香。","發願蓬萊见王母，却归人世施仙方。"]', '诗', 'shi', '', NULL, '送宮人入道 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d80d5b-1ad1-4044-9a68-8da672d9e7e6', '上李吉甫相公', '上李吉甫相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["聖朝齊賀說逢殷，霄漢無雲日月真。","金鼎調和天膳美，瑤池沐浴賜衣新。","兩河開地山川正，四海休兵造化仁。","曾向山東爲散吏，當今竇憲是賢臣。"]', '["聖朝齊賀说逢殷，霄漢無云日月真。","金鼎調和天膳美，瑤池沐浴賜衣新。","兩河开地山川正，四海休兵造化仁。","曾向山东爲散吏，當今竇憲是賢臣。"]', '诗', 'shi', '', NULL, '上李吉甫相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1d3b38-037f-4cca-8a75-c42d52b330a0', '上李益庶子', '上李益庶子', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["紫煙樓閣碧紗亭，上界詩仙獨自行。","奇險驅回還寂寞，雲山經用始鮮明。","藕綃紋縷裁來滑，鏡水波濤濾得清。","昏思願因秋露洗，幸容堦下禮先生。"]', '["紫煙楼閣碧紗亭，上界诗仙独自行。","奇險驱回還寂寞，云山經用始鲜明。","藕綃紋縷裁来滑，镜水波濤濾得清。","昏思願因秋露洗，幸容堦下禮先生。"]', '诗', 'shi', '', NULL, '上李益庶子 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ac5eb3-ccf7-4e2e-987b-846db242acda', '題元郎中新宅', '題元郎中新宅', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["近移松樹初栽藥，經帙書籤一切新。","鋪設暖房迎道士，支分閑院著醫人。","買來高石雖然貴，入得朱門未免貧。","惟有好詩名字出，倍教年少損心神。"]', '["近移松樹初栽藥，經帙书籤一切新。","鋪設暖房迎道士，支分闲院著醫人。","買来高石雖然貴，入得朱门未免貧。","惟有好诗名字出，倍教年少損心神。"]', '诗', 'shi', '', NULL, '題元郎中新宅 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f8238ba-3ceb-4235-b124-28cc24cae7f0', '初授太府丞言懷', '初授太府丞言懷', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["除書亦下屬微班，喚作官曹便不閑。","檢案事多關市井，聽人言志在雲山。","病童喚著唯行慢，老馬鞭多轉放頑。","此去仙宮無一里，遙看松樹衆家攀。"]', '["除书亦下屬微班，喚作官曹便不闲。","檢案事多关市井，听人言志在云山。","病童喚著唯行慢，老马鞭多轉放頑。","此去仙宮無一里，遙看松樹衆家攀。"]', '诗', 'shi', '', NULL, '初授太府丞言懷 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eee28e0-1517-42fd-9da8-e0f39ff5a8e5', '贈李愬僕射', '贈李愬僕射', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["唐州將士死生同，盡逐雙旌舊鎮空。","獨破淮西功業大，新除隴右世家雄。","知時每笑論兵法，識勢還輕立戰功。","次第各分茅土貴，殊勳併在一門中。"]', '["唐州將士死生同，尽逐雙旌旧鎮空。","独破淮西功業大，新除隴右世家雄。","知时每笑論兵法，識勢還轻立戰功。","次第各分茅土貴，殊勳併在一门中。"]', '诗', 'shi', '', NULL, '贈李愬僕射 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dfec9a2-b67b-4eeb-846c-aa2af2bd364e', '書贈舊渾二曹長', '书贈旧渾二曹长', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["二年同在華清下，入縣門中最近鄰。","替飲觥籌知戶小，助成書屋見家貧。","夜碁臨散停分客，朝浴先回各送人。","僮僕使來傳語熟，至今行酒校殷勤。"]', '["二年同在华清下，入縣门中最近鄰。","替饮觥籌知戶小，助成书屋见家貧。","夜碁臨散停分客，朝浴先回各送人。","僮僕使来傳語熟，至今行酒校殷勤。"]', '诗', 'shi', '', NULL, '書贈舊渾二曹長 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('238f693f-32b2-4c3b-9da1-a2e767c88184', '上崔相公', '上崔相公', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["枯桂衰蘭一遍春，唯將道德定君臣。","施行聖澤山川潤，圖畫天文彩色新。","開閣覆看祥瑞曆，封名直進薜蘿人。","應憐老病無知己，自別溪中滿鬢塵。"]', '["枯桂衰蘭一遍春，唯將道德定君臣。","施行聖澤山川潤，圖畫天文彩色新。","开閣覆看祥瑞曆，封名直進薜蘿人。","應怜老病無知己，自別溪中满鬢塵。"]', '诗', 'shi', '', NULL, '上崔相公 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc52516d-0dbb-4fba-9a23-359d1270a87f', '寄楊十二秘書', '寄楊十二秘书', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["初移古寺正南方，靜是浮山遠是莊。","人定猶行背街鼓，月高還去打僧房。","新詩欲寫中朝滿，舊卷常抄外國將。","閑出天門醉騎馬，可憐蓬閣秘書郎。"]', '["初移古寺正南方，静是浮山远是莊。","人定猶行背街鼓，月高還去打僧房。","新诗欲寫中朝满，旧卷常抄外国將。","闲出天门醉騎马，可怜蓬閣秘书郎。"]', '诗', 'shi', '', NULL, '寄楊十二秘書 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da167e6b-f19a-452e-bdc7-0cacb1f20878', '謝田贊善見寄', '謝田贊善见寄', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["五侯三任未相稱，頭白如絲作縣丞。","錯判符曹羣吏笑，亂書巖石一山憎。","自知酒病衰腸怯，遙怕春殘百鳥凌。","年少力生猶不敵，況加顦顇悶騰騰。"]', '["五侯三任未相稱，头白如絲作縣丞。","錯判符曹羣吏笑，亂书巖石一山憎。","自知酒病衰腸怯，遙怕春殘百鸟凌。","年少力生猶不敵，況加顦顇悶腾腾。"]', '诗', 'shi', '', NULL, '謝田贊善見寄 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb6dd3e-1109-4311-a0f6-e995231d60ef', '晚秋病中', '晚秋病中', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["萬事風吹過耳輪，貧兒活計亦曾聞。","偶逢新語書紅葉，難得閑人話白雲。","霜下野花渾著地，寒來溪鳥不成羣。","病多體痛無心力，更被頭邊藥氣熏。"]', '["万事风吹過耳輪，貧兒活計亦曾闻。","偶逢新語书紅葉，难得闲人話白云。","霜下野花渾著地，寒来溪鸟不成羣。","病多體痛無心力，更被头邊藥氣熏。"]', '诗', 'shi', '', NULL, '晚秋病中 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70cab30e-4882-443a-b461-2d38bcae6891', '薛二十池亭', '薛二十池亭', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["每箇樹邊消一日，遶池行匝又須行。","異花多是非時有，好竹皆當要處生。","斜豎小橋看島勢，遠移山石作泉聲。","浮萍著岸風吹歇，水面無塵晚更清。"]', '["每箇樹邊消一日，遶池行匝又須行。","異花多是非时有，好竹皆當要处生。","斜豎小橋看島勢，远移山石作泉声。","浮萍著岸风吹歇，水面無塵晚更清。"]', '诗', 'shi', '', NULL, '薛二十池亭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbbd8442-beb3-4660-a6eb-290f87b89b77', '故梁國公主池亭', '故梁国公主池亭', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["平陽池館枕秦川，門鎖南山一朵煙。","素柰花開西子面，綠榆枝散沈郎錢。","裝簷玳瑁隨風落，傍岸鵁鶄逐暖眠。","寂寞空餘歌舞地，玉簫聲絕鳳歸天。"]', '["平陽池館枕秦川，门鎖南山一朵煙。","素柰花开西子面，綠榆枝散沈郎錢。","裝簷玳瑁隨风落，傍岸鵁鶄逐暖眠。","寂寞空餘歌舞地，玉簫声絕鳳归天。"]', '诗', 'shi', '', NULL, '故梁國公主池亭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14232fe1-35c8-47d1-8ba5-80b31460d564', '題柱國寺', '題柱国寺', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["皇帝施錢修此院，半居天上半人間。","丹梯暗出三重閣，古像斜開一面山。","松柏自穿空地少，川原不稅小僧閑。","行香天使長相續，早起離城日午還。"]', '["皇帝施錢修此院，半居天上半人间。","丹梯暗出三重閣，古像斜开一面山。","松柏自穿空地少，川原不稅小僧闲。","行香天使长相續，早起離城日午還。"]', '诗', 'shi', '', NULL, '題柱國寺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6911799-0c0f-4ab8-b55d-7d63deced9a2', '昭應官舍書事', '昭應官舍书事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["縣在華清宮北面，曉看樓殿正相當。","慶雲出處依時報，御果呈來每度嘗。","臘月近湯泉不凍，夏天臨渭屋多涼。","兩衙早被官拘束，登閣巡溪亦屬忙。"]', '["縣在华清宮北面，晓看楼殿正相當。","慶云出处依时報，御果呈来每度嘗。","臘月近湯泉不凍，夏天臨渭屋多涼。","兩衙早被官拘束，登閣巡溪亦屬忙。"]', '诗', 'shi', '', NULL, '昭應官舍書事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('609665e0-d947-403a-be76-1a7a24aef344', '昭應李郎中見貽佳作次韻奉酬', '昭應李郎中见貽佳作次韻奉酬', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["窗戶風涼四面開，陶公愛晚上高臺。","中庭不熱青山入，野水初晴白鳥來。","靜思道心緣境熟，麤疎文字見詩回。","諸生圍遶新篇讀，玉闕仙宮少此才。"]', '["窗戶风涼四面开，陶公愛晚上高台。","中庭不熱青山入，野水初晴白鸟来。","静思道心緣境熟，麤疎文字见诗回。","諸生圍遶新篇读，玉闕仙宮少此才。"]', '诗', 'shi', '', NULL, '昭應李郎中見貽佳作次韻奉酬 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6ae424-9a39-46f6-9d5a-795bcb600918', '閑說', '闲说', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["桃花百葉不成春，鶴壽千年也未神。","秦隴州緣鸚鵡貴，王侯家爲牡丹貧。","歌頭舞遍回回別，鬢樣眉心日日新。","鼓動六街騎馬出，相逢總是學狂人。"]', '["桃花百葉不成春，鹤壽千年也未神。","秦隴州緣鸚鵡貴，王侯家爲牡丹貧。","歌头舞遍回回別，鬢樣眉心日日新。","鼓动六街騎马出，相逢總是学狂人。"]', '诗', 'shi', '', NULL, '閑說 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78584a46-c8dc-4c1f-bd84-50e4aae19bf9', '自傷', '自傷', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["衰門海內幾多人，滿眼公卿總不親。","四授官資元七品，再經婚娶尚單身。","圖書亦爲頻移盡，兄弟還因數散貧。","獨自在家長似客，黃昏哭向野田春。"]', '["衰门海內幾多人，满眼公卿總不親。","四授官資元七品，再經婚娶尚單身。","圖书亦爲頻移尽，兄弟還因數散貧。","独自在家长似客，黄昏哭向野田春。"]', '诗', 'shi', '', NULL, '自傷 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c64d89c-ddec-4f0a-8e10-37566af8890c', '田侍中宴席', '田侍中宴席', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["香熏羅幕暖成煙，火照中庭燭滿筵。","整頓舞衣呈玉腕，動搖歌扇露金鈿。","青蛾側座調雙管，彩鳳斜飛入五弦。","雖是沂公門下客，爭將肉眼看雲天。"]', '["香熏羅幕暖成煙，火照中庭燭满筵。","整頓舞衣呈玉腕，动搖歌扇露金鈿。","青蛾側座調雙管，彩鳳斜飞入五弦。","雖是沂公门下客，爭將肉眼看云天。"]', '诗', 'shi', '', NULL, '田侍中宴席 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b62970f6-6aa5-4b49-8c2d-02a67210920d', '寒食日看花', '寒食日看花', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["早入公門到夜歸，不因寒食少閑時。","顛狂遶樹猿離鏁，跳躑緣岡馬斷羈。","酒汙衣裳從客笑，醉饒言語覓花知。","老來自喜身無事，仰面西園得詠詩。"]', '["早入公门到夜归，不因寒食少闲时。","顛狂遶樹猿離鏁，跳躑緣岡马斷羈。","酒汙衣裳從客笑，醉饒言語覓花知。","老来自喜身無事，仰面西园得詠诗。"]', '诗', 'shi', '', NULL, '寒食日看花 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7a67db-d417-49f9-823d-d8e679a35d1a', '和少府崔卿微雪早朝', '和少府崔卿微雪早朝', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["蓬萊春雪曉猶殘，點地成花遶百官。","已傍祥鸞迷殿角，還穿瑞草入袍襴。","無多白玉階前濕，積漸青松葉上乾。","粉畫南山稜郭出，初晴一半隔雲看。"]', '["蓬萊春雪晓猶殘，点地成花遶百官。","已傍祥鸾迷殿角，還穿瑞草入袍襴。","無多白玉階前濕，積漸青松葉上乾。","粉畫南山稜郭出，初晴一半隔云看。"]', '诗', 'shi', '', NULL, '和少府崔卿微雪早朝 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2bcfcd7-bff1-4079-8ed9-636909088a11', '和胡將軍寓直', '和胡將軍寓直', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宮鴉棲定禁槍攢，樓殿深嚴月色寒。","進狀直穿金戟槊，探更先傍玉鉤欄。","漏傳五點班初合，鼓動三聲仗已端。","遙見正南宣不坐，新栽松樹喚人看。"]', '["宮鴉棲定禁槍攢，楼殿深嚴月色寒。","進狀直穿金戟槊，探更先傍玉鉤欄。","漏傳五点班初合，鼓动三声仗已端。","遙见正南宣不坐，新栽松樹喚人看。"]', '诗', 'shi', '', NULL, '和胡將軍寓直 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8bb235a-83c5-4925-91a8-b7fc112a2197', '春日五門西望', '春日五门西望', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["百官朝下五門西，塵起春風過玉堤。","黃帕蓋鞍呈了馬，紅羅繫項鬬回雞館松枝重牆頭出，御柳條長水面齊。","唯有教坊南草綠，古苔陰地冷淒淒。"]', '["百官朝下五门西，塵起春风過玉堤。","黄帕蓋鞍呈了马，紅羅繫項鬬回雞館松枝重牆头出，御柳條长水面齊。","唯有教坊南草綠，古苔陰地冷淒淒。"]', '诗', 'shi', '', NULL, '春日五門西望 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75e8d1e-9f33-4203-8a87-518c2bba6875', '長安早春', '长安早春', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["霏霏漠漠遶皇州，銷雪欺寒不自由。","先向紅妝添曉夢，爭來白髮送新愁。","暖催衣上縫羅勝，晴報窗中點綵毬。","每度暗來還暗去，今年須遣蝶遲留。"]', '["霏霏漠漠遶皇州，銷雪欺寒不自由。","先向紅妝添晓梦，爭来白髮送新愁。","暖催衣上縫羅勝，晴報窗中点綵毬。","每度暗来還暗去，今年須遣蝶遲留。"]', '诗', 'shi', '', NULL, '長安早春 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbf8c05d-acf9-4c37-990c-f32200d9e1f3', '早春病中', '早春病中', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["日日春風階下起，不吹光彩上寒株。","師教絳服禳衰月，妻許青衣侍病夫。","健羨人家多力子，祈求道士有神符。","世間方法從誰問，臥處還看藥草圖。"]', '["日日春风階下起，不吹光彩上寒株。","師教絳服禳衰月，妻許青衣侍病夫。","健羨人家多力子，祈求道士有神符。","世间方法從誰问，臥处還看藥草圖。"]', '诗', 'shi', '', NULL, '早春病中 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f10208-8797-412a-a458-a0faaccb0ea5', '上陽宮', '上陽宮', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["上陽花木不曾秋，洛水穿宮處處流。","畫閣紅樓宮女笑，玉簫金管路人愁。","幔城入澗橙花發，玉輦登山桂葉稠。","曾讀列仙王母傳，九天未勝此中遊。"]', '["上陽花木不曾秋，洛水穿宮处处流。","畫閣紅楼宮女笑，玉簫金管路人愁。","幔城入澗橙花發，玉輦登山桂葉稠。","曾读列仙王母傳，九天未勝此中游。"]', '诗', 'shi', '', NULL, '上陽宮 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c02818-5805-43b0-aed3-02d64601f482', '李處士故居', '李处士故居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["露濃煙重草萋萋，樹映闌干柳拂堤。","一院落花無客醉，半窗殘月有鶯啼。","芳筵想像情難盡，故榭荒涼路欲迷。","風景宛然人自改，却經門外馬頻嘶。"]', '["露濃煙重草萋萋，樹映闌干柳拂堤。","一院落花無客醉，半窗殘月有鶯啼。","芳筵想像情难尽，故榭荒涼路欲迷。","风景宛然人自改，却經门外马頻嘶。"]', '诗', 'shi', '', NULL, '李處士故居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ebf2c0d-1270-4493-90af-b7d429ab78eb', '寄賈島', '寄賈島', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["盡日吟詩坐忍飢，萬人中覓似君稀。","僮眠冷榻朝猶臥，驢放秋田夜不歸。","傍暖旋收紅落葉，覺寒猶著舊生衣。","曲江池畔時時到，爲愛鸕鷀雨後飛。"]', '["尽日吟诗坐忍飢，万人中覓似君稀。","僮眠冷榻朝猶臥，驢放秋田夜不归。","傍暖旋收紅落葉，覺寒猶著旧生衣。","曲江池畔时时到，爲愛鸕鷀雨後飞。"]', '诗', 'shi', '', NULL, '寄賈島 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b4fa8e-6535-4b54-a31d-853c3cc55431', '村居即事', '村居即事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["休看小字大書名，向日持經眼却明。","時過無心求富貴，身閑不夢見公卿。","因尋寺裏薰辛斷，自別城中禮數生。","斜月照房新睡覺，西峰半夜鶴來聲。"]', '["休看小字大书名，向日持經眼却明。","时過無心求富貴，身闲不梦见公卿。","因尋寺裏薰辛斷，自別城中禮數生。","斜月照房新睡覺，西峰半夜鹤来声。"]', '诗', 'shi', '', NULL, '村居即事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e70b94-0d86-4430-b51f-c3c6e9a1796d', '維揚冬末寄幕中二從事', '維揚冬末寄幕中二從事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["江上數株桑棗樹，自從離亂更荒涼。","那堪旅館經殘臘，秪把空書寄故鄉。","典盡客衣三尺雪，鍊精詩句一頭霜。","故人多在芙蓉幕，應笑孜孜道未光。"]', '["江上數株桑棗樹，自從離亂更荒涼。","那堪旅館經殘臘，秪把空书寄故乡。","典尽客衣三尺雪，鍊精诗句一头霜。","故人多在芙蓉幕，應笑孜孜道未光。"]', '诗', 'shi', '', NULL, '維揚冬末寄幕中二從事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc10910-5358-4c1e-ad03-4114fb8ff480', '寄杜侍御', '寄杜侍御', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["何須服藥覓昇天，粉閣爲郎即是仙。","買宅但幽從索價，栽松取活不爭錢。","退朝寺裏尋荒塔，經宿城南看野泉。","道氣清凝分曉爽，詩情冷瘦滴秋鮮。","學通儒釋三千卷，身擁旌旗二十年。","春巷偶過同戶飲，暖窗時與對牀眠。","破除心力緣書癖，傷瘦花枝爲酒顛。","今日總來歸聖代，丈人先達幸相憐。"]', '["何須服藥覓昇天，粉閣爲郎即是仙。","買宅但幽從索價，栽松取活不爭錢。","退朝寺裏尋荒塔，經宿城南看野泉。","道氣清凝分晓爽，诗情冷瘦滴秋鲜。","学通儒釋三千卷，身擁旌旗二十年。","春巷偶過同戶饮，暖窗时與对牀眠。","破除心力緣书癖，傷瘦花枝爲酒顛。","今日總来归聖代，丈人先達幸相怜。"]', '诗', 'shi', '', NULL, '寄杜侍御 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85b298b8-e4bf-4cd7-b335-a5ed90169354', '寄上韓愈侍郎', '寄上韓愈侍郎', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["重登大學領儒流，學浪詞鋒壓九州。","不以雄名疎野賤，唯將直氣折王侯。","詠傷松桂青山瘦，取盡珠璣碧海愁。","敍述異篇經總別，鞭驅險句最先投。","碑文合遣貞魂謝，史筆應令諂骨羞。","清俸探將還酒債，黃金旋得起書樓。","參來擬設官人禮，朝退多逢月閣遊。","見說雲泉求住處，若無知薦一生休。"]', '["重登大学領儒流，学浪词鋒壓九州。","不以雄名疎野賤，唯將直氣折王侯。","詠傷松桂青山瘦，取尽珠璣碧海愁。","敍述異篇經總別，鞭驱險句最先投。","碑文合遣貞魂謝，史笔應令諂骨羞。","清俸探將還酒債，黄金旋得起书楼。","參来擬設官人禮，朝退多逢月閣游。","见说云泉求住处，若無知薦一生休。"]', '诗', 'shi', '', NULL, '寄上韓愈侍郎 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96799361-68ba-4585-99f9-cbfa8e2ba0d2', '贈華州鄭大夫', '贈华州鄭大夫', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["此官出入鳳池頭，通化門前第一州。","少華山雲當驛起，小敷溪水入城流。","空閑地內人初滿，詞訟牌前草漸稠。","報狀拆開知足雨，赦書宣過喜無囚。","自來不說雙旌貴，恐替長教百姓愁。","公退晚涼無一事，步行攜客上南樓。"]', '["此官出入鳳池头，通化门前第一州。","少华山云當驛起，小敷溪水入城流。","空闲地內人初满，词訟牌前草漸稠。","報狀拆开知足雨，赦书宣過喜無囚。","自来不说雙旌貴，恐替长教百姓愁。","公退晚涼無一事，步行携客上南楼。"]', '诗', 'shi', '', NULL, '贈華州鄭大夫 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a453a702-ad7f-4f2a-a620-b2471955c45d', '寄賀田侍中東平功成', '寄賀田侍中东平功成', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["使回高品滿城傳，親見沂公在陣前。","百里旗幡衝即斷，兩重衣甲射皆穿。","探知點檢兵應怯，算得新移柵未堅。","營被數驚乘勢破，將經頻敗遂生全。","密招殘寇防人覺，遙斬元兇恐自專。","首讓諸軍無敢近，功歸部曲不爭先。","開通州縣斜連海，交割山河直到燕。","戰馬散驅還逐草，肉牛齊散却耕田。","府中獨拜將軍貴，門下兼分宰相權。","唐史上頭功第一，春風雙節好朝天。"]', '["使回高品满城傳，親见沂公在陣前。","百里旗幡衝即斷，兩重衣甲射皆穿。","探知点檢兵應怯，算得新移柵未堅。","營被數驚乘勢破，將經頻敗遂生全。","密招殘寇防人覺，遙斬元兇恐自專。","首讓諸軍無敢近，功归部曲不爭先。","开通州縣斜連海，交割山河直到燕。","戰马散驱還逐草，肉牛齊散却耕田。","府中独拜將軍貴，门下兼分宰相權。","唐史上头功第一，春风雙節好朝天。"]', '诗', 'shi', '', NULL, '寄賀田侍中東平功成 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aedeb3e6-3df2-4379-afc7-0b5f8719f597', '送裴相公上太原', '送裴相公上太原', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["還攜堂印向幷州，將相兼權是武侯。","時難獨當天下事，功成却進手中籌。","再三陳乞罏煙裏，前後封章玉案頭。","朱架早朝立劒戟，綠槐殘雨看張油。","遙知塞雁從今好，直得漁陽已北愁。","邊鋪警巡旗盡換，山城候館壁重修。","千羣白刃兵迎節，十對紅妝妓打毬。","聖主分明交暫去，不須高起見京樓。"]', '["還携堂印向幷州，將相兼權是武侯。","时难独當天下事，功成却進手中籌。","再三陳乞罏煙裏，前後封章玉案头。","朱架早朝立劒戟，綠槐殘雨看張油。","遙知塞雁從今好，直得漁陽已北愁。","邊鋪警巡旗尽換，山城候館壁重修。","千羣白刃兵迎節，十对紅妝妓打毬。","聖主分明交暫去，不須高起见京楼。"]', '诗', 'shi', '', NULL, '送裴相公上太原 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96758abb-9c2f-4af2-984f-914592486897', '題栢巖禪師影堂', '題栢巖禪師影堂', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["山中磚塔閉，松下影堂新。","恨不生前識，今朝禮畫身。"]', '["山中磚塔閉，松下影堂新。","恨不生前識，今朝禮畫身。"]', '诗', 'shi', '', NULL, '題栢巖禪師影堂 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7e882c-5c5c-40d9-971b-ccdd2d1df293', '送人', '送人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["河亭收酒器，語盡各西東。","回首不相見，行車秋雨中。"]', '["河亭收酒器，語尽各西东。","回首不相见，行车秋雨中。"]', '诗', 'shi', '', NULL, '送人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a360ba0f-5145-481a-9398-2b0e6955501d', '春意二首 一', '春意二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["去日丁寧別，情知寒食歸。","緣逢好天氣，教熨看花衣。"]', '["去日丁寧別，情知寒食归。","緣逢好天氣，教熨看花衣。"]', '诗', 'shi', '', NULL, '春意二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4191e9-46f3-4d0e-941e-556c957f9bb4', '春意二首 二', '春意二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["誰是杏園主，一枝臨古岐。","從傷早春意，乞取欲開枝。"]', '["誰是杏园主，一枝臨古岐。","從傷早春意，乞取欲开枝。"]', '诗', 'shi', '', NULL, '春意二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('793bba92-14b6-45e6-89aa-b12c71b47348', '夜聞子規', '夜闻子規', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["子規啼不歇，到曉口應穿。","況是不眠夜，聲聲在耳邊。"]', '["子規啼不歇，到晓口應穿。","況是不眠夜，声声在耳邊。"]', '诗', 'shi', '', NULL, '夜聞子規 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f22731db-7c73-4122-b5ee-998b1c153c4b', '四望驛松', '四望驛松', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["當初北澗別，直至此庭中。","何意聞鞞耳，聽君枝上風。"]', '["當初北澗別，直至此庭中。","何意闻鞞耳，听君枝上风。"]', '诗', 'shi', '', NULL, '四望驛松 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b063dd-11e1-4f20-92e0-e5d475c8e77a', '江館', '江館', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["水面細風生，菱歌慢慢聲。","客亭臨小市，燈火夜妝明。"]', '["水面細风生，菱歌慢慢声。","客亭臨小市，灯火夜妝明。"]', '诗', 'shi', '', NULL, '江館 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fed83da-d1ee-45de-b792-0a4e404df0fd', '題江臺驛', '題江台驛', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["水北金臺路，年年行客稀。","近聞天子使，多取雁門歸。"]', '["水北金台路，年年行客稀。","近闻天子使，多取雁门归。"]', '诗', 'shi', '', NULL, '題江臺驛 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342ad256-e8c4-4d7a-b3a9-ad6accd335e8', '贈謫者', '贈謫者', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["何罪過長沙，年年北望家。","重封嶺頭信，一樹海邊花。"]', '["何罪過长沙，年年北望家。","重封嶺头信，一樹海邊花。"]', '诗', 'shi', '', NULL, '贈謫者 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a0b0f07-a9fb-41ed-941c-63c7aa90b6b3', '戲酬盧秘書', '戲酬盧秘书', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["芸香閣裏人，採摘御園春。","取此和仙藥，猶治老病身。"]', '["芸香閣裏人，採摘御园春。","取此和仙藥，猶治老病身。"]', '诗', 'shi', '', NULL, '戲酬盧秘書 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8564e4ef-9502-4ddd-952d-7879f3790fa9', '小松', '小松', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["小松初數尺，未有直生枝。","閑即傍邊立，看多長却遲。"]', '["小松初數尺，未有直生枝。","闲即傍邊立，看多长却遲。"]', '诗', 'shi', '', NULL, '小松 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64fdab52-e6d2-410e-8bde-aba1429c4b56', '秋夜', '秋夜', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["夜久葉露滴，秋蟲入戶飛。","臥多骨髓冷，起覆舊綿衣。"]', '["夜久葉露滴，秋蟲入戶飞。","臥多骨髓冷，起覆旧綿衣。"]', '诗', 'shi', '', NULL, '秋夜 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a93bc9-1d69-4dfa-8525-c6d99b6c17c8', '水精', '水精', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["映水色不別，向月光還度。","傾在荷葉中，有時看是露。"]', '["映水色不別，向月光還度。","傾在荷葉中，有时看是露。"]', '诗', 'shi', '', NULL, '水精 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9952526-56d6-4fe5-a44f-44f2d8cff826', '香印', '香印', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["閑坐燒印香，滿戶松柏氣。","火盡轉分明，青苔碑上字。"]', '["闲坐燒印香，满戶松柏氣。","火尽轉分明，青苔碑上字。"]', '诗', 'shi', '', NULL, '香印 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60cc0c7d-7a16-4474-9e97-710f3f5ba362', '秋燈', '秋灯', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["向壁暖悠悠，羅幃寒寂寂。","斜照碧山圖，松間一片石。"]', '["向壁暖悠悠，羅幃寒寂寂。","斜照碧山圖，松间一片石。"]', '诗', 'shi', '', NULL, '秋燈 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b463e3-0634-4be4-8d69-935d41bb76ba', '落葉', '落葉', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["陳綠向參差，初紅已重疊。","中庭初掃地，繞樹三兩葉。"]', '["陳綠向參差，初紅已重叠。","中庭初掃地，繞樹三兩葉。"]', '诗', 'shi', '', NULL, '落葉 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb272bc-5660-4a2f-8c56-cff401d964da', '園果', '园果', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雨中棃果病，每樹無數箇。","小兒出入看，一半鳥啄破。"]', '["雨中棃果病，每樹無數箇。","小兒出入看，一半鸟啄破。"]', '诗', 'shi', '', NULL, '園果 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1ee060-5750-4c9b-8c75-6080912cbe17', '野菊', '野菊', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["晚豔出荒籬，冷香著秋水。","憶向山中見，伴蛩石壁裏。"]', '["晚豔出荒籬，冷香著秋水。","憶向山中见，伴蛩石壁裏。"]', '诗', 'shi', '', NULL, '野菊 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69fb354c-b79e-49ff-b5af-3ebda8e78467', '荒園', '荒园', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["朝日滿園霜，牛衝籬落壞。","掃掠黃葉中，時時一窠薤。"]', '["朝日满园霜，牛衝籬落壞。","掃掠黄葉中，时时一窠薤。"]', '诗', 'shi', '', NULL, '荒園 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e60091b4-ed57-4889-93ef-7134cd4a235a', '南澗', '南澗', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["野桂香滿溪，石莎寒覆水。","愛此南澗頭，終日潺湲裏。"]', '["野桂香满溪，石莎寒覆水。","愛此南澗头，終日潺湲裏。"]', '诗', 'shi', '', NULL, '南澗 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed75c18-bb15-43f6-8a59-694c872b9f2f', '晚蝶', '晚蝶', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["粉翅嫩如水，繞砌乍依風。","日高山露解，飛入菊花中。"]', '["粉翅嫩如水，繞砌乍依风。","日高山露解，飞入菊花中。"]', '诗', 'shi', '', NULL, '晚蝶 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7546c4ad-9315-40c4-b334-8650fa5b17a5', '田家', '田家', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["啾啾雀滿樹，靄靄東坡雨。","田家夜無食，水中摘禾黍。"]', '["啾啾雀满樹，靄靄东坡雨。","田家夜無食，水中摘禾黍。"]', '诗', 'shi', '', NULL, '田家 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb88df8-f09c-42ef-86ef-5e022a5831b4', '新嫁娘詞三首 一', '新嫁娘词三首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鄰家人未識，牀上坐堆堆。","郎來傍門戶，滿口索錢財。"]', '["鄰家人未識，牀上坐堆堆。","郎来傍门戶，满口索錢財。"]', '诗', 'shi', '', NULL, '新嫁娘詞三首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7bced0-9f84-409b-b035-38ae5a143842', '新嫁娘詞三首 二', '新嫁娘词三首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["錦幛兩邊橫，遮掩侍娘行。","遣郎鋪簟席，相並拜親情。"]', '["錦幛兩邊橫，遮掩侍娘行。","遣郎鋪簟席，相並拜親情。"]', '诗', 'shi', '', NULL, '新嫁娘詞三首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efaaa86e-5628-40d3-a137-1ae8fcbe41b8', '新嫁娘詞三首 三', '新嫁娘词三首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["三日入廚下，洗手作羹湯。","未諳姑食性，先遣小姑嘗。"]', '["三日入廚下，洗手作羹湯。","未諳姑食性，先遣小姑嘗。"]', '诗', 'shi', '', NULL, '新嫁娘詞三首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6c85d29-ad02-4f54-a347-63800213a7b4', '故行宮', '故行宮', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["寥落古行宮，宮花寂寞紅。","白頭宮女在，閑坐說玄宗。"]', '["寥落古行宮，宮花寂寞紅。","白头宮女在，闲坐说玄宗。"]', '诗', 'shi', '', NULL, '故行宮 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('973818db-26cf-4b60-8bf3-e22f212d8dde', '酬從姪再看詩本', '酬從姪再看诗本', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["眼暗沒功夫，慵來翦刻麤。","自看花樣古，稱得少年無。"]', '["眼暗沒功夫，慵来翦刻麤。","自看花樣古，稱得少年無。"]', '诗', 'shi', '', NULL, '酬從姪再看詩本 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aecb258-38b9-4f80-96cc-64f14f9825fd', '別自栽小樹', '別自栽小樹', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["去年今日栽，臨去見花開。","好住守空院，夜間人不來。"]', '["去年今日栽，臨去见花开。","好住守空院，夜间人不来。"]', '诗', 'shi', '', NULL, '別自栽小樹 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c12466c3-75d2-4ec2-b5cc-11f49bdaf1ed', '早發汾南', '早發汾南', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["橋上車馬發，橋南煙樹開。","青山斜不斷，迢遞故鄉來。"]', '["橋上车马發，橋南煙樹开。","青山斜不斷，迢遞故乡来。"]', '诗', 'shi', '', NULL, '早發汾南 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9390075-3566-448f-b2f2-f1147059926d', '宮中三臺詞二首 一', '宮中三台词二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["魚藻池邊射鴨，芙蓉園裏看花。","日色柘袍相似，不著紅鸞扇遮。"]', '["鱼藻池邊射鴨，芙蓉园裏看花。","日色柘袍相似，不著紅鸾扇遮。"]', '诗', 'shi', '', NULL, '宮中三臺詞二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c14bd729-8560-4c4c-b37d-e5e9828fa655', '宮中三臺詞二首 二', '宮中三台词二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["池北池南草綠，殿前殿後花紅。","天子千年萬歲，未央明月清風。"]', '["池北池南草綠，殿前殿後花紅。","天子千年万歲，未央明月清风。"]', '诗', 'shi', '', NULL, '宮中三臺詞二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('334b1989-6f9f-411a-abc3-471ae51ac8fe', '江南三臺詞四首 一', '江南三台词四首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["揚州橋邊少婦，長安城裏商人。","二年不得消息，各自拜鬼求神。"]', '["揚州橋邊少婦，长安城裏商人。","二年不得消息，各自拜鬼求神。"]', '诗', 'shi', '', NULL, '江南三臺詞四首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f434ec24-50d5-4024-80be-07252d574be4', '江南三臺詞四首 二', '江南三台词四首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["青草湖邊草色，飛猿嶺上猿聲。","萬里湘江客到，有風有雨人行。"]', '["青草湖邊草色，飞猿嶺上猿声。","万里湘江客到，有风有雨人行。"]', '诗', 'shi', '', NULL, '江南三臺詞四首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da48d016-0cc5-4350-b24f-27cbf145391b', '江南三臺詞四首 三', '江南三台词四首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["樹頭花落花開，道上人去人來。","朝愁暮愁即老，百年幾度三臺。"]', '["樹头花落花开，道上人去人来。","朝愁暮愁即老，百年幾度三台。"]', '诗', 'shi', '', NULL, '江南三臺詞四首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66593163-046a-42fe-8227-4efe7fdfc9ce', '江南三臺詞四首 四', '江南三台词四首 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["聞身強健且爲，頭白齒落難追。","準擬百年千歲，能得幾許多時。"]', '["闻身強健且爲，头白齒落难追。","準擬百年千歲，能得幾許多时。"]', '诗', 'shi', '', NULL, '江南三臺詞四首 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1f0b4b-b46e-4cf8-848c-d89260a5ca47', '御獵', '御獵', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["青山直遶鳳城頭，滻水斜分入御溝。","新教內人唯射鴨，長隨天子苑東遊。"]', '["青山直遶鳳城头，滻水斜分入御溝。","新教內人唯射鴨，长隨天子苑东游。"]', '诗', 'shi', '', NULL, '御獵 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ab425a-47bb-403c-bed4-e3f6cea59cd2', '長門燭', '长门燭', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["秋夜牀前蠟燭微，銅壺滴盡曉鐘遲。","殘光欲滅還吹著，年少宮人未睡時。"]', '["秋夜牀前蠟燭微，銅壺滴尽晓鐘遲。","殘光欲滅還吹著，年少宮人未睡时。"]', '诗', 'shi', '', NULL, '長門燭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd06d4b0-fd55-438b-92b7-bfa2109e51a9', '過綺岫宮', '過綺岫宮', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["玉樓傾倒粉牆空，重疊青山遶故宮。","武帝去來羅袖盡，野花黃蝶領春風。"]', '["玉楼傾倒粉牆空，重叠青山遶故宮。","武帝去来羅袖尽，野花黄蝶領春风。"]', '诗', 'shi', '', NULL, '過綺岫宮 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('325c9e2a-6ca7-4d91-b076-d5dad743b93b', '朝天詞十首寄上魏博田侍中 一', '朝天词十首寄上魏博田侍中 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["山川初展國圖寬，未識龍顏坐不安。","風動白髯旌節下，過時天子御樓看。"]', '["山川初展国圖寬，未識龙顏坐不安。","风动白髯旌節下，過时天子御楼看。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63607944-267b-4810-97e9-31b235b24fd8', '朝天詞十首寄上魏博田侍中 二', '朝天词十首寄上魏博田侍中 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["相感君臣總淚流，恩深舞蹈不知休。","初從戰地來無物，唯奏新添十八州。"]', '["相感君臣總泪流，恩深舞蹈不知休。","初從戰地来無物，唯奏新添十八州。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da9bb588-3815-4451-9d8c-2e6e26e29752', '朝天詞十首寄上魏博田侍中 三', '朝天词十首寄上魏博田侍中 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["催修水殿宴沂公，與別諸候總不同。","隔月太常先習樂，金書牌纛彩雲中。"]', '["催修水殿宴沂公，與別諸候總不同。","隔月太常先習乐，金书牌纛彩云中。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f57ae3b8-f969-4a3a-93a4-3e3f4cfb2e36', '朝天詞十首寄上魏博田侍中 四', '朝天词十首寄上魏博田侍中 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["無人敢奪在先籌，天子門邊送與毬。","遙索綵箱新樣錦，內人舁出馬前頭。"]', '["無人敢奪在先籌，天子门邊送與毬。","遙索綵箱新樣錦，內人舁出马前头。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e32ab972-dd13-4cb1-90dd-e5cf930080c9', '朝天詞十首寄上魏博田侍中 五', '朝天词十首寄上魏博田侍中 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["御馬牽來親自試，珠毬到處玉蹄知。","殿頭宣賜連催上，未解紅纓不敢騎。"]', '["御马牽来親自試，珠毬到处玉蹄知。","殿头宣賜連催上，未解紅纓不敢騎。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d07fa66-b7b9-4f94-81bf-19b233c132ce', '朝天詞十首寄上魏博田侍中 六', '朝天词十首寄上魏博田侍中 六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["老作三公經獻壽，臨時猶自語差池。","私從班裏來長跪，捧上金杯便合儀。"]', '["老作三公經獻壽，臨时猶自語差池。","私從班裏来长跪，捧上金杯便合儀。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('035e142c-723d-4c7a-9df8-91c623fa3674', '朝天詞十首寄上魏博田侍中 七', '朝天词十首寄上魏博田侍中 七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["四海無波乞放閑，三封手疏犯龍顏。","他時若有邊塵動，不待天書自出山。"]', '["四海無波乞放闲，三封手疏犯龙顏。","他时若有邊塵动，不待天书自出山。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a716fe00-9b22-43e7-a2bf-e6fd8ad0c747', '朝天詞十首寄上魏博田侍中 八', '朝天词十首寄上魏博田侍中 八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["胡馬悠悠未盡歸，玉關猶隔吐蕃旗。","老臣一表求高臥，邊事從今欲問誰。"]', '["胡马悠悠未尽归，玉关猶隔吐蕃旗。","老臣一表求高臥，邊事從今欲问誰。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d7c9ed1-9b1f-4996-a3d4-59950a4d3c18', '朝天詞十首寄上魏博田侍中 九', '朝天词十首寄上魏博田侍中 九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["威容難畫改頻頻，眉目分毫恐不真。","有詔別圖書閣上，先教粉本定風神。"]', '["威容难畫改頻頻，眉目分毫恐不真。","有詔別圖书閣上，先教粉本定风神。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab61f08b-a616-4620-8b34-a348a42833f2', '朝天詞十首寄上魏博田侍中 十', '朝天词十首寄上魏博田侍中 十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["重賜弓刀內宴回，看人城外滿樓臺。","君臣不作多時別，收盡邊旗當日來。"]', '["重賜弓刀內宴回，看人城外满楼台。","君臣不作多时別，收尽邊旗當日来。"]', '诗', 'shi', '', NULL, '朝天詞十首寄上魏博田侍中 十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c6ed3e-f919-4714-bd66-9027266166eb', '霓裳詞十首 一', '霓裳词十首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["弟子部中留一色，聽風聽水作霓裳。","散聲未足重來授，直到牀前見上皇。"]', '["弟子部中留一色，听风听水作霓裳。","散声未足重来授，直到牀前见上皇。"]', '诗', 'shi', '', NULL, '霓裳詞十首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b88d670-c288-43cf-b13f-5f0837859cdf', '霓裳詞十首 二', '霓裳词十首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["中管五弦初半曲，遙教合上隔簾聽。","一聲聲向天頭落，效得仙人夜唱經。"]', '["中管五弦初半曲，遙教合上隔簾听。","一声声向天头落，效得仙人夜唱經。"]', '诗', 'shi', '', NULL, '霓裳詞十首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a288380f-6d60-4cd3-8472-0b2ffc7cbc7a', '霓裳詞十首 三', '霓裳词十首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自直棃園得出稀，更番上曲不教歸。","一時跪拜霓裳徹，立地階前賜紫衣。"]', '["自直棃园得出稀，更番上曲不教归。","一时跪拜霓裳徹，立地階前賜紫衣。"]', '诗', 'shi', '', NULL, '霓裳詞十首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9045eea5-b5d5-4783-9002-244b5a8e943e', '霓裳詞十首 四', '霓裳词十首 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["旋翻新譜聲初足，除却棃園未教人。","宣與書家分手寫，中官走馬賜功臣。"]', '["旋翻新譜声初足，除却棃园未教人。","宣與书家分手寫，中官走马賜功臣。"]', '诗', 'shi', '', NULL, '霓裳詞十首 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19385e57-2a5e-4113-aa82-65edf85f1345', '霓裳詞十首 五', '霓裳词十首 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["伴教霓裳有貴妃，從初直到曲成時。","日長耳裏聞聲熟，拍數分毫錯總知。"]', '["伴教霓裳有貴妃，從初直到曲成时。","日长耳裏闻声熟，拍數分毫錯總知。"]', '诗', 'shi', '', NULL, '霓裳詞十首 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f2e1cd-6453-4911-a00c-27526448ae41', '霓裳詞十首 六', '霓裳词十首 六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["弦索摐摐隔綵雲，五更初發一山聞。","武皇自送西王母，新換霓裳月色裙。"]', '["弦索摐摐隔綵云，五更初發一山闻。","武皇自送西王母，新換霓裳月色裙。"]', '诗', 'shi', '', NULL, '霓裳詞十首 六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afcdcc57-3da0-43f5-828b-6e4bd641c271', '霓裳詞十首 七', '霓裳词十首 七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["敕賜宮人澡浴回，遙看美女院門開。","一山星月霓裳動，好字先從殿裏來。"]', '["敕賜宮人澡浴回，遙看美女院门开。","一山星月霓裳动，好字先從殿裏来。"]', '诗', 'shi', '', NULL, '霓裳詞十首 七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f698d3e5-621b-4717-bae9-80d4e6292e0c', '霓裳詞十首 八', '霓裳词十首 八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["傳呼法部按霓裳，新得承恩別作行。","應是貴妃樓上看，內人舁下綵羅箱。"]', '["傳呼法部按霓裳，新得承恩別作行。","應是貴妃楼上看，內人舁下綵羅箱。"]', '诗', 'shi', '', NULL, '霓裳詞十首 八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9bf8fc8-0376-4f66-aca3-4915726e3eb8', '霓裳詞十首 九', '霓裳词十首 九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["朝元閣上山風起，夜聽霓裳玉露寒。","宮女月中更替立，黃金梯滑並行難。"]', '["朝元閣上山风起，夜听霓裳玉露寒。","宮女月中更替立，黄金梯滑並行难。"]', '诗', 'shi', '', NULL, '霓裳詞十首 九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba83c93-e69c-4685-b220-4d37759a6095', '霓裳詞十首 十', '霓裳词十首 十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["知向華清年月滿，山頭山底種長生。","去時留下霓裳曲，總是離宮別館聲。"]', '["知向华清年月满，山头山底種长生。","去时留下霓裳曲，總是離宮別館声。"]', '诗', 'shi', '', NULL, '霓裳詞十首 十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3199cc3-01a0-44a9-a090-35b1c8ea6129', '宮前早春', '宮前早春', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["酒幔高樓一百家，宮前楊柳寺前花。","內園分得溫湯水，二月中旬已進瓜。"]', '["酒幔高楼一百家，宮前楊柳寺前花。","內园分得溫湯水，二月中旬已進瓜。"]', '诗', 'shi', '', NULL, '宮前早春 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a798dc05-a953-4a61-9719-bfbf95b92e5f', '奉同曾郎中題石甕寺得嵌韻', '奉同曾郎中題石甕寺得嵌韻', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["寺門連內遶丹巖，下界雲開數過帆。","遙指上皇翻曲處，百官題字滿西嵌。"]', '["寺门連內遶丹巖，下界云开數過帆。","遙指上皇翻曲处，百官題字满西嵌。"]', '诗', 'shi', '', NULL, '奉同曾郎中題石甕寺得嵌韻 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f107b6fe-9934-49d0-b6f0-7665640f60ae', '舊宮人', '旧宮人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["先帝舊宮宮女在，亂絲猶挂鳳皇釵。","霓裳法曲渾拋却，獨自花間埽玉堦。"]', '["先帝旧宮宮女在，亂絲猶挂鳳皇釵。","霓裳法曲渾拋却，独自花间埽玉堦。"]', '诗', 'shi', '', NULL, '舊宮人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abbd2286-1f7e-4974-abc8-94c593359714', '新授戒尼師', '新授戒尼師', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新短方裙疊作稜，聽鐘洗鉢繞青蠅。","自知戒相分明後，先出壇場禮大僧。"]', '["新短方裙叠作稜，听鐘洗鉢繞青蠅。","自知戒相分明後，先出壇場禮大僧。"]', '诗', 'shi', '', NULL, '新授戒尼師 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e926b041-c871-4752-8e3e-c6234d62fa75', '太和公主和蕃', '太和公主和蕃', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["塞黑雲黃欲渡河，風沙瞇眼雪相和。","琵琶淚濕行聲小，斷得人腸不在多。"]', '["塞黑云黄欲渡河，风沙瞇眼雪相和。","琵琶泪濕行声小，斷得人腸不在多。"]', '诗', 'shi', '', NULL, '太和公主和蕃 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c98cbf-8dbf-45d1-8e67-d8b325af766a', '元太守同遊七泉寺', '元太守同游七泉寺', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["盤磴回廊古塔深，紫芝紅藥入雲尋。","晚吹簫管秋山裏，引得獼猴出象林。"]', '["盤磴回廊古塔深，紫芝紅藥入云尋。","晚吹簫管秋山裏，引得獼猴出象林。"]', '诗', 'shi', '', NULL, '元太守同遊七泉寺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e321175f-9b6a-4431-9b7b-dd63621bd55b', '望定州寺', '望定州寺', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["回看佛閣青山半，三四年前到上頭。","省得老僧留不住，重尋更可有因由。"]', '["回看佛閣青山半，三四年前到上头。","省得老僧留不住，重尋更可有因由。"]', '诗', 'shi', '', NULL, '望定州寺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4596457b-eaa3-4f6e-9ef4-187d56f60031', '道中寄杜書記', '道中寄杜书記', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["西南東北暮天斜，巴字江邊楚樹花。","珍重荆州杜書記，閑時多在廣師家。"]', '["西南东北暮天斜，巴字江邊楚樹花。","珍重荆州杜书記，闲时多在廣師家。"]', '诗', 'shi', '', NULL, '道中寄杜書記 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23d4fe8-e02b-45c1-85de-18adaa8b74e6', '聽琴', '听琴', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["無事此身離白雲，松風溪水不曾聞。","至心聽著仙翁引，今看青山圍繞君。"]', '["無事此身離白云，松风溪水不曾闻。","至心听著仙翁引，今看青山圍繞君。"]', '诗', 'shi', '', NULL, '聽琴 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37687b5-fdf6-41c3-bcf5-ec8780de5f2b', '贈陳評事', '贈陳評事', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["識君雖向歌鐘會，說事不離雲水間。","春夜酒醒長起坐，燈前一紙洞庭山。"]', '["識君雖向歌鐘會，说事不離云水间。","春夜酒醒长起坐，灯前一紙洞庭山。"]', '诗', 'shi', '', NULL, '贈陳評事 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb0fb1db-133b-47be-91c1-5191a6529bd7', '寄畫松僧', '寄畫松僧', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天香寺裏古松僧，不畫枯松落石層。","最愛臨江兩三樹，水禽棲處解無藤。"]', '["天香寺裏古松僧，不畫枯松落石層。","最愛臨江兩三樹，水禽棲处解無藤。"]', '诗', 'shi', '', NULL, '寄畫松僧 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c772c8-74da-4e97-bdc4-83b9806650b7', '花褐裘', '花褐裘', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["對織芭蕉雪毳新，長縫雙袖窄裁身。","到頭須向邊城著，消殺秋風稱獵塵。"]', '["对织芭蕉雪毳新，长縫雙袖窄裁身。","到头須向邊城著，消殺秋风稱獵塵。"]', '诗', 'shi', '', NULL, '花褐裘 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620e2d04-2cd5-4217-a8f0-64837017c7e4', '夜看美人宮棊', '夜看美人宮棊', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宮棊布局不依經，黑白分明子數停。","巡拾玉沙天漢曉，猶殘織女兩三星。"]', '["宮棊布局不依經，黑白分明子數停。","巡拾玉沙天漢晓，猶殘织女兩三星。"]', '诗', 'shi', '', NULL, '夜看美人宮棊 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46dae050-2936-49c0-8e85-618f626602df', '上田僕射', '上田僕射', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一方新地隔河煙，曾接諸生聽管弦。","却憶去年寒食會，看花猶在水堂前。"]', '["一方新地隔河煙，曾接諸生听管弦。","却憶去年寒食會，看花猶在水堂前。"]', '诗', 'shi', '', NULL, '上田僕射 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3498cc32-040b-45d0-8371-f6352b2f11bd', '江陵道中', '江陵道中', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["菱葉參差萍葉重，新蒲半折夜來風。","江村水落平地出，溪畔漁船青草中。"]', '["菱葉參差萍葉重，新蒲半折夜来风。","江村水落平地出，溪畔漁船青草中。"]', '诗', 'shi', '', NULL, '江陵道中 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15eaceec-b21b-4943-aceb-04490e80b8c3', '冬至後招于秀才', '冬至後招于秀才', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["日近山紅暖氣新，一陽先入御溝春。","聞閑立馬重來此，沐浴明年稱意身。"]', '["日近山紅暖氣新，一陽先入御溝春。","闻闲立马重来此，沐浴明年稱意身。"]', '诗', 'shi', '', NULL, '冬至後招于秀才 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab8d4ae-c0f3-4171-a099-3828bcefe2a6', '別曲', '別曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["毒蛇在腸瘡滿背，去年別家今別弟。","馬頭對哭各東西，天邊柳絮無根蔕。"]', '["毒蛇在腸瘡满背，去年別家今別弟。","马头对哭各东西，天邊柳絮無根蔕。"]', '诗', 'shi', '', NULL, '別曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1a95aaa-b46f-4ffb-8d2b-99c775e543eb', '長安別', '长安別', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長安清明好時節，只宜相送不宜別。","惡心牀上銅片明，照見離人白頭髮。"]', '["长安清明好时節，只宜相送不宜別。","惡心牀上銅片明，照见離人白头髮。"]', '诗', 'shi', '', NULL, '長安別 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99cc619a-eb30-4f1f-97b7-279c11d84c82', '宮人斜', '宮人斜', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["未央牆西青草路，宮人斜裏紅妝墓。","一邊載出一邊來，更衣不減尋常數。"]', '["未央牆西青草路，宮人斜裏紅妝墓。","一邊載出一邊来，更衣不減尋常數。"]', '诗', 'shi', '', NULL, '宮人斜 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e45ad205-446b-4c7b-81fc-7d3e924dacea', '春詞', '春词', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["良人朝早半夜起，櫻桃如珠露如水。","下堂把火送郎回，移枕重眠曉窗裏。"]', '["良人朝早半夜起，櫻桃如珠露如水。","下堂把火送郎回，移枕重眠晓窗裏。"]', '诗', 'shi', '', NULL, '春詞 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33dcb0f7-faf3-4af8-a759-81dbcbb130b4', '野池', '野池', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["野池水滿連秋隄，菱花結實蒲葉齊。","川口雨晴風復止，蜻蜓上下魚東西。"]', '["野池水满連秋隄，菱花結實蒲葉齊。","川口雨晴风复止，蜻蜓上下鱼东西。"]', '诗', 'shi', '', NULL, '野池 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5548eba3-d209-400d-afd5-6157bb51c4c5', '題崔秀才里居', '題崔秀才里居', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自知名出休呈卷，愛去人家遠處居。","時復打門無別事，鋪頭來索買殘書。"]', '["自知名出休呈卷，愛去人家远处居。","时复打门無別事，鋪头来索買殘书。"]', '诗', 'shi', '', NULL, '題崔秀才里居 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb82f85b-d97b-48f9-816c-b7dc0092e098', '酬栢侍御荅酒', '酬栢侍御荅酒', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["茱萸酒法大家同，好是盛來白椀中。","這度自知顏色重，不消詩裏弄溪翁。"]', '["茱萸酒法大家同，好是盛来白椀中。","這度自知顏色重，不消诗裏弄溪翁。"]', '诗', 'shi', '', NULL, '酬栢侍御荅酒 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb7737e-914a-4ad7-a032-489d17e154b2', '別藥欄', '別藥欄', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["芍藥丁香手裏栽，臨行一日繞千回。","外人應怪難辭別，總是山中自取來。"]', '["芍藥丁香手裏栽，臨行一日繞千回。","外人應怪难辞別，總是山中自取来。"]', '诗', 'shi', '', NULL, '別藥欄 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aefa3e9-7950-497c-aa54-00890e756c2d', '長門', '长门', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長門閉定不求生，燒却頭花卸却箏。","病臥玉窗秋雨下，遙聞別院喚人聲。"]', '["长门閉定不求生，燒却头花卸却箏。","病臥玉窗秋雨下，遙闻別院喚人声。"]', '诗', 'shi', '', NULL, '長門 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf94d502-d196-4e83-aa2f-86e9284cf102', '題渭亭', '題渭亭', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雲開遠水傍秋天，沙岸蒲帆隔野煙。","一片蔡州青草色，日西鋪在古臺邊。"]', '["云开远水傍秋天，沙岸蒲帆隔野煙。","一片蔡州青草色，日西鋪在古台邊。"]', '诗', 'shi', '', NULL, '題渭亭 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac3d7d0-5c12-4c90-a4c7-a9bda256bd2d', '過喜祥山館', '過喜祥山館', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["夜過深山算驛程，三回黑地聽泉聲。","自離軍馬身輕健，得向溪邊盡足行。"]', '["夜過深山算驛程，三回黑地听泉声。","自離軍马身轻健，得向溪邊尽足行。"]', '诗', 'shi', '', NULL, '過喜祥山館 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4430674-7a00-407d-bba2-a17ae04e5909', '送遷客', '送遷客', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["萬里潮州一逐臣，悠悠青草海邊春。","天涯莫道無回日，上嶺還逢向北人。"]', '["万里潮州一逐臣，悠悠青草海邊春。","天涯莫道無回日，上嶺還逢向北人。"]', '诗', 'shi', '', NULL, '送遷客 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5839f015-8e31-4fc5-91fc-422798d98f04', '廢寺', '廢寺', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["廢寺亂來爲縣驛，荒松老柏不生煙。","空廊屋漏畫僧盡，梁上猶書天寶年。"]', '["廢寺亂来爲縣驛，荒松老柏不生煙。","空廊屋漏畫僧尽，梁上猶书天寶年。"]', '诗', 'shi', '', NULL, '廢寺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('525dabc8-bbfc-42a8-b4e7-41ed2125dcc8', '題禪師房', '題禪師房', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["浮生不住葉隨風，填海移山總是空。","長向人間愁老病，誰來閑坐此房中。"]', '["浮生不住葉隨风，填海移山總是空。","长向人间愁老病，誰来闲坐此房中。"]', '诗', 'shi', '', NULL, '題禪師房 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7cd746a-92b3-4eb0-a841-4bb1a76d730a', '看石楠花', '看石楠花', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["留得行人忘却歸，雨中須是石楠枝。","明朝獨上銅臺路，容見花開少許時。"]', '["留得行人忘却归，雨中須是石楠枝。","明朝独上銅台路，容见花开少許时。"]', '诗', 'shi', '', NULL, '看石楠花 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6652dea-e6aa-4e6c-af27-259c0b65b6d5', '長安縣後亭看畫', '长安縣後亭看畫', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["水凍橫橋雪滿池，新排石笋繞巴籬。","縣門斜掩無人吏，看畫雙飛白鷺鷥。"]', '["水凍橫橋雪满池，新排石笋繞巴籬。","縣门斜掩無人吏，看畫雙飞白鷺鷥。"]', '诗', 'shi', '', NULL, '長安縣後亭看畫 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba0ec5f3-26b3-4e40-83b9-48a8f9e37464', '華嶽廟二首 一', '华嶽廟二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["女巫遮客買神盤，爭取琵琶廟裏彈。","聞有馬蹄生拍樹，路人來去向南看。"]', '["女巫遮客買神盤，爭取琵琶廟裏彈。","闻有马蹄生拍樹，路人来去向南看。"]', '诗', 'shi', '', NULL, '華嶽廟二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('819b1dd4-1b06-4130-a9af-4bf9c179b3e0', '華嶽廟二首 二', '华嶽廟二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自移西嶽門長鎖，一箇行人一遍開。","上廟參天今見在，夜頭風起覺神來。"]', '["自移西嶽门长鎖，一箇行人一遍开。","上廟參天今见在，夜头风起覺神来。"]', '诗', 'shi', '', NULL, '華嶽廟二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('543b213a-914b-43c4-b377-0bb8ec1e4d90', '酬趙侍御', '酬趙侍御', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["年少同爲鄴下游，閑尋野寺醉登樓。","別來衣馬從勝舊，爭向邊塵滿白頭。"]', '["年少同爲鄴下游，闲尋野寺醉登楼。","別来衣马從勝旧，爭向邊塵满白头。"]', '诗', 'shi', '', NULL, '酬趙侍御 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec310b54-45a8-4e02-af27-d76da2184edd', '鑷白', '鑷白', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["總道老來無用處，何須白髮在前生。","如今不用偷年少，拔却三莖又五莖。"]', '["總道老来無用处，何須白髮在前生。","如今不用偷年少，拔却三莖又五莖。"]', '诗', 'shi', '', NULL, '鑷白 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dcbb7d7-7992-4eb7-b008-2a2749609a65', '送山人二首 一', '送山人二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["嵩山古寺離來久。","回見溪橋野葉黃，辛苦老師看守處。","爲懸秋藥閉空房。"]', '["嵩山古寺離来久。","回见溪橋野葉黄，辛苦老師看守处。","爲懸秋藥閉空房。"]', '诗', 'shi', '', NULL, '送山人二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8cd61b-2108-47b8-b9df-7d15ebffe805', '送山人二首 二', '送山人二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["山客狂來跨白驢，袖中遺却潁陽書。","人間亦有妻兒在，拋向嵩陽古觀居。"]', '["山客狂来跨白驢，袖中遺却潁陽书。","人间亦有妻兒在，拋向嵩陽古观居。"]', '诗', 'shi', '', NULL, '送山人二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac09f79-9160-47ac-a986-507617902179', '揚州尋張籍不見', '揚州尋張籍不见', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["別後知君在楚城，揚州寺裏覓君名。","西江水闊吳山遠，却打船頭向北行。"]', '["別後知君在楚城，揚州寺裏覓君名。","西江水闊吳山远，却打船头向北行。"]', '诗', 'shi', '', NULL, '揚州尋張籍不見 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1c88932-0054-45d5-9d51-9bfdaa799865', '宿長安縣後齋', '宿长安縣後斋', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新向金階奏罷兵，長安縣裏繞池行。","喜歡得伴山僧宿，看雪吟詩直到明。"]', '["新向金階奏罷兵，长安縣裏繞池行。","喜歡得伴山僧宿，看雪吟诗直到明。"]', '诗', 'shi', '', NULL, '宿長安縣後齋 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3171ee8-76b4-41bb-85ec-d0514bc4ec3a', '夜看揚州市', '夜看揚州市', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["夜市千燈照碧雲，高樓紅袖客紛紛。","如今不似時平日，猶自笙歌徹曉聞。"]', '["夜市千灯照碧云，高楼紅袖客紛紛。","如今不似时平日，猶自笙歌徹晓闻。"]', '诗', 'shi', '', NULL, '夜看揚州市 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2466d720-86c9-47e0-b8f0-8f4c4a2585c8', '寄韋諫議', '寄韋諫議', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["百年看似暫時間，頭白求官亦未閑。","獨有龍門韋諫議，三徵不起戀青山。"]', '["百年看似暫时间，头白求官亦未闲。","独有龙门韋諫議，三徵不起戀青山。"]', '诗', 'shi', '', NULL, '寄韋諫議 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6848ad-db6c-43c7-86ba-5b579b100a35', '尋補闕舊宅', '尋補闕旧宅', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["知得清名二十年，登山上坂乞新篇。","除書近拜侍臣去，空院鳥啼風竹前。"]', '["知得清名二十年，登山上坂乞新篇。","除书近拜侍臣去，空院鸟啼风竹前。"]', '诗', 'shi', '', NULL, '尋補闕舊宅 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e44b6215-6bb8-4cf4-851c-e524334f84ad', '初冬旅遊', '初冬旅游', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["遠投人宿趁房遲，僮僕傷寒馬亦飢。","爲客悠悠十月盡，莊頭栽竹已過時。"]', '["远投人宿趁房遲，僮僕傷寒马亦飢。","爲客悠悠十月尽，莊头栽竹已過时。"]', '诗', 'shi', '', NULL, '初冬旅遊 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473ea995-013c-4aa8-a332-6e2bed131ddb', '江館對雨', '江館对雨', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鳥聲愁雨似秋天，病客思家一向眠。","草館門臨廣州路，夜聞蠻語小江邊。"]', '["鸟声愁雨似秋天，病客思家一向眠。","草館门臨廣州路，夜闻蠻語小江邊。"]', '诗', 'shi', '', NULL, '江館對雨 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0d2513-d896-4ce1-a06d-8810f696e545', '雨過山村', '雨過山村', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雨裏雞鳴一兩家，竹溪村路板橋斜。","婦姑相喚浴蠶去，閑看中庭梔子花。"]', '["雨裏雞鳴一兩家，竹溪村路板橋斜。","婦姑相喚浴蠶去，闲看中庭梔子花。"]', '诗', 'shi', '', NULL, '雨過山村 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d33abcca-535d-47ae-8cd9-725c0f0f1b5e', '山店', '山店', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["登登石路何時盡，決決溪泉到處聞。","風動葉聲山犬吠，一家松火隔秋雲。"]', '["登登石路何时尽，決決溪泉到处闻。","风动葉声山犬吠，一家松火隔秋云。"]', '诗', 'shi', '', NULL, '山店 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca16fd7a-26e1-431e-8ca9-21dc29a7a988', '雨中寄東溪韋處士', '雨中寄东溪韋处士', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雨中溪破無乾地，浸著牀頭濕著書。","一箇月來山水隔，不知茅屋若爲居。"]', '["雨中溪破無乾地，浸著牀头濕著书。","一箇月来山水隔，不知茅屋若爲居。"]', '诗', 'shi', '', NULL, '雨中寄東溪韋處士 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210ba813-2a72-42c0-ad24-23bab9962f5a', '乞竹', '乞竹', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["乞取池西三兩竿，房前栽著病時看。","亦知自惜難判割，猶勝橫根引出欄。"]', '["乞取池西三兩竿，房前栽著病时看。","亦知自惜难判割，猶勝橫根引出欄。"]', '诗', 'shi', '', NULL, '乞竹 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a792fe89-52b2-40d9-bd42-c4e8dc6949aa', '人家看花', '人家看花', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["年少狂疎逐君馬，去來憔悴到京華。","恨無閑地栽仙藥，長傍人家看好花。"]', '["年少狂疎逐君马，去来憔悴到京华。","恨無闲地栽仙藥，长傍人家看好花。"]', '诗', 'shi', '', NULL, '人家看花 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bbe646d-8cba-4ce4-83f0-be2335d014e5', '未央風', '未央风', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["五更先起玉階東，漸入千門萬戶中。","總向高樓吹舞袖，秋風還不及春風。"]', '["五更先起玉階东，漸入千门万戶中。","總向高楼吹舞袖，秋风還不及春风。"]', '诗', 'shi', '', NULL, '未央風 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c5ec2e-c2ac-4651-beb1-e135a51087d5', '歸山莊', '归山莊', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長安寄食半年餘，重向人邊乞薦書。","山路獨歸衝夜雪，落斜騎馬避柴車。"]', '["长安寄食半年餘，重向人邊乞薦书。","山路独归衝夜雪，落斜騎马避柴车。"]', '诗', 'shi', '', NULL, '歸山莊 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9894e249-6b01-4703-ae50-dbc73beb1249', '寒食憶歸', '寒食憶归', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["京中曹局無多事，寒食貧兒要在家。","遮莫杏園勝別處，亦須歸看傍村花。"]', '["京中曹局無多事，寒食貧兒要在家。","遮莫杏园勝別处，亦須归看傍村花。"]', '诗', 'shi', '', NULL, '寒食憶歸 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4c26bb-a622-4b23-b501-d9c3d94d8547', '留別張廣文', '留別張廣文', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["謝恩新入鳳皇城，亂定相逢合眼明。","千萬求方好將息，杏花寒食的同行。"]', '["謝恩新入鳳皇城，亂定相逢合眼明。","千万求方好將息，杏花寒食的同行。"]', '诗', 'shi', '', NULL, '留別張廣文 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53eb8316-b634-449c-8af7-c402bc9fe6c9', '送鄭山人歸山', '送鄭山人归山', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["玉作車轅蒲作輪，當初不起潁陽人。","一家總入嵩山去，天子何因得諫臣。"]', '["玉作车轅蒲作輪，當初不起潁陽人。","一家總入嵩山去，天子何因得諫臣。"]', '诗', 'shi', '', NULL, '送鄭山人歸山 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e125a1-8206-4227-a842-317875fa7d59', '傷墮水烏', '傷墮水烏', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一烏墮水百烏啼，相吊相號遶故堤。","眼見行人車輾過，不妨同伴各東西。"]', '["一烏墮水百烏啼，相吊相號遶故堤。","眼见行人车輾過，不妨同伴各东西。"]', '诗', 'shi', '', NULL, '傷墮水烏 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b8d611d-361b-4cdd-ad6a-7f840533d9f6', '看碁', '看碁', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["彼此抽先局勢平，傍人道死的還生。","兩邊對坐無言語，盡日時聞下子聲。"]', '["彼此抽先局勢平，傍人道死的還生。","兩邊对坐無言語，尽日时闻下子声。"]', '诗', 'shi', '', NULL, '看碁 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e41a0d-5d0e-420b-a07b-7612bf95243d', '設酒寄獨孤少府', '設酒寄独孤少府', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自看和釀一依方，緣看松花色較黃。","不分君家新酒熟，好詩收得被回將。"]', '["自看和釀一依方，緣看松花色較黄。","不分君家新酒熟，好诗收得被回將。"]', '诗', 'shi', '', NULL, '設酒寄獨孤少府 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727ef1d7-5360-49e3-9c70-2e02ec31fe40', '贈人二首 一', '贈人二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["金爐煙裏要班頭，欲得歸山可自由。","每度報朝愁入閣，在先教示小千牛。"]', '["金爐煙裏要班头，欲得归山可自由。","每度報朝愁入閣，在先教示小千牛。"]', '诗', 'shi', '', NULL, '贈人二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3517beea-e904-4f17-afa9-a2937b1fa386', '贈人二首 二', '贈人二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["多在蓬萊少在家，越緋衫上有紅霞。","朝回不向諸餘處，騎馬城西檢校花。"]', '["多在蓬萊少在家，越緋衫上有紅霞。","朝回不向諸餘处，騎马城西檢校花。"]', '诗', 'shi', '', NULL, '贈人二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ad3c3f-ec93-4855-89ca-ae75de234ed3', '樓前', '楼前', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天寶年前勤政樓，每年三日作千秋。","飛龍老馬曾教舞，聞著音聲總舉頭。"]', '["天寶年前勤政楼，每年三日作千秋。","飞龙老马曾教舞，闻著音声總舉头。"]', '诗', 'shi', '', NULL, '樓前 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b67af64-69c2-42ec-9df6-7cfc3258fe06', '寄劉蕡問疾', '寄劉蕡问疾', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["年少病多應爲酒，誰家將息過今春。","賒來半夏重熏盡，投著山中舊主人。"]', '["年少病多應爲酒，誰家將息過今春。","賒来半夏重熏尽，投著山中旧主人。"]', '诗', 'shi', '', NULL, '寄劉蕡問疾 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7b03c0-c364-464d-92cd-a5e0556d6dbe', '聽雨', '听雨', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["半夜思家睡裏愁，雨聲落落屋簷頭。","照泥星出依前黑，淹爛庭花不肯休。"]', '["半夜思家睡裏愁，雨声落落屋簷头。","照泥星出依前黑，淹爛庭花不肯休。"]', '诗', 'shi', '', NULL, '聽雨 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dc68d1-e571-485c-843d-cac07a7cab81', '新晴', '新晴', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["夏夜新晴星校少，雨收殘水入天河。","簷前熟著衣裳坐，風冷渾無撲火蛾。"]', '["夏夜新晴星校少，雨收殘水入天河。","簷前熟著衣裳坐，风冷渾無撲火蛾。"]', '诗', 'shi', '', NULL, '新晴 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b920d0-5616-48aa-9753-73af6ccf8813', '秋日後', '秋日後', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["住處近山常足雨，聞晴曬曝舊芳茵。","立秋日後無多熱，漸覺生衣不著身。"]', '["住处近山常足雨，闻晴曬曝旧芳茵。","立秋日後無多熱，漸覺生衣不著身。"]', '诗', 'shi', '', NULL, '秋日後 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('178dce62-9f2c-4c71-9097-efece2e43708', '哭孟東野二首 一', '哭孟东野二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["吟損秋天月不明，蘭無香氣鶴無聲。","自從東野先生死，側近雲山得散行。"]', '["吟損秋天月不明，蘭無香氣鹤無声。","自從东野先生死，側近云山得散行。"]', '诗', 'shi', '', NULL, '哭孟東野二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8919dad-b1f9-4bc8-a6e9-42c9b4f96e89', '哭孟東野二首 二', '哭孟东野二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["老松臨死不生枝，東野先生早哭兒。","但是洛陽城裏客，家傳一本杏殤詩。"]', '["老松臨死不生枝，东野先生早哭兒。","但是洛陽城裏客，家傳一本杏殤诗。"]', '诗', 'shi', '', NULL, '哭孟東野二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f2a986-5f8e-4e70-92a0-6d5838262dde', '寄蜀中薛濤校書', '寄蜀中薛濤校书', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["萬里橋邊女校書，枇杷花裏閉門居。","掃眉才子於今少，管領春風總不如。"]', '["万里橋邊女校书，枇杷花裏閉门居。","掃眉才子於今少，管領春风總不如。"]', '诗', 'shi', '', NULL, '寄蜀中薛濤校書 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0ecaa9a-f72e-4c01-bbaf-1420710e25d6', '路中上田尚書', '路中上田尚书', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["去路何詞見六親，手中刀尺不如人。","可憐池閣秋風夜，愁綠嬌紅一遍新。"]', '["去路何词见六親，手中刀尺不如人。","可怜池閣秋风夜，愁綠嬌紅一遍新。"]', '诗', 'shi', '', NULL, '路中上田尚書 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6acb536a-2868-40c5-b09f-64e84e290f8f', '于主簿廳看花', '于主簿廳看花', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["小葉稠枝粉壓摧，暖風吹動鶴翎開。","若無別事爲留滯，應便拋家宿看來。"]', '["小葉稠枝粉壓摧，暖风吹动鹤翎开。","若無別事爲留滯，應便拋家宿看来。"]', '诗', 'shi', '', NULL, '于主簿廳看花 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ac781c0-55ba-4854-bcb7-8ceda3849a53', '江樓對雨寄杜書記', '江楼对雨寄杜书記', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["竹煙花雨細相和，看著閑書睡更多。","好是主人無事日，應持小酒按新歌。"]', '["竹煙花雨細相和，看著闲书睡更多。","好是主人無事日，應持小酒按新歌。"]', '诗', 'shi', '', NULL, '江樓對雨寄杜書記 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76bfa201-6d01-40e7-8115-714ab1c10b9e', '觀蠻妓', '观蠻妓', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["欲說昭君歛翠蛾，清聲委曲怨于歌。","誰家年少春風裏，拋與金錢唱好多。"]', '["欲说昭君歛翠蛾，清声委曲怨于歌。","誰家年少春风裏，拋與金錢唱好多。"]', '诗', 'shi', '', NULL, '觀蠻妓 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e70707e-2204-4948-9632-492fb98e6a20', '送顧非熊秀才歸丹陽', '送顧非熊秀才归丹陽', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["江城柳色海門煙，欲到茅山始下船。","知道君家當瀑布，菖蒲潭在草堂前。"]', '["江城柳色海门煙，欲到茅山始下船。","知道君家當瀑布，菖蒲潭在草堂前。"]', '诗', 'shi', '', NULL, '送顧非熊秀才歸丹陽 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aabc8b89-aa9f-4b74-ae78-3d9f74be7133', '老人歌', '老人歌', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["白髮老人垂淚行，上皇生日出京城。","如今供奉多新意，錯唱當時一半聲。"]', '["白髮老人垂泪行，上皇生日出京城。","如今供奉多新意，錯唱當时一半声。"]', '诗', 'shi', '', NULL, '老人歌 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f22c077-c772-4f0c-90ea-8a3978a29dee', '和元郎中從八月十二至十五夜翫月五首 一', '和元郎中從八月十二至十五夜翫月五首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["半秋初入中旬夜，已向堦前守月明。","從未圓時看却好，一分分見傍輪生。"]', '["半秋初入中旬夜，已向堦前守月明。","從未圓时看却好，一分分见傍輪生。"]', '诗', 'shi', '', NULL, '和元郎中從八月十二至十五夜翫月五首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c237906-5af5-411e-9a0e-9174330d100b', '和元郎中從八月十二至十五夜翫月五首 二', '和元郎中從八月十二至十五夜翫月五首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["亂雲遮却臺東月，不許教依次第看。","莫爲詩家先見鏡，被他寵與作艱難。"]', '["亂云遮却台东月，不許教依次第看。","莫爲诗家先见镜，被他寵與作艱难。"]', '诗', 'shi', '', NULL, '和元郎中從八月十二至十五夜翫月五首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b6b249-3dce-46bf-9b4d-373b4cd34a35', '和元郎中從八月十二至十五夜翫月五首 三', '和元郎中從八月十二至十五夜翫月五首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["今夜月明勝昨夜，新添桂樹近東枝。","立多地濕舁牀坐，看過牆西寸寸遲。"]', '["今夜月明勝昨夜，新添桂樹近东枝。","立多地濕舁牀坐，看過牆西寸寸遲。"]', '诗', 'shi', '', NULL, '和元郎中從八月十二至十五夜翫月五首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f883ef7-297d-4b93-891a-24ab34badd79', '和元郎中從八月十二至十五夜翫月五首 四', '和元郎中從八月十二至十五夜翫月五首 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["月似圓來色漸凝，玉盆盛水欲侵稜。","夜深盡放家人睡，直到天明不炷燈。"]', '["月似圓来色漸凝，玉盆盛水欲侵稜。","夜深尽放家人睡，直到天明不炷灯。"]', '诗', 'shi', '', NULL, '和元郎中從八月十二至十五夜翫月五首 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59583a2e-fc8d-457d-9e3a-4f8c63e7da91', '和元郎中從八月十二至十五夜翫月五首 五', '和元郎中從八月十二至十五夜翫月五首 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["合望月時常望月，分明不得似今年。","仰頭五夜風中立，從未圓時直到圓。"]', '["合望月时常望月，分明不得似今年。","仰头五夜风中立，從未圓时直到圓。"]', '诗', 'shi', '', NULL, '和元郎中從八月十二至十五夜翫月五首 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b355c8fc-db00-4e76-8cab-3f9bf5d8a72f', '對酒', '对酒', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["爲病比來渾斷絕，緣花不免却知聞。","從來事事關身少，主領春風只在君。"]', '["爲病比来渾斷絕，緣花不免却知闻。","從来事事关身少，主領春风只在君。"]', '诗', 'shi', '', NULL, '對酒 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f4bc049-274b-493b-a481-2546ada10200', '曉望華清宮', '晓望华清宮', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["曉來樓閣更鮮明，日出闌干見鹿行。","武帝自知身不死，看修玉殿號長生。"]', '["晓来楼閣更鲜明，日出闌干见鹿行。","武帝自知身不死，看修玉殿號长生。"]', '诗', 'shi', '', NULL, '曉望華清宮 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531c8fdd-7e2d-457e-8e0d-b2e9333f5e81', '贈李愬僕射二首 一', '贈李愬僕射二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["和雪翻營一夜行，神旗凍定馬無聲。","遙看火號連營赤，知是先鋒已上城。"]', '["和雪翻營一夜行，神旗凍定马無声。","遙看火號連營赤，知是先鋒已上城。"]', '诗', 'shi', '', NULL, '贈李愬僕射二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cc728f-c062-449f-a8e3-f19f6361d0e2', '贈李愬僕射二首 二', '贈李愬僕射二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["旗幡四面下營稠，手詔頻來老將憂。","每日城南空挑戰，不知生縛入唐州。"]', '["旗幡四面下營稠，手詔頻来老將憂。","每日城南空挑戰，不知生縛入唐州。"]', '诗', 'shi', '', NULL, '贈李愬僕射二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('538b37af-a94b-4881-9008-171a22b3a679', '秋夜對雨寄石甕寺二秀才', '秋夜对雨寄石甕寺二秀才', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["夜山秋雨滴空廊，燈照堂前樹葉光。","對坐讀書終卷後，自披衣被掃僧房。"]', '["夜山秋雨滴空廊，灯照堂前樹葉光。","对坐读书終卷後，自披衣被掃僧房。"]', '诗', 'shi', '', NULL, '秋夜對雨寄石甕寺二秀才 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12fe62b3-64cb-41db-8b46-9b2b61d2f250', '華清宮前柳', '华清宮前柳', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["楊柳宮前忽地春，在先驚動探春人。","曉來唯欠驪山雨，洗却枝頭綠上塵。"]', '["楊柳宮前忽地春，在先驚动探春人。","晓来唯欠驪山雨，洗却枝头綠上塵。"]', '诗', 'shi', '', NULL, '華清宮前柳 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00677727-a9af-4f71-8828-26c450dbe87b', '別楊校書', '別楊校书', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["從軍秣馬十三年，白髮營中聽早蟬。","故作老丞身不避，縣名昭應管山泉。"]', '["從軍秣马十三年，白髮營中听早蟬。","故作老丞身不避，縣名昭應管山泉。"]', '诗', 'shi', '', NULL, '別楊校書 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b22b61-6cda-485b-a863-51e433f16daa', '和門下武相公春曉聞鶯', '和门下武相公春晓闻鶯', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["侵黑行飛一兩聲，春寒囀小未分明。","若教更解諸餘語，應向宮花不惜情。"]', '["侵黑行飞一兩声，春寒囀小未分明。","若教更解諸餘語，應向宮花不惜情。"]', '诗', 'shi', '', NULL, '和門下武相公春曉聞鶯 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9789e09-3b2a-44e8-b262-c7ab66992c6e', '田侍郎歸鎮 一', '田侍郎归鎮 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["去處長將決勝籌，回回身在陣前頭。","賊城破後先鋒入，看著紅妝不敢收。"]', '["去处长將決勝籌，回回身在陣前头。","賊城破後先鋒入，看著紅妝不敢收。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d49656e0-2313-441d-a3b1-11349454f56f', '田侍郎歸鎮 二', '田侍郎归鎮 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["熨帖朝衣拋戰袍，夔龍班裏侍中高。","對時先奏牙間將，次第天恩與節旄。"]', '["熨帖朝衣拋戰袍，夔龙班裏侍中高。","对时先奏牙间將，次第天恩與節旄。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e22d372-6a01-4578-ab93-2ee7182f71b2', '田侍郎歸鎮 三', '田侍郎归鎮 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["踏著家鄉馬腳輕，暮山秋色眼前明。","老人上酒齊頭拜，得侍中來盡再生。"]', '["踏著家乡马腳轻，暮山秋色眼前明。","老人上酒齊头拜，得侍中来尽再生。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e79e1752-434f-414a-a722-65a02714a3ef', '田侍郎歸鎮 四', '田侍郎归鎮 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["功成誰不擁藩方，富貴還須是本鄉。","萬里雙旌汾水上，玉鞭遙指白雲莊。"]', '["功成誰不擁藩方，富貴還須是本乡。","万里雙旌汾水上，玉鞭遙指白云莊。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5714a972-d577-4402-a1d4-e62d53d79acf', '田侍郎歸鎮 五', '田侍郎归鎮 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鼓吹旛旗道兩邊，行男走女喜駢闐。","舊交省得當時別，指點如今却少年。"]', '["鼓吹旛旗道兩邊，行男走女喜駢闐。","旧交省得當时別，指点如今却少年。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d17ebc8b-4230-4123-a14e-dfabf626e1f3', '田侍郎歸鎮 六', '田侍郎归鎮 六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["廣場破陣樂初休，彩纛高于百尺樓。","老將氣雄爭起舞，管弦回作大纏頭。"]', '["廣場破陣乐初休，彩纛高于百尺楼。","老將氣雄爭起舞，管弦回作大纏头。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da159cc5-ae80-4fb9-99d4-ed49aa8b3d0b', '田侍郎歸鎮 七', '田侍郎归鎮 七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["笳聲萬里動燕山，草白天清塞馬閑。","觸處不如別處樂，可憐秋月照江關。"]', '["笳声万里动燕山，草白天清塞马闲。","觸处不如別处乐，可怜秋月照江关。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06124ae1-83c0-48ea-a0ae-c8cd7c2181f1', '田侍郎歸鎮 八', '田侍郎归鎮 八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["將士請衣忘却貧，綠窗紅燭酒樓新。","家家盡踏還鄉曲，明月街中不絕人。"]', '["將士請衣忘却貧，綠窗紅燭酒楼新。","家家尽踏還乡曲，明月街中不絕人。"]', '诗', 'shi', '', NULL, '田侍郎歸鎮 八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('193c8e13-19a9-49c0-8553-406704c1422b', '寄廣文張博士', '寄廣文張博士', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春明門外作卑官，病友經年不得看。","莫道長安近于日，昇天却易到城難。"]', '["春明门外作卑官，病友經年不得看。","莫道长安近于日，昇天却易到城难。"]', '诗', 'shi', '', NULL, '寄廣文張博士 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2adaaab8-0538-477d-babe-254b4cc9205f', '早春書情', '早春书情', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["漸老風光不著人，花溪柳陌早逢春。","近來行到門前少，趁暖閑眠似病人。"]', '["漸老风光不著人，花溪柳陌早逢春。","近来行到门前少，趁暖闲眠似病人。"]', '诗', 'shi', '', NULL, '早春書情 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39a6efc-8e25-46d6-bcc9-d0c3cc5a9796', '唐昌觀玉蕋花', '唐昌观玉蕋花', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一樹籠𩮀玉刻成，飄廊點地色輕輕。","女冠夜覓香來處，唯見階前碎月明。"]', '["一樹籠𩮀玉刻成，飄廊点地色轻轻。","女冠夜覓香来处，唯见階前碎月明。"]', '诗', 'shi', '', NULL, '唐昌觀玉蕋花 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dce8e95c-03c0-45f5-89a3-d0a1ac788ac2', '眼病寄同官', '眼病寄同官', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天寒眼痛少心情，隔霧看人夜裏行。","年少往來常不住，牆西凍地馬蹄聲。"]', '["天寒眼痛少心情，隔霧看人夜裏行。","年少往来常不住，牆西凍地马蹄声。"]', '诗', 'shi', '', NULL, '眼病寄同官 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0308766c-4823-4c11-b046-648c66694b8b', '九日登叢臺', '九日登叢台', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["平原池閣在誰家，雙塔叢臺野菊花。","零落故宮無入路，西來澗水繞城斜。"]', '["平原池閣在誰家，雙塔叢台野菊花。","零落故宮無入路，西来澗水繞城斜。"]', '诗', 'shi', '', NULL, '九日登叢臺 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e88c0a93-25d4-483b-9458-cbbd01ae2fff', '題酸棗縣蔡中郎碑', '題酸棗縣蔡中郎碑', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["蒼苔滿字土埋龜，風雨銷磨絕妙詞。","不向圖經中舊見，無人知是蔡邕碑。"]', '["蒼苔满字土埋龟，风雨銷磨絕妙词。","不向圖經中旧见，無人知是蔡邕碑。"]', '诗', 'shi', '', NULL, '題酸棗縣蔡中郎碑 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7556d5b5-6c70-4d7d-9035-82324f377648', '江陵使至汝州', '江陵使至汝州', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["回看巴路在雲間，寒食離家麥熟還。","日暮數峰青似染，商人說是汝州山。"]', '["回看巴路在云间，寒食離家麦熟還。","日暮數峰青似染，商人说是汝州山。"]', '诗', 'shi', '', NULL, '江陵使至汝州 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6c16de-1d7e-4564-979b-e93e42ab176b', '十五夜望月寄杜郎中', '十五夜望月寄杜郎中', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["中庭地白樹棲鴉，冷露無聲濕桂花。","今夜月明人盡望，不知秋思在誰家。"]', '["中庭地白樹棲鴉，冷露無声濕桂花。","今夜月明人尽望，不知秋思在誰家。"]', '诗', 'shi', '', NULL, '十五夜望月寄杜郎中 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c43af341-9b07-472d-b881-402d053bb96c', '寄同州田長史', '寄同州田长史', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["除聽好語耳常聾，不見詩人眼底空。","莫怪出城爲長史，總緣山在白雲中。"]', '["除听好語耳常聾，不见诗人眼底空。","莫怪出城爲长史，總緣山在白云中。"]', '诗', 'shi', '', NULL, '寄同州田長史 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f49e0e-117f-43ed-a1be-176bf07fa24d', '外按', '外按', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["夾城門向野田開，白鹿非時出洞來。","日暮秦陵塵土起，從東外按使初回。"]', '["夾城门向野田开，白鹿非时出洞来。","日暮秦陵塵土起，從东外按使初回。"]', '诗', 'shi', '', NULL, '外按 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82ac4bb-b67d-4e05-a73d-f2f4552e311f', '宮詞一百首 一', '宮词一百首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["蓬萊正殿壓金鼇，紅日初生碧海濤。","閑著五門遙北望，柘黃新帕御牀高。"]', '["蓬萊正殿壓金鼇，紅日初生碧海濤。","闲著五门遙北望，柘黄新帕御牀高。"]', '诗', 'shi', '', NULL, '宮詞一百首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6676981-e083-47f3-af47-cf93762c9f10', '宮詞一百首 二', '宮词一百首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["殿前傳點各依班，召對西來八詔蠻。","上得青花龍尾道，側身偷覷正南山。"]', '["殿前傳点各依班，召对西来八詔蠻。","上得青花龙尾道，側身偷覷正南山。"]', '诗', 'shi', '', NULL, '宮詞一百首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5883d5de-6c74-425b-a502-d04eb49aef7c', '宮詞一百首 三', '宮词一百首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["龍煙日暖紫曈曈，宣政門當玉殿風。","五刻閣前卿相出，下簾聲在半天中。"]', '["龙煙日暖紫曈曈，宣政门當玉殿风。","五刻閣前卿相出，下簾声在半天中。"]', '诗', 'shi', '', NULL, '宮詞一百首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('185a5cd7-628e-46a1-85bc-05c7a57ffc59', '宮詞一百首 四', '宮词一百首 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["白玉窗前起草臣，櫻桃初赤賜嘗新。","殿頭傳語金階遠，只進詞來謝聖人。"]', '["白玉窗前起草臣，櫻桃初赤賜嘗新。","殿头傳語金階远，只進词来謝聖人。"]', '诗', 'shi', '', NULL, '宮詞一百首 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e17937-790f-42fa-9add-95c27eb16022', '宮詞一百首 五', '宮词一百首 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["內人對御疊花牋，繡坐移來玉案邊。","紅蠟燭前呈草本，平明舁出閣門宣。"]', '["內人对御叠花牋，繡坐移来玉案邊。","紅蠟燭前呈草本，平明舁出閣门宣。"]', '诗', 'shi', '', NULL, '宮詞一百首 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daaf31ca-9e62-41ed-acba-073c77b4d1b0', '宮詞一百首 六', '宮词一百首 六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["千牛仗下放朝初，玉案傍邊立起居。","每日進來金鳳紙，殿頭無事不多書。"]', '["千牛仗下放朝初，玉案傍邊立起居。","每日進来金鳳紙，殿头無事不多书。"]', '诗', 'shi', '', NULL, '宮詞一百首 六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40becd46-16d8-4e81-ae3d-53490c5a9f13', '宮詞一百首 七', '宮词一百首 七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["延英引對碧衣郎，江硯宣毫各別牀。","天子下簾親考試，宮人手裏過茶湯。"]', '["延英引对碧衣郎，江硯宣毫各別牀。","天子下簾親考試，宮人手裏過茶湯。"]', '诗', 'shi', '', NULL, '宮詞一百首 七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('575c38b9-7a1a-496f-97f5-d80c1f81a2a8', '宮詞一百首 八', '宮词一百首 八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["未明開著九重關，金畫黃龍五色幡。","直到銀臺排仗合，聖人三殿對西番。"]', '["未明开著九重关，金畫黄龙五色幡。","直到銀台排仗合，聖人三殿对西番。"]', '诗', 'shi', '', NULL, '宮詞一百首 八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f249f1-6d83-4ef8-9532-6732787cab97', '宮詞一百首 九', '宮词一百首 九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["少年天子重邊功，親到凌煙畫閣中。","敎覓勳臣寫圖本，長將殿裏作屏風。"]', '["少年天子重邊功，親到凌煙畫閣中。","敎覓勳臣寫圖本，长將殿裏作屏风。"]', '诗', 'shi', '', NULL, '宮詞一百首 九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f36053b-32df-4500-96cf-05cba02c9af7', '宮詞一百首 十', '宮词一百首 十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["丹鳳樓門把火開，五雲金輅下天來。","堦前走馬人宣慰，天子南郊一宿回。"]', '["丹鳳楼门把火开，五云金輅下天来。","堦前走马人宣慰，天子南郊一宿回。"]', '诗', 'shi', '', NULL, '宮詞一百首 十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5966e3f4-fc7f-489b-b30c-9302e85f5b44', '宮詞一百首 十一', '宮词一百首 十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["樓前立仗看宣赦，萬歲聲長拜舞齊。","日照彩盤高百尺，飛仙爭上取金雞。"]', '["楼前立仗看宣赦，万歲声长拜舞齊。","日照彩盤高百尺，飞仙爭上取金雞。"]', '诗', 'shi', '', NULL, '宮詞一百首 十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9719be-9cdd-44cb-9e89-b0864f12c156', '宮詞一百首 十二', '宮词一百首 十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["集賢殿裏圖書滿，點勘頭邊御印同。","真跡進來依數字，別收鎖在玉函中。"]', '["集賢殿裏圖书满，点勘头邊御印同。","真跡進来依數字，別收鎖在玉函中。"]', '诗', 'shi', '', NULL, '宮詞一百首 十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1f971a3-2727-4d24-8065-671b4856eee6', '宮詞一百首 十三', '宮词一百首 十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["秘殿清齋刻漏長，紫微宮女夜焚香。","拜陵日近公卿發，鹵簿分頭入太常。"]', '["秘殿清斋刻漏长，紫微宮女夜焚香。","拜陵日近公卿發，鹵簿分头入太常。"]', '诗', 'shi', '', NULL, '宮詞一百首 十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804c1475-eff8-46c9-a573-b521caf7a705', '宮詞一百首 十四', '宮词一百首 十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新調白馬怕鞭聲，供奉騎來遶殿行。","爲報諸王侵早入，隔門催進打毬名。"]', '["新調白马怕鞭声，供奉騎来遶殿行。","爲報諸王侵早入，隔门催進打毬名。"]', '诗', 'shi', '', NULL, '宮詞一百首 十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98caea4-58b0-4a60-a763-25acc8817f5d', '宮詞一百首 十五', '宮词一百首 十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["對御難爭第一籌，殿前不打背身毬。","內人唱好龜茲急，天子鞘回過玉樓。"]', '["对御难爭第一籌，殿前不打背身毬。","內人唱好龟茲急，天子鞘回過玉楼。"]', '诗', 'shi', '', NULL, '宮詞一百首 十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb6142d3-2b35-4adc-8ee1-d8ac5bec4791', '宮詞一百首 十六', '宮词一百首 十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新衫一樣殿頭黃，銀帶排方獺尾長。","總把玉鞭騎御馬，綠鬃紅額麝香香。"]', '["新衫一樣殿头黄，銀带排方獺尾长。","總把玉鞭騎御马，綠鬃紅額麝香香。"]', '诗', 'shi', '', NULL, '宮詞一百首 十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a669e152-741f-4f74-a409-6aecd7df08ba', '宮詞一百首 十七', '宮词一百首 十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["羅衫葉葉繡重重，金鳳銀鵝各一叢。","每遍舞時分兩向，太平萬歲字當中。"]', '["羅衫葉葉繡重重，金鳳銀鵝各一叢。","每遍舞时分兩向，太平万歲字當中。"]', '诗', 'shi', '', NULL, '宮詞一百首 十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c49ce104-96c3-4dce-91b8-ec868d2791ba', '宮詞一百首 十八', '宮词一百首 十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["魚藻宮中鎖翠娥，先皇行處不曾過。","如今池底休鋪錦，菱角雞頭積漸多。"]', '["鱼藻宮中鎖翠娥，先皇行处不曾過。","如今池底休鋪錦，菱角雞头積漸多。"]', '诗', 'shi', '', NULL, '宮詞一百首 十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc641fa-46c8-4ab7-8e66-46060bde0182', '宮詞一百首 十九', '宮词一百首 十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["殿前明日中和節，連夜瓊林散舞衣。","傳報所司分蠟燭，監開金鎖放人歸。"]', '["殿前明日中和節，連夜瓊林散舞衣。","傳報所司分蠟燭，監开金鎖放人归。"]', '诗', 'shi', '', NULL, '宮詞一百首 十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be108111-f9e5-426c-8df8-4f50002b9cb3', '宮詞一百首 二十', '宮词一百首 二十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["五更三點索金車，盡放宮人出看花。","仗下一時催立馬，殿頭先報內園家。"]', '["五更三点索金车，尽放宮人出看花。","仗下一时催立马，殿头先報內园家。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da681c98-2b0e-4be8-b5df-229b200d36f2', '宮詞一百首 二十一', '宮词一百首 二十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["城東北面望雲樓，半下珠簾半上鉤。","騎馬行人長遠過，恐防天子在樓頭。"]', '["城东北面望云楼，半下珠簾半上鉤。","騎马行人长远過，恐防天子在楼头。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98e698b4-0ee7-42ee-9f1e-1d2c1b1aedaa', '宮詞一百首 二十二', '宮词一百首 二十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["射生宮女宿紅妝，把得新弓各自張。","臨上馬時齊賜酒，男兒跪拜謝君王。"]', '["射生宮女宿紅妝，把得新弓各自張。","臨上马时齊賜酒，男兒跪拜謝君王。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d14d7bdb-4332-431b-8b6f-0e279e4590d6', '宮詞一百首 二十三', '宮词一百首 二十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新秋白兔大於拳，紅耳霜毛趁草眠。","天子不敎人射殺，玉鞭遮到馬蹄前。"]', '["新秋白兔大於拳，紅耳霜毛趁草眠。","天子不敎人射殺，玉鞭遮到马蹄前。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd778d7-4c03-4b0a-ad03-2cdbda05bdb7', '宮詞一百首 二十四', '宮词一百首 二十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["內鷹籠脫解紅絛，鬬勝爭飛出手高。","直上碧雲還却下，一雙金爪掬花毛。"]', '["內鷹籠脫解紅絛，鬬勝爭飞出手高。","直上碧云還却下，一雙金爪掬花毛。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7af7e64-c793-4922-9a14-2c5332d38155', '宮詞一百首 二十五', '宮词一百首 二十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["競渡船頭掉采旗，兩邊濺水濕羅衣。","池東爭向池西岸，先到先書上字歸。"]', '["競渡船头掉采旗，兩邊濺水濕羅衣。","池东爭向池西岸，先到先书上字归。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8a3502c-61a9-42c5-aaf8-d65ec3bac7f1', '宮詞一百首 二十六', '宮词一百首 二十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["燈前飛入玉堦蟲，未臥常聞半夜鐘。","看著中元齋日到，自盤金線繡真容。"]', '["灯前飞入玉堦蟲，未臥常闻半夜鐘。","看著中元斋日到，自盤金線繡真容。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b77e5b0-ff3a-4d8e-9584-ccd08e2bbc21', '宮詞一百首 二十七', '宮词一百首 二十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["紅燈睡裏喚春雲，雲上三更直宿分。","金砌雨來行步滑，兩人擡起隱花裙。"]', '["紅灯睡裏喚春云，云上三更直宿分。","金砌雨来行步滑，兩人擡起隐花裙。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68307771-cbce-4ead-b5b6-76d68add6b2f', '宮詞一百首 二十八', '宮词一百首 二十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["一時起立吹簫管，得寵人來滿殿迎。","整頓衣裳皆著却，舞頭當拍第三聲。"]', '["一时起立吹簫管，得寵人来满殿迎。","整頓衣裳皆著却，舞头當拍第三声。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90c97ed-54c9-4bca-a005-db41a1a17621', '宮詞一百首 二十九', '宮词一百首 二十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["琵琶先抹六么頭，小管丁寧側調愁。","半夜美人雙唱起，一聲聲出鳳皇樓。"]', '["琵琶先抹六么头，小管丁寧側調愁。","半夜美人雙唱起，一声声出鳳皇楼。"]', '诗', 'shi', '', NULL, '宮詞一百首 二十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bffb44d1-d617-4ee6-b7f7-1c933cf926b3', '宮詞一百首 三十', '宮词一百首 三十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春池日暖少風波，花裏牽船水上歌。","遙索劒南新樣錦，東宮先釣得魚多。"]', '["春池日暖少风波，花裏牽船水上歌。","遙索劒南新樣錦，东宮先釣得鱼多。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69755171-e021-4c51-a24c-19dfcb9a2db5', '宮詞一百首 三十一', '宮词一百首 三十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["十三初學擘箜篌，弟子名中被點留。","昨日敎坊新進入，並房宮女與梳頭。"]', '["十三初学擘箜篌，弟子名中被点留。","昨日敎坊新進入，並房宮女與梳头。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870092a2-f622-4aa2-b7ed-1b5af46f8022', '宮詞一百首 三十二', '宮词一百首 三十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["紅蠻桿撥貼胸前，移坐當頭近御筵。","用力獨彈金殿響，鳳皇飛下四條弦。"]', '["紅蠻桿撥貼胸前，移坐當头近御筵。","用力独彈金殿响，鳳皇飞下四條弦。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2256ca-c75e-43eb-9976-eaf941fb8047', '宮詞一百首 三十三', '宮词一百首 三十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春風吹雨灑旗竿，得出深宮不怕寒。","誇道自家能走馬，團中橫過覓人看。"]', '["春风吹雨灑旗竿，得出深宮不怕寒。","誇道自家能走马，團中橫過覓人看。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa69b9f-998a-4ed4-ad71-95b7dd2283e9', '宮詞一百首 三十四', '宮词一百首 三十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["粟金腰帶象牙錐，散插紅翎玉突枝。","旋獵一邊還引馬，歸來雞兔遶鞍垂。"]', '["粟金腰带象牙錐，散插紅翎玉突枝。","旋獵一邊還引马，归来雞兔遶鞍垂。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf383ed-97f3-46ae-ba95-893b472418d4', '宮詞一百首 三十五', '宮词一百首 三十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雲駮花驄各試行，一般毛色一般纓。","殿前來往重騎過，欲得君王別賜名。"]', '["云駮花驄各試行，一般毛色一般纓。","殿前来往重騎過，欲得君王別賜名。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca62aad4-239a-4aeb-9ebf-9fce78039341', '宮詞一百首 三十六', '宮词一百首 三十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["每夜停燈熨御衣，銀熏籠底火霏霏。","遙聽帳裏君王覺，上直鐘聲始得歸。"]', '["每夜停灯熨御衣，銀熏籠底火霏霏。","遙听帳裏君王覺，上直鐘声始得归。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4dfae1-881c-482b-8cdb-132788f7ed49', '宮詞一百首 三十七', '宮词一百首 三十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["因喫櫻桃病放歸，三年著破舊羅衣。","內中人識從來去，結得金花上貴妃。"]', '["因喫櫻桃病放归，三年著破旧羅衣。","內中人識從来去，結得金花上貴妃。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2446ee37-2fcd-4f49-b009-054005db401f', '宮詞一百首 三十八', '宮词一百首 三十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["欲迎天子看花去，下得金堦却悔行。","恐見失恩人舊院，回來憶著五弦聲。"]', '["欲迎天子看花去，下得金堦却悔行。","恐见失恩人旧院，回来憶著五弦声。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c9016d-b52b-47ff-8f57-885bb4499cf4', '宮詞一百首 三十九', '宮词一百首 三十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["往來舊院不堪修，近勑宣徽別起樓。","聞有美人新進入，六宮未見一時愁。"]', '["往来旧院不堪修，近勑宣徽別起楼。","闻有美人新進入，六宮未见一时愁。"]', '诗', 'shi', '', NULL, '宮詞一百首 三十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('befc933c-08ad-46df-baf6-19e7d5814819', '宮詞一百首 四十', '宮词一百首 四十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自誇歌舞勝諸人，恨未承恩出內頻。","連夜宮中修別院，地衣簾額一時新。"]', '["自誇歌舞勝諸人，恨未承恩出內頻。","連夜宮中修別院，地衣簾額一时新。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab2d9af0-bb42-4590-a611-cab2126a9ace', '宮詞一百首 四十一', '宮词一百首 四十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["悶來無處可思量，旋下金堦旋憶牀。","收得山丹紅蘂粉，鏡前洗却麝香黃。"]', '["悶来無处可思量，旋下金堦旋憶牀。","收得山丹紅蘂粉，镜前洗却麝香黄。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecf85314-585f-4020-bae3-d1c45e3ac734', '宮詞一百首 四十二', '宮词一百首 四十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["蜂鬚蟬翅薄鬆鬆，浮動搔頭似有風。","一度出時拋一遍，金條零落滿函中。"]', '["蜂鬚蟬翅薄鬆鬆，浮动搔头似有风。","一度出时拋一遍，金條零落满函中。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce6206d9-ad39-49b3-adbe-6143e9b05f92', '宮詞一百首 四十三', '宮词一百首 四十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["合暗報來門鎖了，夜深應別喚笙歌。","房房下著珠簾睡，月過金堦白露多。"]', '["合暗報来门鎖了，夜深應別喚笙歌。","房房下著珠簾睡，月過金堦白露多。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2155eb24-b4f4-47c4-912d-b04ff59fa363', '宮詞一百首 四十四', '宮词一百首 四十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["御廚不食索時新，每見花開即苦春。","白日臥多嬌似病，隔簾敎喚女醫人。"]', '["御廚不食索时新，每见花开即苦春。","白日臥多嬌似病，隔簾敎喚女醫人。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7129b044-cdab-40fd-84b2-0ce5fc4685eb', '宮詞一百首 四十五', '宮词一百首 四十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["叢叢洗手遶金盆，旋拭紅巾入殿門。","衆裏遙拋新摘子，在前收得便承恩。"]', '["叢叢洗手遶金盆，旋拭紅巾入殿门。","衆裏遙拋新摘子，在前收得便承恩。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27558e1c-02d9-4c38-b18a-d9737612820e', '宮詞一百首 四十六', '宮词一百首 四十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["御池水色春來好，處處分流白玉渠。","密奏君王知入月，喚人相伴洗裙裾。"]', '["御池水色春来好，处处分流白玉渠。","密奏君王知入月，喚人相伴洗裙裾。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7921717-ef0f-4523-a23d-5626b50785ed', '宮詞一百首 四十七', '宮词一百首 四十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["移來女樂部頭邊，新賜花檀木五弦。","緶得紅羅手帕子，中心細畫一雙蟬。"]', '["移来女乐部头邊，新賜花檀木五弦。","緶得紅羅手帕子，中心細畫一雙蟬。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5584e895-f24e-4c04-aff3-1a731c4b3b9f', '宮詞一百首 四十八', '宮词一百首 四十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["新晴草色綠溫暾，山雪初消漸出渾。","今日踏青歸校晚，傳聲留著望春門。"]', '["新晴草色綠溫暾，山雪初消漸出渾。","今日踏青归校晚，傳声留著望春门。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00d5fc5c-1887-4c3c-ad5f-bbee4c2efe09', '宮詞一百首 四十九', '宮词一百首 四十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["兩樓相換珠簾額，中尉明朝設內家。","一樣金盤五千面，紅酥點出牡丹花。"]', '["兩楼相換珠簾額，中尉明朝設內家。","一樣金盤五千面，紅酥点出牡丹花。"]', '诗', 'shi', '', NULL, '宮詞一百首 四十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('955a3048-33b6-4e12-98e4-9cf603dc1bc8', '宮詞一百首 五十', '宮词一百首 五十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["盡送春來出內家，記巡傳把一枝花。","散時各自燒紅燭，相逐行歸不上車。"]', '["尽送春来出內家，記巡傳把一枝花。","散时各自燒紅燭，相逐行归不上车。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb2927d-99c2-433f-979a-41b714494542', '宮詞一百首 五十一', '宮词一百首 五十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["家常愛著舊衣裳，空插紅梳不出妝。","忽地下堦裙帶解，非時應得見君王。"]', '["家常愛著旧衣裳，空插紅梳不出妝。","忽地下堦裙带解，非时應得见君王。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7708d535-845d-461e-bf74-659c639f95ec', '宮詞一百首 五十二', '宮词一百首 五十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["別勑敎歌不出房，一聲一遍奏君王。","再三博士留殘拍，索向宣徽作徹章。"]', '["別勑敎歌不出房，一声一遍奏君王。","再三博士留殘拍，索向宣徽作徹章。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314760fc-d2de-4a95-bd4e-21d1031859f1', '宮詞一百首 五十三', '宮词一百首 五十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["行中第一爭先舞，博士傍邊亦被欺。","忽覺管弦偷破拍，急翻羅袖不敎知。"]', '["行中第一爭先舞，博士傍邊亦被欺。","忽覺管弦偷破拍，急翻羅袖不敎知。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17feaadd-bca9-4f1d-892f-21f655da7e73', '宮詞一百首 五十四', '宮词一百首 五十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["私縫黃帔捨釵梳，欲得金仙觀裏居。","近被君王知識字，收來案上檢文書。"]', '["私縫黄帔捨釵梳，欲得金仙观裏居。","近被君王知識字，收来案上檢文书。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712f1f4a-4c65-4ece-b241-d05bc21a331b', '宮詞一百首 五十五', '宮词一百首 五十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["月冷江清近獵時，玉階金瓦雪澌澌。","浴堂門外抄名入，公主家人謝面脂。"]', '["月冷江清近獵时，玉階金瓦雪澌澌。","浴堂门外抄名入，公主家人謝面脂。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0a4677-a671-4e55-864f-e3bb48b578f8', '宮詞一百首 五十六', '宮词一百首 五十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["未承恩澤一家愁，乍到宮中憶外頭。","求守管弦聲款逐，側商調裏唱伊州。"]', '["未承恩澤一家愁，乍到宮中憶外头。","求守管弦声款逐，側商調裏唱伊州。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c266ae05-1dce-4290-ad80-24845bf71191', '宮詞一百首 五十七', '宮词一百首 五十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["東風潑火雨新休，舁盡春泥掃雪溝。","走馬犢車當御路，漢陽宮主進雞毬。"]', '["东风潑火雨新休，舁尽春泥掃雪溝。","走马犢车當御路，漢陽宮主進雞毬。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8125f7-cc2c-43dc-82e6-3d74dcb898c2', '宮詞一百首 五十八', '宮词一百首 五十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["風簾水閣壓芙蓉，四面鉤欄在水中。","避熱不歸金殿宿，秋河織女夜妝紅。"]', '["风簾水閣壓芙蓉，四面鉤欄在水中。","避熱不归金殿宿，秋河织女夜妝紅。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3618eeb6-1295-4013-aafe-a378040c5a5c', '宮詞一百首 五十九', '宮词一百首 五十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["聖人生日明朝是，私地敎人屬內監。","自寫金花紅牓子，前頭先進鳳皇衫。"]', '["聖人生日明朝是，私地敎人屬內監。","自寫金花紅牓子，前头先進鳳皇衫。"]', '诗', 'shi', '', NULL, '宮詞一百首 五十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b629bd15-915f-4a89-8e86-b6f9fc75431f', '宮詞一百首 六十', '宮词一百首 六十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["避暑昭陽不擲盧，井邊含水噴鵶雛。","內中數日無呼喚，搨得滕王蛺蝶圖。"]', '["避暑昭陽不擲盧，井邊含水噴鵶雛。","內中數日無呼喚，搨得滕王蛺蝶圖。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d23f29d-61dd-4adc-ad22-965e215447b7', '宮詞一百首 六十一', '宮词一百首 六十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["內宴初秋入二更，殿前燈火一天明。","中宮傳旨音聲散，諸院門開觸處行。"]', '["內宴初秋入二更，殿前灯火一天明。","中宮傳旨音声散，諸院门开觸处行。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b409641-e710-4501-9362-b131a9e59efb', '宮詞一百首 六十二', '宮词一百首 六十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["玉蟬金雀三層插，翠髻高叢綠鬢虛。","舞處春風吹落地，歸來別賜一頭梳。"]', '["玉蟬金雀三層插，翠髻高叢綠鬢虛。","舞处春风吹落地，归来別賜一头梳。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af4cd8d-92a4-44f4-9280-cc649e58c05b', '宮詞一百首 六十三', '宮词一百首 六十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["樹葉初成鳥護窠，石榴花裏笑聲多。","衆中遺却金釵子，拾得從他要贖麽。"]', '["樹葉初成鸟護窠，石榴花裏笑声多。","衆中遺却金釵子，拾得從他要贖麽。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e9933a-e69f-47da-9cb8-52d05e4e6cd6', '宮詞一百首 六十四', '宮词一百首 六十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["小殿初成粉未乾，貴妃姊妹自來看。","爲逢好日先移入，續向街西索牡丹。"]', '["小殿初成粉未乾，貴妃姊妹自来看。","爲逢好日先移入，續向街西索牡丹。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3beea2-2fc3-4b58-97a9-c1c3d7c891d4', '宮詞一百首 六十五', '宮词一百首 六十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["內人相續報花開，准擬君王便看來。","逢着五弦琴繡袋，宜春院裏按歌回。"]', '["內人相續報花开，准擬君王便看来。","逢着五弦琴繡袋，宜春院裏按歌回。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c08384-40a8-404c-b177-0eb871349ae1', '宮詞一百首 六十六', '宮词一百首 六十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["巡吹慢遍不相和，暗數看誰曲校多。","明日棃花園裏見，先須逐得內家歌。"]', '["巡吹慢遍不相和，暗數看誰曲校多。","明日棃花园裏见，先須逐得內家歌。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a87df7c5-a016-48e2-bea8-e8245d30d3a7', '宮詞一百首 六十七', '宮词一百首 六十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["黃金合裏盛紅雪，重結香羅四出花。","一一傍邊書勑字，中官送與大臣家。"]', '["黄金合裏盛紅雪，重結香羅四出花。","一一傍邊书勑字，中官送與大臣家。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2013c2a-cdf9-4622-81c1-c4a78779392d', '宮詞一百首 六十八', '宮词一百首 六十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["未明東上閣門開，排仗聲從後殿來。","阿監兩邊相對立，遙聞索馬一時回。"]', '["未明东上閣门开，排仗声從後殿来。","阿監兩邊相对立，遙闻索马一时回。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7dc6fee-bc60-4413-b70e-f61285e4bc77', '宮詞一百首 六十九', '宮词一百首 六十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宮人早起笑相呼，不識堦前掃地夫。","乞與金錢爭借問，外頭還似此間無。"]', '["宮人早起笑相呼，不識堦前掃地夫。","乞與金錢爭借问，外头還似此间無。"]', '诗', 'shi', '', NULL, '宮詞一百首 六十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40823f2e-270e-453d-bd29-927dd6ab2cbd', '宮詞一百首 七十', '宮词一百首 七十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["小隨阿姊學吹笙，見好君王賜與名。","夜拂玉牀朝把鏡，黃金殿外不敎行。"]', '["小隨阿姊学吹笙，见好君王賜與名。","夜拂玉牀朝把镜，黄金殿外不敎行。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('334086ee-25b3-4495-94b7-b3fb778df9b8', '宮詞一百首 七十一', '宮词一百首 七十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["日高殿裏有香煙，萬歲聲長動九天。","妃子院中初降誕，內人爭乞洗兒錢。"]', '["日高殿裏有香煙，万歲声长动九天。","妃子院中初降誕，內人爭乞洗兒錢。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a07cb67-6cbb-46aa-960d-917d7dadf304', '宮詞一百首 七十二', '宮词一百首 七十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宮花不共外花同，正月長生一半紅。","供御櫻桃看守別，直無鴉鵲到園中。"]', '["宮花不共外花同，正月长生一半紅。","供御櫻桃看守別，直無鴉鵲到园中。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fd04c5-458a-4ba0-80d6-7787739a2627', '宮詞一百首 七十三', '宮词一百首 七十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["殿前鋪設兩邊樓，寒食宮人步打毬。","一半走來爭跪拜，上棚先謝得頭籌。"]', '["殿前鋪設兩邊楼，寒食宮人步打毬。","一半走来爭跪拜，上棚先謝得头籌。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1295bb1f-bfdf-476b-bde2-40a67a6a4eff', '宮詞一百首 七十四', '宮词一百首 七十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["太儀前日暖房來，囑向朝陽乞藥栽。","勑賜一窠紅躑躅，謝恩未了奏花開。"]', '["太儀前日暖房来，囑向朝陽乞藥栽。","勑賜一窠紅躑躅，謝恩未了奏花开。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e3d796-d787-498f-8163-4f775b872f51', '宮詞一百首 七十五', '宮词一百首 七十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["御前新賜紫羅襦，步步金堦上軟輿。","宮局總來爲喜樂，院中新拜內尚書。"]', '["御前新賜紫羅襦，步步金堦上軟輿。","宮局總来爲喜乐，院中新拜內尚书。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9024705b-f9c1-4c1a-a28f-90ebd42b3811', '宮詞一百首 七十六', '宮词一百首 七十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鸚鵡誰敎轉舌關，內人手裏養來姦。","語多更覺承恩澤，數對君王憶隴山。"]', '["鸚鵡誰敎轉舌关，內人手裏養来姦。","語多更覺承恩澤，數对君王憶隴山。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fa2d6f-76e8-4ad8-9b15-f1771a7241e6', '宮詞一百首 七十七', '宮词一百首 七十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["分朋閑坐賭櫻桃，收却投壺玉腕勞。","各把沈香雙陸子，局中鬬累阿誰高。"]', '["分朋闲坐賭櫻桃，收却投壺玉腕勞。","各把沈香雙陸子，局中鬬累阿誰高。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('107c1617-7647-437a-8177-d719b4560a80', '宮詞一百首 七十八', '宮词一百首 七十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["禁寺紅樓內裏通，笙歌引駕夾城東。","裹頭宮監堂前立，手把牙鞘竹彈弓。"]', '["禁寺紅楼內裏通，笙歌引駕夾城东。","裹头宮監堂前立，手把牙鞘竹彈弓。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090fd046-dcc9-4ebb-a99c-417fc3ec2008', '宮詞一百首 七十九', '宮词一百首 七十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春風院院落花堆，金鎖生衣掣不開。","更築歌臺起妝殿，明朝先進畫圖來。"]', '["春风院院落花堆，金鎖生衣掣不开。","更築歌台起妝殿，明朝先進畫圖来。"]', '诗', 'shi', '', NULL, '宮詞一百首 七十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('467d3c69-6c5e-4c35-8d5b-17c42e0c2d73', '宮詞一百首 八十', '宮词一百首 八十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["舞來汗濕羅衣徹，樓上人扶下玉梯。","歸到院中重洗面，金花盆裏潑銀泥。"]', '["舞来汗濕羅衣徹，楼上人扶下玉梯。","归到院中重洗面，金花盆裏潑銀泥。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc532435-aea1-41b7-b74f-f30dc115f154', '宮詞一百首 八十一', '宮词一百首 八十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宿妝殘粉未明天，總立昭陽花樹邊。","寒食內人長白打，庫中先散與金錢。"]', '["宿妝殘粉未明天，總立昭陽花樹邊。","寒食內人长白打，庫中先散與金錢。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2addfb8d-5428-4304-866b-0af6ab74e426', '宮詞一百首 八十二', '宮词一百首 八十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["衆中偏得君王笑，偷把金箱筆硯開。","書破紅蠻隔子上，旋推當直美人來。"]', '["衆中偏得君王笑，偷把金箱笔硯开。","书破紅蠻隔子上，旋推當直美人来。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c86da712-c6eb-489f-b16d-1dddc7084bf4', '宮詞一百首 八十三', '宮词一百首 八十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["敎遍宮娥唱遍詞，暗中頭白沒人知。","樓中日日歌聲好，不問從初學阿誰。"]', '["敎遍宮娥唱遍词，暗中头白沒人知。","楼中日日歌声好，不问從初学阿誰。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb63faa5-960f-4198-8574-bc331814e42b', '宮詞一百首 八十四', '宮词一百首 八十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["青樓小婦砑裙長，總被抄名入敎坊。","春設殿前多隊舞，朋頭各自請衣裳。"]', '["青楼小婦砑裙长，總被抄名入敎坊。","春設殿前多隊舞，朋头各自請衣裳。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62607439-cdb9-4024-879f-1035c750cb87', '宮詞一百首 八十五', '宮词一百首 八十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["水中芹葉土中花，拾得還將避衆家。","總待別人般數盡，袖中拈出鬱金芽。"]', '["水中芹葉土中花，拾得還將避衆家。","總待別人般數尽，袖中拈出鬱金芽。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e5eff87-04dc-4297-937f-ca0d38a4dc23', '宮詞一百首 八十六', '宮词一百首 八十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["玉簫改調箏移柱，催換紅羅繡舞筵。","未戴柘枝花帽子，兩行宮監在簾前。"]', '["玉簫改調箏移柱，催換紅羅繡舞筵。","未戴柘枝花帽子，兩行宮監在簾前。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d4d155-6d1a-45ca-a55c-1956480dc8a2', '宮詞一百首 八十七', '宮词一百首 八十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["窗窗戶戶院相當，總有珠簾玳瑁牀。","雖道君王不來宿，帳中長是炷牙香。"]', '["窗窗戶戶院相當，總有珠簾玳瑁牀。","雖道君王不来宿，帳中长是炷牙香。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c195dc2-8eab-4b38-9b34-ed9c2423a9ef', '宮詞一百首 八十八', '宮词一百首 八十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雨入珠簾滿殿涼，避風新出玉盆湯。","內人恐要秋衣着，不住熏籠換好香。"]', '["雨入珠簾满殿涼，避风新出玉盆湯。","內人恐要秋衣着，不住熏籠換好香。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a2e87d-b5f3-423f-9079-62035f45fca2', '宮詞一百首 八十九', '宮词一百首 八十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["金吾除夜進儺名，畫袴朱衣四隊行。","院院燒燈如白日，沈香火底坐吹笙。"]', '["金吾除夜進儺名，畫袴朱衣四隊行。","院院燒灯如白日，沈香火底坐吹笙。"]', '诗', 'shi', '', NULL, '宮詞一百首 八十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a502cc3f-e82b-4972-8581-5123d83ca646', '宮詞一百首 九十', '宮词一百首 九十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["樹頭樹底覓殘紅，一片西飛一片東。","自是桃花貪結子，錯敎人恨五更風。"]', '["樹头樹底覓殘紅，一片西飞一片东。","自是桃花貪結子，錯敎人恨五更风。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0edb69f-e1e5-46bc-8481-577a118f8b4c', '宮詞一百首 九十一', '宮词一百首 九十一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["金殿當頭紫閤重，仙人掌上玉芙蓉。","太平天子朝迎日，五色雲車駕六龍。"]', '["金殿當头紫閤重，仙人掌上玉芙蓉。","太平天子朝迎日，五色云车駕六龙。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599fb506-5684-4d62-b5fa-db3c51812f8e', '宮詞一百首 九十二', '宮词一百首 九十二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鴛鴦瓦上瞥然聲，晝寢宮娥夢裏驚。","元是我王金彈子，海棠花下打流鶯。"]', '["鴛鴦瓦上瞥然声，晝寢宮娥梦裏驚。","元是我王金彈子，海棠花下打流鶯。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a572a9b-e559-4c0e-b203-f79f1aa8827d', '宮詞一百首 九十三', '宮词一百首 九十三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["忽地金輿向月陂，內人接著便相隨。","却回龍武軍前過，當處敎開臥鴨池。"]', '["忽地金輿向月陂，內人接著便相隨。","却回龙武軍前過，當处敎开臥鴨池。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2264ebda-c26d-44d0-ade0-b4e4f611f5cf', '宮詞一百首 九十四', '宮词一百首 九十四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["畫作天河刻作牛，玉梭金鑷采橋頭。","每年宮裏穿針夜，勑賜諸親乞巧樓。"]', '["畫作天河刻作牛，玉梭金鑷采橋头。","每年宮裏穿針夜，勑賜諸親乞巧楼。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39a7273e-ae33-4de7-b20e-f0f7a6c0d78c', '宮詞一百首 九十五', '宮词一百首 九十五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["春來睡困不梳頭，懶逐君王苑北游。","暫向玉花階上坐，簸錢贏得兩三籌。"]', '["春来睡困不梳头，懶逐君王苑北游。","暫向玉花階上坐，簸錢贏得兩三籌。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b633f346-d769-4271-bff8-64999918129e', '宮詞一百首 九十六', '宮词一百首 九十六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["步行送入長門裏，不許來辭舊院花。","只恐他時身到此，乞恩求赦放還家。"]', '["步行送入长门裏，不許来辞旧院花。","只恐他时身到此，乞恩求赦放還家。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b439d1-831d-4205-a029-b960752b79d3', '宮詞一百首 九十七', '宮词一百首 九十七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["縑羅不著索輕容，對面敎人染退紅。","衫子成來一遍出，明朝半片在園中。"]', '["縑羅不著索轻容，对面敎人染退紅。","衫子成来一遍出，明朝半片在园中。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b000bd9-a7a3-4324-bbb4-1e7b753c88f2', '宮詞一百首 九十八', '宮词一百首 九十八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["彈棋玉指兩叁差，背局臨虛鬬著危。","先打角頭紅子落，上三金字半邊垂。"]', '["彈棋玉指兩叁差，背局臨虛鬬著危。","先打角头紅子落，上三金字半邊垂。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76aa321-8445-4830-9fa8-ec736fa8703f', '宮詞一百首 九十九', '宮词一百首 九十九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["後宮宮女無多少，盡向園中笑一團。","舞蝶落花相覓著，春風共語亦應難。"]', '["後宮宮女無多少，尽向园中笑一團。","舞蝶落花相覓著，春风共語亦應难。"]', '诗', 'shi', '', NULL, '宮詞一百首 九十九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d2463d-b5f0-4b81-83aa-408aa2cad3b8', '宮詞一百首 一百', '宮词一百首 一百', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["宛轉黃金白柄長，青荷葉子畫鴛鴦。","把來不是呈新樣，欲進微風到御牀。"]', '["宛轉黄金白柄长，青荷葉子畫鴛鴦。","把来不是呈新樣，欲進微风到御牀。"]', '诗', 'shi', '', NULL, '宮詞一百首 一百 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7577f4d7-8b15-4133-a741-84caefc06062', '宮詞一百首 一百一', '宮词一百首 一百一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["供御香方加減頻，水沈山麝每回新。","內中不許相傳出，已被醫家寫與人。"]', '["供御香方加減頻，水沈山麝每回新。","內中不許相傳出，已被醫家寫與人。"]', '诗', 'shi', '', NULL, '宮詞一百首 一百一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('798e071a-a38c-4e59-a2fd-aaa5c7a6e1b3', '宮詞一百首 一百二', '宮词一百首 一百二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["藥童食後送雲漿，高殿無風扇少涼。","每到日中重掠鬢，衩衣騎馬繞宮廊。"]', '["藥童食後送云漿，高殿無风扇少涼。","每到日中重掠鬢，衩衣騎马繞宮廊。"]', '诗', 'shi', '', NULL, '宮詞一百首 一百二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d155e3-e149-403e-ae76-538a64295657', '句', '句', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["單于不向南牧馬，席萁遍滿天山下卻公不易勝，莫著外家欺。","錦江詩弟子，時寄五花牋。","花燒落第眼，雨破到家程。","一朝金鳳庭前下，當是虛皇詔沈曦。","宣城四面水茫茫，草蓋江城竹夾牆。"]', '["單于不向南牧马，席萁遍满天山下卻公不易勝，莫著外家欺。","錦江诗弟子，时寄五花牋。","花燒落第眼，雨破到家程。","一朝金鳳庭前下，當是虛皇詔沈曦。","宣城四面水茫茫，草蓋江城竹夾牆。"]', '诗', 'shi', '', NULL, '句 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a9d1c54-36be-433a-bf1c-35f0e839e226', '銅雀妓', '銅雀妓', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["魏主矜蛾眉，美人美於玉。","高臺無晝夜，歌舞竟未足。","盛色如轉圜，夕陽落深谷。","仍令身歿後，尚縱平生慾。","紅粉淚縱橫，調絃向空屋。","舉頭君不在，惟見西陵木。","玉輦豈再來，嬌鬟爲誰綠。","那堪秋風裏，更舞陽春曲。","曲罷情不勝，凭闌向西哭。","臺邊生野草，來去罥羅縠。","況復陵寢間，雙雙見麋鹿。"]', '["魏主矜蛾眉，美人美於玉。","高台無晝夜，歌舞竟未足。","盛色如轉圜，夕陽落深谷。","仍令身歿後，尚縱平生慾。","紅粉泪縱橫，調絃向空屋。","舉头君不在，惟见西陵木。","玉輦豈再来，嬌鬟爲誰綠。","那堪秋风裏，更舞陽春曲。","曲罷情不勝，凭闌向西哭。","台邊生野草，来去罥羅縠。","況复陵寢间，雙雙见麋鹿。"]', '诗', 'shi', '', NULL, '銅雀妓 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2bbb81-fe8c-448a-b0de-d1d518314e90', '哭韓淮端公兼上崔中丞', '哭韓淮端公兼上崔中丞', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["堅貞與和璧，利用歸干將。","金玉徒自寶，高賢無比方。","挺生巖松姿，孤直凌雪霜。","亭亭結清陰，不競桃李芳。","讀書哂霸業，翊贊思皇王。","千載有疑議，一言能否臧。","儒風久淪弊，顏閔壽不長。","邦國豈殄瘁，斯人今又亡。","別離長春草，存沒隔楚鄉。","聞問尚書慟，淚凝向日黃。","奄忽薤露晞，杳冥泉夜長。","賢愚自修短，天色空蒼蒼。","銘旌歛歸魂，荆棘生路傍。","門柳日蕭索，繐帷掩空堂。","燈孤晦處明，高節歿後彰。","芳蘭已灰燼，幕府留餘香。","常愛獨坐尊，繡衣如雁行。","至今虛左位，言發淚霑裳。"]', '["堅貞與和璧，利用归干將。","金玉徒自寶，高賢無比方。","挺生巖松姿，孤直凌雪霜。","亭亭結清陰，不競桃李芳。","读书哂霸業，翊贊思皇王。","千載有疑議，一言能否臧。","儒风久淪弊，顏閔壽不长。","邦国豈殄瘁，斯人今又亡。","別離长春草，存沒隔楚乡。","闻问尚书慟，泪凝向日黄。","奄忽薤露晞，杳冥泉夜长。","賢愚自修短，天色空蒼蒼。","銘旌歛归魂，荆棘生路傍。","门柳日蕭索，繐帷掩空堂。","灯孤晦处明，高節歿後彰。","芳蘭已灰燼，幕府留餘香。","常愛独坐尊，繡衣如雁行。","至今虛左位，言發泪霑裳。"]', '诗', 'shi', '', NULL, '哭韓淮端公兼上崔中丞 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9dd333-5f18-478b-8b18-53ed1bf06e91', '秋夜聽嚴紳巴童唱竹枝歌', '秋夜听嚴紳巴童唱竹枝歌', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["巴人遠從荆山客，回首荆山楚雲隔。","思歸夜唱竹枝歌，庭槐葉落秋風多。","曲中歷歷敘鄉土，鄉思綿綿楚詞古。","身騎吳牛不畏虎，手提簑笠欺風雨。","猨啼日暮江岸邊，綠蕪連山水連天。","來時十三今十五，一成新衣已再補。","鴻雁南飛報鄰伍，在家歡樂辭家苦。","天晴露白鐘漏遲，淚痕滿面看竹枝。","曲終寒竹風裊裊，西方落日東方曉。"]', '["巴人远從荆山客，回首荆山楚云隔。","思归夜唱竹枝歌，庭槐葉落秋风多。","曲中歷歷敘乡土，乡思綿綿楚词古。","身騎吳牛不畏虎，手提簑笠欺风雨。","猨啼日暮江岸邊，綠蕪連山水連天。","来时十三今十五，一成新衣已再補。","鴻雁南飞報鄰伍，在家歡乐辞家苦。","天晴露白鐘漏遲，泪痕满面看竹枝。","曲終寒竹风裊裊，西方落日东方晓。"]', '诗', 'shi', '', NULL, '秋夜聽嚴紳巴童唱竹枝歌 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14824f68-98d7-433e-be7c-2eff3a9a891c', '烏夜啼', '烏夜啼', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["遶樹啞啞驚復栖，含烟碧樹高枝齊。","月明露濕枝亦滑，城上女牆西月低。","愁人出戶聽烏啼，團團明月墮牆西。","月中有桂樹，日中有伴侶。","何不上天去？一聲啼到曙。"]', '["遶樹啞啞驚复栖，含烟碧樹高枝齊。","月明露濕枝亦滑，城上女牆西月低。","愁人出戶听烏啼，團團明月墮牆西。","月中有桂樹，日中有伴侶。","何不上天去？一声啼到曙。"]', '诗', 'shi', '', NULL, '烏夜啼 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2f8ac7-6cd0-4b7f-9dba-38a1b190f195', '隨陽雁歌送兄南遊', '隨陽雁歌送兄南游', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["塞鴻聲聲飛不住，終日南征向何處。","大漠窮陰多沍寒，分飛不得長懷安。","春去秋來年歲疾，湖南薊北關山難。","寒飛萬里胡天雪，夜度千門漢家月。","去住應多兩地情，東西動作經年別。","南州風土復何如，春雁歸時早寄書。"]', '["塞鴻声声飞不住，終日南征向何处。","大漠窮陰多沍寒，分飞不得长懷安。","春去秋来年歲疾，湖南薊北关山难。","寒飞万里胡天雪，夜度千门漢家月。","去住應多兩地情，东西动作經年別。","南州风土复何如，春雁归时早寄书。"]', '诗', 'shi', '', NULL, '隨陽雁歌送兄南遊 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db712ea-73c1-4162-b031-24b137bcc622', '賦得射雉歌送楊協律表弟赴婚期', '賦得射雉歌送楊協律表弟赴婚期', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["昔日才高容貌古，相敬如賓不相覩。","手奉蘋蘩喜盛門，心知禮義感君恩。","三星照戶春空盡，一樹桃花竟不言。","結束車輿強遊往，和風霽日東臯上。","鸞鳳參差陌上行，麥苗縈隴雉初鳴。","修容盡飾將何益，極慮呈材欲導情。","六藝從師得機要，百發穿楊含絕妙。","白羽風馳碎錦毛，青娥怨處嫣然笑。","楊生詞賦比潘郎，不似前賢貌不揚。","聽調琴弄能和室，更解彎弧足自防。","秋深爲爾持圓扇，莫忘魯連飛一箭。"]', '["昔日才高容貌古，相敬如賓不相覩。","手奉蘋蘩喜盛门，心知禮義感君恩。","三星照戶春空尽，一樹桃花竟不言。","結束车輿強游往，和风霽日东臯上。","鸾鳳參差陌上行，麦苗縈隴雉初鳴。","修容尽飾將何益，極慮呈材欲導情。","六藝從師得機要，百發穿楊含絕妙。","白羽风驰碎錦毛，青娥怨处嫣然笑。","楊生词賦比潘郎，不似前賢貌不揚。","听調琴弄能和室，更解彎弧足自防。","秋深爲爾持圓扇，莫忘魯連飞一箭。"]', '诗', 'shi', '', NULL, '賦得射雉歌送楊協律表弟赴婚期 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a21972-1845-42d9-9d17-e7d4987d496d', '泛舒城南溪賦得沙鶴歌奉餞張侍御赴河南元博士赴揚州拜覲僕射', '泛舒城南溪賦得沙鹤歌奉餞張侍御赴河南元博士赴揚州拜覲僕射', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["終日閭閻逐羣雞，喜逢野鶴臨清溪。","綠苔春水水中影，夜月平沙沙上栖。","驚謂汀洲白蘋發，又疑曲渚前年雪。","紫頂昂藏肯狎人，一聲嘹亮沖天闕。","素質翩翩帶落暉，湖南渭陽相背飛。","東西分散別離促，宇宙蒼茫相見稀。","皇華地仙如鶴馭，乘駕飄飄留不住。","延望乘虛入紫霞，陌頭回首空烟樹。","會使摶風羽翮輕，九霄雲路隨先鳴。"]', '["終日閭閻逐羣雞，喜逢野鹤臨清溪。","綠苔春水水中影，夜月平沙沙上栖。","驚謂汀洲白蘋發，又疑曲渚前年雪。","紫頂昂藏肯狎人，一声嘹亮沖天闕。","素質翩翩带落暉，湖南渭陽相背飞。","东西分散別離促，宇宙蒼茫相见稀。","皇华地仙如鹤馭，乘駕飄飄留不住。","延望乘虛入紫霞，陌头回首空烟樹。","會使摶风羽翮轻，九霄云路隨先鳴。"]', '诗', 'shi', '', NULL, '泛舒城南溪賦得沙鶴歌奉餞張侍御赴河南元博士赴揚州拜覲僕射 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e781fe-94d9-48fd-9d57-cc331970e10f', '姑蘇懷古送秀才下第歸江南', '姑蘇懷古送秀才下第归江南', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["姑蘇臺枕吳江水，層級鱗差向天倚。","秋高露白萬林空，低望吳田三百里。","當時雄盛如何比，千仞無根立平地。","臺前夾月吹玉鸞，臺上迎涼撼金翠。","銀河倒瀉君王醉，灩酒峩冠眄西子。","宮娃酣態舞娉婷，香飆四颯青城墜。","伍員結舌長噓嚱，忠諫無因到君耳。","城烏啼盡海霞銷，深掩金屏日高睡。","王道潛隳伍員死，可嘆斗間瞻王氣。","會稽句踐擁長矛，萬馬鳴蹄掃空壘。","瓦解冰銷真可恥，凝豔妖芳安足恃。","可憐荒堞晚冥濛，麋鹿呦呦達遺址。","君懷逸氣還東吳，吟狂日日遊姑蘇。","興來下筆到奇景，瑤盤迸灑蛟人珠。","大鵬矯翼翻雲衢，嵩峰霽後凌天孤。","海潮秋打羅剎石，月魄夜當彭蠡湖。","有時凝思家虛無，霓幢彷彿遊仙都。","琳琅暗戛玉華殿，天香靜褭金芙蕖。","君聲日下聞來久，清贍何人敢敵手。","我逃名迹遁西林，不得灞陵傾別酒。","莫便五湖爲隱淪，年年三十昇仙人。"]', '["姑蘇台枕吳江水，層級鱗差向天倚。","秋高露白万林空，低望吳田三百里。","當时雄盛如何比，千仞無根立平地。","台前夾月吹玉鸾，台上迎涼撼金翠。","銀河倒瀉君王醉，灩酒峩冠眄西子。","宮娃酣態舞娉婷，香飆四颯青城墜。","伍員結舌长噓嚱，忠諫無因到君耳。","城烏啼尽海霞銷，深掩金屏日高睡。","王道潛隳伍員死，可嘆斗间瞻王氣。","會稽句踐擁长矛，万马鳴蹄掃空壘。","瓦解冰銷真可恥，凝豔妖芳安足恃。","可怜荒堞晚冥濛，麋鹿呦呦達遺址。","君懷逸氣還东吳，吟狂日日游姑蘇。","兴来下笔到奇景，瑤盤迸灑蛟人珠。","大鵬矯翼翻云衢，嵩峰霽後凌天孤。","海潮秋打羅剎石，月魄夜當彭蠡湖。","有时凝思家虛無，霓幢彷彿游仙都。","琳琅暗戛玉华殿，天香静褭金芙蕖。","君声日下闻来久，清贍何人敢敵手。","我逃名迹遁西林，不得灞陵傾別酒。","莫便五湖爲隐淪，年年三十昇仙人。"]', '诗', 'shi', '', NULL, '姑蘇懷古送秀才下第歸江南 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc25343e-4e2d-46b0-a856-c2465581ef90', '金井歌', '金井歌', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["文明化洽天地清，和氣氤氳孕至靈。","瑞雪不散抱層嶺，陽谷霞光射山頂。","薙草披沙石竇開，生金曜日明金井。","虞衡相賀爲禎祥，畏人採攫持殳戕。","羊馳馬走塵滿道，郡邸封章開建章。","君王儉德先簡易，贍國肥家在仁義。","山澤藏金與萬人，宣言郡邑無專利。","閭閻少長競奔凑，黃金滿袖家富有。","驩心蹈舞歌皇風，願載謳歌青史中。"]', '["文明化洽天地清，和氣氤氳孕至靈。","瑞雪不散抱層嶺，陽谷霞光射山頂。","薙草披沙石竇开，生金曜日明金井。","虞衡相賀爲禎祥，畏人採攫持殳戕。","羊驰马走塵满道，郡邸封章开建章。","君王儉德先簡易，贍国肥家在仁義。","山澤藏金與万人，宣言郡邑無專利。","閭閻少长競奔凑，黄金满袖家富有。","驩心蹈舞歌皇风，願載謳歌青史中。"]', '诗', 'shi', '', NULL, '金井歌 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a0aeeef-7f97-44a4-969b-ce61c69043c3', '柳條歌送客', '柳條歌送客', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["露井夭桃春未到，遲日猶寒柳開早。","高枝低枝飛鸝黃，千條萬條覆宮牆。","幾回離別折欲盡，一夜東風吹又長。","毿毿拂人行不進，依依送君無遠近。","青春去住隨柳條，却寄來人以爲信。"]', '["露井夭桃春未到，遲日猶寒柳开早。","高枝低枝飞鸝黄，千條万條覆宮牆。","幾回離別折欲尽，一夜东风吹又长。","毿毿拂人行不進，依依送君無远近。","青春去住隨柳條，却寄来人以爲信。"]', '诗', 'shi', '', NULL, '柳條歌送客 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c752cff2-b969-4ada-b562-bc5cc58caaa3', '胡笳十八拍 第一拍', '胡笳十八拍 第一拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["漢室將衰兮四夷不賓，動干戈兮征戰頻。","哀哀父母生育我，見離亂兮當此辰。","紗窗對鏡未經事，將謂珠簾能蔽身。","一朝胡騎入中國，蒼黃處處逢胡人。","忽將薄命委鋒鏑，可惜紅顏隨虜塵。"]', '["漢室將衰兮四夷不賓，动干戈兮征戰頻。","哀哀父母生育我，见離亂兮當此辰。","紗窗对镜未經事，將謂珠簾能蔽身。","一朝胡騎入中国，蒼黄处处逢胡人。","忽將薄命委鋒鏑，可惜紅顏隨虜塵。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第一拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8aa9275-c55a-4d12-aff9-fffb282530b4', '胡笳十八拍 第二拍', '胡笳十八拍 第二拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["馬上將余向絕域，厭生求死死不得。","戎羯腥膻豈是人，豺狼喜怒難姑息。","行盡天山足霜霰，風土蕭條近胡國。","萬里重陰鳥不飛，寒沙莽莽無南北。"]', '["马上將余向絕域，厭生求死死不得。","戎羯腥膻豈是人，豺狼喜怒难姑息。","行尽天山足霜霰，风土蕭條近胡国。","万里重陰鸟不飞，寒沙莽莽無南北。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第二拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e600dd7-b922-4ec2-b694-0d4eaeaa86bb', '胡笳十八拍 第三拍', '胡笳十八拍 第三拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["如羇囚兮在縲絏，憂慮萬端無處說。","使余刀兮剪余髮，食余肉兮飲余血。","誠知殺身願如此，以余爲妻不如死。","早被蛾眉累此身，空悲弱質柔如水。"]', '["如羇囚兮在縲絏，憂慮万端無处说。","使余刀兮剪余髮，食余肉兮饮余血。","誠知殺身願如此，以余爲妻不如死。","早被蛾眉累此身，空悲弱質柔如水。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第三拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d1e936-b9ac-465b-8f25-c2e4df0e6658', '胡笳十八拍 第四拍', '胡笳十八拍 第四拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["山川路長誰記得，何處天涯是鄉國。","自從驚怖少精神，不覺風霜損顏色。","夜中歸夢來又去，朦朧豈解傳消息。","漫漫胡天叫不聞，明明漢月應相識。"]', '["山川路长誰記得，何处天涯是乡国。","自從驚怖少精神，不覺风霜損顏色。","夜中归梦来又去，朦朧豈解傳消息。","漫漫胡天叫不闻，明明漢月應相識。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第四拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b34c23-9d12-4503-b7c8-057c815ed34f', '胡笳十八拍 第五拍', '胡笳十八拍 第五拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["水頭宿兮草頭坐，風吹漢地衣裳破。","羊脂沐髮長不梳，羔子皮裘領仍左。","狐襟貉袖腥復膻，晝披行兮夜披臥。","氈帳時移無定居，日月長兮不可過。"]', '["水头宿兮草头坐，风吹漢地衣裳破。","羊脂沐髮长不梳，羔子皮裘領仍左。","狐襟貉袖腥复膻，晝披行兮夜披臥。","氈帳时移無定居，日月长兮不可過。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第五拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ce2ebb-5660-4c5a-b360-e8352c651df6', '胡笳十八拍 第六拍', '胡笳十八拍 第六拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["怪得春光不來久，胡中風土無花柳。","天翻地覆誰得知，如今正南看北斗。","姓名音信兩不通，終日經年常閉口。","是非取與在指撝，言語傳情不如手。"]', '["怪得春光不来久，胡中风土無花柳。","天翻地覆誰得知，如今正南看北斗。","姓名音信兩不通，終日經年常閉口。","是非取與在指撝，言語傳情不如手。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第六拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d2dfe8-40c2-42ec-9dee-72a1480571de', '胡笳十八拍 第七拍', '胡笳十八拍 第七拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["男兒婦人帶弓箭，塞馬蕃羊臥霜霰。","寸步東西豈自由，偷生乞死非情願。","龜茲觱篥愁中聽，碎葉琵琶夜深怨。","竟夕無雲月上天，故鄉應得重相見。"]', '["男兒婦人带弓箭，塞马蕃羊臥霜霰。","寸步东西豈自由，偷生乞死非情願。","龟茲觱篥愁中听，碎葉琵琶夜深怨。","竟夕無云月上天，故乡應得重相见。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第七拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d98fe1d-74b2-4b61-8112-1d2e9beaf6d8', '胡笳十八拍 第八拍', '胡笳十八拍 第八拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["憶昔私家恣嬌小，遠取珍禽學馴擾。","如今淪棄念故鄉，悔不當初放林表。","朔風蕭蕭寒日暮，星河寥落胡天曉。","旦夕思歸不得歸，愁心想似籠中鳥。"]', '["憶昔私家恣嬌小，远取珍禽学馴擾。","如今淪棄念故乡，悔不當初放林表。","朔风蕭蕭寒日暮，星河寥落胡天晓。","旦夕思归不得归，愁心想似籠中鸟。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第八拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa098574-5f7e-4be3-b8d1-5a1e7bc8040d', '胡笳十八拍 第九拍', '胡笳十八拍 第九拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["當日蘇武單于問，道是賓鴻解傳信。","學他刺血寫得書，書上千重萬重恨。","髯胡少年能走馬，彎弓射飛無遠近。","遂令邊雁轉怕人，絕域何由達方寸。"]', '["當日蘇武單于问，道是賓鴻解傳信。","学他刺血寫得书，书上千重万重恨。","髯胡少年能走马，彎弓射飞無远近。","遂令邊雁轉怕人，絕域何由達方寸。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第九拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3128f181-3841-403b-bb63-75cff2210e7b', '胡笳十八拍 第十拍', '胡笳十八拍 第十拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["恨凌辱兮惡腥膻，憎胡地兮怨胡天。","生得胡兒欲棄捐，及生母子情宛然。","貌殊語異憎還愛，心中不覺常相牽。","朝朝暮暮在眼前，腹生手養寧不憐。"]', '["恨凌辱兮惡腥膻，憎胡地兮怨胡天。","生得胡兒欲棄捐，及生母子情宛然。","貌殊語異憎還愛，心中不覺常相牽。","朝朝暮暮在眼前，腹生手養寧不怜。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5c1f94-f4af-464d-a9c7-feee2cdddd51', '胡笳十八拍 第十一拍', '胡笳十八拍 第十一拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["日來月往相催遷，迢迢星歲欲周天。","無冬無夏臥霜霰，水凍草枯爲一年。","漢家甲子有正朔，絕域三光空自懸。","幾回鴻雁來又去，腸斷蟾蜍虧復圓。"]', '["日来月往相催遷，迢迢星歲欲周天。","無冬無夏臥霜霰，水凍草枯爲一年。","漢家甲子有正朔，絕域三光空自懸。","幾回鴻雁来又去，腸斷蟾蜍虧复圓。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十一拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855f3a4e-d57b-455d-91a2-8680575a592c', '胡笳十八拍 第十二拍', '胡笳十八拍 第十二拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["破瓶落井空永沈，故鄉望斷無歸心。","寧知遠使問姓名，漢語泠泠傳好音。","夢魂幾度到鄉國，覺後翻成哀怨深。","如今果是夢中事，喜過悲來情不任。"]', '["破瓶落井空永沈，故乡望斷無归心。","寧知远使问姓名，漢語泠泠傳好音。","梦魂幾度到乡国，覺後翻成哀怨深。","如今果是梦中事，喜過悲来情不任。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十二拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b4f82e-7435-463a-bd8c-c4556930e757', '胡笳十八拍 第十三拍', '胡笳十八拍 第十三拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["童稚牽衣雙在側，將來不可留又憶。","還鄉惜別兩難分，寧棄胡兒歸舊國。","山川萬里復邊戍，背面無由得消息。","淚痕滿面對殘陽，終日依依向南北。"]', '["童稚牽衣雙在側，將来不可留又憶。","還乡惜別兩难分，寧棄胡兒归旧国。","山川万里复邊戍，背面無由得消息。","泪痕满面对殘陽，終日依依向南北。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十三拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57e95e45-fd2e-45e6-ac84-770e801192ef', '胡笳十八拍 第十四拍', '胡笳十八拍 第十四拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["莫以胡兒可羞耻，恩情亦各言其子。","手中十指有長短，截之痛惜皆相似。","還鄉豈不見親族，念此飄零隔生死。","南風萬里吹我心，心亦隨風度遼水。"]', '["莫以胡兒可羞耻，恩情亦各言其子。","手中十指有长短，截之痛惜皆相似。","還乡豈不见親族，念此飄零隔生死。","南风万里吹我心，心亦隨风度遼水。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十四拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc3f33f8-4a8a-4f6c-bbb2-1d911272a2d4', '胡笳十八拍 第十五拍', '胡笳十八拍 第十五拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["歎息襟懷無定分，當時怨來歸又恨。","不知愁怨情若何，似有鋒鋩擾方寸。","悲歡竝行情未快，心意相尤自相問。","不緣生得天屬親，豈向仇讐結恩信。"]', '["歎息襟懷無定分，當时怨来归又恨。","不知愁怨情若何，似有鋒鋩擾方寸。","悲歡竝行情未快，心意相尤自相问。","不緣生得天屬親，豈向仇讐結恩信。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十五拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d879f5-cf71-4fc0-b691-48b4800e4610', '胡笳十八拍 第十六拍', '胡笳十八拍 第十六拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["去時只覺天蒼蒼，歸日始知胡地長。","重陰白日落何處，秋雁所向應南方。","平沙四顧自迷惑，遠近悠悠隨雁行。","征途未盡馬蹄盡，不見行人邊草黃。"]', '["去时只覺天蒼蒼，归日始知胡地长。","重陰白日落何处，秋雁所向應南方。","平沙四顧自迷惑，远近悠悠隨雁行。","征途未尽马蹄尽，不见行人邊草黄。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十六拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bac9387-46ad-4204-aa27-0b802d854d99', '胡笳十八拍 第十七拍', '胡笳十八拍 第十七拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["行盡胡天千萬里，唯見黃沙白雲起。","馬飢跑雪銜草根，人渴敲冰飲流水。","燕山髣髴辨烽戍，鼙鼓如聞漢家壘。","努力前程是帝鄉，生前免向胡中死。"]', '["行尽胡天千万里，唯见黄沙白云起。","马飢跑雪銜草根，人渴敲冰饮流水。","燕山髣髴辨烽戍，鼙鼓如闻漢家壘。","努力前程是帝乡，生前免向胡中死。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十七拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77a5ef08-2dcc-407a-8435-8a675d8cd159', '胡笳十八拍 第十八拍', '胡笳十八拍 第十八拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["歸來故鄉見親族，田園半蕪春草綠。","明燭重燃煨燼灰，寒泉更洗沈泥玉。","載持巾櫛禮儀好，一弄絲桐生死足。","出入關山十二年，哀情盡在胡笳曲。"]', '["归来故乡见親族，田园半蕪春草綠。","明燭重燃煨燼灰，寒泉更洗沈泥玉。","載持巾櫛禮儀好，一弄絲桐生死足。","出入关山十二年，哀情尽在胡笳曲。"]', '诗', 'shi', '', NULL, '胡笳十八拍 第十八拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8175d362-c8b9-466d-a738-fc95652ee00c', '雜言同豆盧郎中郭南七里橋哀悼姚倉曹', '杂言同豆盧郎中郭南七里橋哀悼姚倉曹', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["橋邊足離別，終日爲悲辛。","登橋因歎逝，却羨別離人。","橋下東流水，芳樹櫻桃蘂。","流水與潮迴，花落明年開。","可憐三語掾，長作九泉灰。","宿昔歡遊在何處，花前飲足求仙去。"]', '["橋邊足離別，終日爲悲辛。","登橋因歎逝，却羨別離人。","橋下东流水，芳樹櫻桃蘂。","流水與潮迴，花落明年开。","可怜三語掾，长作九泉灰。","宿昔歡游在何处，花前饮足求仙去。"]', '诗', 'shi', '', NULL, '雜言同豆盧郎中郭南七里橋哀悼姚倉曹 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e3c503-b936-42f7-a20b-aa67fb63bd42', '春日臥病', '春日臥病', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["楚客經年病，孤舟人事稀。","晚晴江柳變，春暮塞鴻歸。","今日方知命，前身自覺非。","不能憂歲計，無限故山薇。"]', '["楚客經年病，孤舟人事稀。","晚晴江柳变，春暮塞鴻归。","今日方知命，前身自覺非。","不能憂歲計，無限故山薇。"]', '诗', 'shi', '', NULL, '春日臥病 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f57929-32fc-4b75-a67c-5c8a205b6633', '題禪居廢寺', '題禪居廢寺', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["凋殘精舍在，連步訪緇衣。","古殿門空掩，楊花雪亂飛。","鶴巢松影薄，僧少磬聲稀。","青眼能留客，疎鐘逼夜歸。"]', '["凋殘精舍在，連步訪緇衣。","古殿门空掩，楊花雪亂飞。","鹤巢松影薄，僧少磬声稀。","青眼能留客，疎鐘逼夜归。"]', '诗', 'shi', '', NULL, '題禪居廢寺 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('750681cd-241e-47e4-ae58-75a805741d79', '題山寺', '題山寺', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["扁舟水淼淼，曲岸復長塘。","古寺春山上，登樓憶故鄉。","雲烟橫極浦，花木擁迴廊。","更有思歸意，晴明陟上方。"]', '["扁舟水淼淼，曲岸复长塘。","古寺春山上，登楼憶故乡。","云烟橫極浦，花木擁迴廊。","更有思归意，晴明陟上方。"]', '诗', 'shi', '', NULL, '題山寺 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f28d3b72-4f74-44fd-bf93-47cc98b943a3', '題楊侍郎新亭', '題楊侍郎新亭', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["毘陵過柱史，簡易在茅茨。","芳草如花種，修篁帶笋移。","徑幽人未賞，簷靜燕初窺。","野客憐霜壁，青松畫一枝。"]', '["毘陵過柱史，簡易在茅茨。","芳草如花種，修篁带笋移。","徑幽人未賞，簷静燕初窺。","野客怜霜壁，青松畫一枝。"]', '诗', 'shi', '', NULL, '題楊侍郎新亭 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f52d4d-4255-4974-847a-0511d42332a5', '同徐城季明府遊重光寺題晃師壁', '同徐城季明府游重光寺題晃師壁', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["野寺僧房遠，陶潛引客來。","鳥喧殘果落，蘭敗幾花開。","真性知無住，微言欲望迴。","竹風清磬晚，歸策步蒼苔。"]', '["野寺僧房远，陶潛引客来。","鸟喧殘果落，蘭敗幾花开。","真性知無住，微言欲望迴。","竹风清磬晚，归策步蒼苔。"]', '诗', 'shi', '', NULL, '同徐城季明府遊重光寺題晃師壁 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54057edc-c57e-48c5-9aab-9e6a78dfc58b', '送林袞侍御東陽秩滿赴上都', '送林袞侍御东陽秩满赴上都', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["幾年烏府內，何處逐鳧歸。","關吏迷驄馬，銅章累繡衣。","野亭山草綠，客路柳花飛。","況復長安遠，音書從此稀。"]', '["幾年烏府內，何处逐鳧归。","关吏迷驄马，銅章累繡衣。","野亭山草綠，客路柳花飞。","況复长安远，音书從此稀。"]', '诗', 'shi', '', NULL, '送林袞侍御東陽秩滿赴上都 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed324ccb-055a-4da7-9807-8464a8eb46d1', '送人之江東', '送人之江东', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["含香仍佩玉，宜入鏡中行。","盡室隨乘興，扁舟不計程。","渡江霖雨霽，對月夜潮生。","莫慮當炎暑，稽山水木清。"]', '["含香仍佩玉，宜入镜中行。","尽室隨乘兴，扁舟不計程。","渡江霖雨霽，对月夜潮生。","莫慮當炎暑，稽山水木清。"]', '诗', 'shi', '', NULL, '送人之江東 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256d9d34-901b-4586-bd9c-bfddbdf025db', '送李元規昆季赴舉', '送李元規昆季赴舉', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["見誦甘泉賦，心期折桂歸。","鳳雛皆五色，鴻漸又雙飛。","別思看衰柳，秋風動客衣。","明朝問禮處，蹔覺雁行稀。"]', '["见誦甘泉賦，心期折桂归。","鳳雛皆五色，鴻漸又雙飞。","別思看衰柳，秋风动客衣。","明朝问禮处，蹔覺雁行稀。"]', '诗', 'shi', '', NULL, '送李元規昆季赴舉 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04bee0c-2dd1-4ce8-8363-3be2f06db71b', '送楊閑侍御拜命赴上都', '送楊闲侍御拜命赴上都', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["賀客移星使，絲綸出紫微。","手中霜作簡，身上繡爲衣。","驄馬朝天疾，臺烏向日飛。","親朋皆避路，不是送人稀。"]', '["賀客移星使，絲綸出紫微。","手中霜作簡，身上繡爲衣。","驄马朝天疾，台烏向日飞。","親朋皆避路，不是送人稀。"]', '诗', 'shi', '', NULL, '送楊閑侍御拜命赴上都 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d693be-a8d4-4ad2-a205-cf0d30255e90', '賦得月下聞蛩送別', '賦得月下闻蛩送別', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["物候改秋節，炎涼此夕分。","暗蟲聲徧草，明月夜無雲。","清逈簷外見，淒其籬下聞。","感時兼惜別，羇思自紛紛。"]', '["物候改秋節，炎涼此夕分。","暗蟲声徧草，明月夜無云。","清逈簷外见，淒其籬下闻。","感时兼惜別，羇思自紛紛。"]', '诗', 'shi', '', NULL, '賦得月下聞蛩送別 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fba7ff9-acd9-4dce-bfbc-2e071547103d', '重陽日寄上饒李明府', '重陽日寄上饒李明府', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["重陽秋雁未啣蘆，始覺他鄉節候殊。","旅館但知聞蟋蟀，郵童不解獻茱萸。","陶潛何處登高醉，倦客停橈一事無。","來歲公田多種黍，莫敎黃菊笑楊朱。"]', '["重陽秋雁未啣蘆，始覺他乡節候殊。","旅館但知闻蟋蟀，郵童不解獻茱萸。","陶潛何处登高醉，倦客停橈一事無。","来歲公田多種黍，莫敎黄菊笑楊朱。"]', '诗', 'shi', '', NULL, '重陽日寄上饒李明府 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd5f08ab-e872-48df-978b-369433e46e7d', '同諸子哭張元易', '同諸子哭張元易', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["盛德高名總是空，神明福善大朦朧。","遊魂永永無歸日，流水年年自向東。","素帷旅櫬鄉關遠，丹旐孤燈客舍中。","伯道共悲無後嗣，孀妻老母斷根蓬。"]', '["盛德高名總是空，神明福善大朦朧。","游魂永永無归日，流水年年自向东。","素帷旅櫬乡关远，丹旐孤灯客舍中。","伯道共悲無後嗣，孀妻老母斷根蓬。"]', '诗', 'shi', '', NULL, '同諸子哭張元易 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35922d1a-9bd6-4c05-aa45-274cf51ded24', '合肥至日愁中寄鄭明府', '合肥至日愁中寄鄭明府', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["失計爲卑吏，三年滯楚鄉。","不能隨世俗，應是昧行藏。","白璧空無玷，黃沙只自傷。","暮天鄉思亂，曉鏡鬢毛蒼。","灰管移新律，窮陰變一陽。","歲時人共換，幽憤日先長。","拙宦慚知己，無媒悔自強。","迍邅羞薄命，恩惠費餘光。","衆口誠難稱，長川却易防。","魚竿今尚在，行此掉滄浪。"]', '["失計爲卑吏，三年滯楚乡。","不能隨世俗，應是昧行藏。","白璧空無玷，黄沙只自傷。","暮天乡思亂，晓镜鬢毛蒼。","灰管移新律，窮陰变一陽。","歲时人共換，幽憤日先长。","拙宦慚知己，無媒悔自強。","迍邅羞薄命，恩惠費餘光。","衆口誠难稱，长川却易防。","鱼竿今尚在，行此掉滄浪。"]', '诗', 'shi', '', NULL, '合肥至日愁中寄鄭明府 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0bfd0f1-c4ef-46fe-a535-5effc4ca87b6', '送廬州賈使君拜命', '送廬州賈使君拜命', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["考績朝稱貴，時清武用文。","二天移外府，三命佐元勳。","佩玉兼高位，摐金閱上軍。","威容冠是鐵，圖畫閣名芸。","人詠甘棠茂，童謠竹馬羣。","懸旌風肅肅，臥轍淚紛紛。","特達恩難報，升沈路易分。","侯嬴不得從，心逐信陵君。"]', '["考績朝稱貴，时清武用文。","二天移外府，三命佐元勳。","佩玉兼高位，摐金閱上軍。","威容冠是鐵，圖畫閣名芸。","人詠甘棠茂，童謠竹马羣。","懸旌风肅肅，臥轍泪紛紛。","特達恩难報，升沈路易分。","侯嬴不得從，心逐信陵君。"]', '诗', 'shi', '', NULL, '送廬州賈使君拜命 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('356e693d-f163-4cfb-ba12-54c808e63828', '怨婦', '怨婦', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["淨掃黃金階，飛霜皎如雪。","下簾彈箜篌，不忍見秋月。"]', '["淨掃黄金階，飞霜皎如雪。","下簾彈箜篌，不忍见秋月。"]', '诗', 'shi', '', NULL, '怨婦 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1af41365-8613-43b1-b7e7-ec4bc29016a2', '綠珠怨', '綠珠怨', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["從來上臺榭，不敢倚闌干。","零落知成血，高樓直下看。"]', '["從来上台榭，不敢倚闌干。","零落知成血，高楼直下看。"]', '诗', 'shi', '', NULL, '綠珠怨 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d40eb55-efed-44ae-a45d-994044bd05e7', '古意', '古意', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["達曉寢衣冷，開帷霜露凝。","風吹昨夜淚，一片枕前冰。"]', '["達晓寢衣冷，开帷霜露凝。","风吹昨夜泪，一片枕前冰。"]', '诗', 'shi', '', NULL, '古意 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6704ae-d21f-4be6-ab2c-b2627696130a', '哭蕭掄', '哭蕭掄', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["何處哭故人，青門水如箭。","當時水頭別，從此不相見。"]', '["何处哭故人，青门水如箭。","當时水头別，從此不相见。"]', '诗', 'shi', '', NULL, '哭蕭掄 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c07bf8-fca7-4c72-91d2-f7043d2c972a', '送從弟赴上都', '送從弟赴上都', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["車騎秦城遠，囊裝楚客貧。","月明思遠道，詩罷訴何人。"]', '["车騎秦城远，囊裝楚客貧。","月明思远道，诗罷訴何人。"]', '诗', 'shi', '', NULL, '送從弟赴上都 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f97955-cff6-4990-879b-acd33c85c53d', '登相國寺閣', '登相国寺閣', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["晴日登臨好，春風各望家。","垂楊夾城路，客思逐楊花。"]', '["晴日登臨好，春风各望家。","垂楊夾城路，客思逐楊花。"]', '诗', 'shi', '', NULL, '登相國寺閣 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('465abfc8-fe1f-4cc3-a9f3-5479f87cbfc0', '酬濬上人采藥見寄', '酬濬上人采藥见寄', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["玉英期共采，雲嶺獨先過。","應得靈芝也，詩情一倍多。"]', '["玉英期共采，云嶺独先過。","應得靈芝也，诗情一倍多。"]', '诗', 'shi', '', NULL, '酬濬上人采藥見寄 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d6b275-c8b1-4bd6-9670-8a50b5be44d1', '曲水寺枳實', '曲水寺枳實', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["枳實遶僧房，攀枝置藥囊。","洞庭山上橘，霜落也應黃。"]', '["枳實遶僧房，攀枝置藥囊。","洞庭山上橘，霜落也應黄。"]', '诗', 'shi', '', NULL, '曲水寺枳實 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29cf1bbc-2b05-497a-89d2-961b2f7235d6', '酬問師', '酬问師', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["虛空無處所，髣髴似琉璃。","詩境何人到，禪心又過詩。"]', '["虛空無处所，髣髴似琉璃。","诗境何人到，禪心又過诗。"]', '诗', 'shi', '', NULL, '酬問師 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d70ecfb-07ba-41c3-81ed-d4f8fbc8e1e4', '殷秀才求詩', '殷秀才求诗', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["傾蓋見芳姿，晴天瓊樹枝。","連城猶隱石，唯有卞和知。"]', '["傾蓋见芳姿，晴天瓊樹枝。","連城猶隐石，唯有卞和知。"]', '诗', 'shi', '', NULL, '殷秀才求詩 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7723ef-bcde-4e91-8d32-dd66a03dadbe', '行營即事', '行營即事', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["萬姓厭干戈，三邊尚未和。","將軍誇寶劒，功在殺人多。"]', '["万姓厭干戈，三邊尚未和。","將軍誇寶劒，功在殺人多。"]', '诗', 'shi', '', NULL, '行營即事 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02efac18-657f-49cc-aec7-bb821b0fa2d4', '送劉寰北歸', '送劉寰北归', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["南巢登望縣城孤，半是青山半是湖。","知爾素多山水興，此回歸去更來無。"]', '["南巢登望縣城孤，半是青山半是湖。","知爾素多山水兴，此回归去更来無。"]', '诗', 'shi', '', NULL, '送劉寰北歸 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('119ad018-c432-46e0-8ead-829e7ed61524', '送王閈歸蘇州', '送王閈归蘇州', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["深山窮谷沒人來，邂逅相逢眼漸開。","雲鶴洞宮君未到，夕陽帆影幾時回。"]', '["深山窮谷沒人来，邂逅相逢眼漸开。","云鹤洞宮君未到，夕陽帆影幾时回。"]', '诗', 'shi', '', NULL, '送王閈歸蘇州 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4541bc-5bdc-49d4-9124-e6933d65476f', '送人往虔州', '送人往虔州', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["莫歎乘軺道路賒，高樓日日望還家。","人到南康皆下淚，唯君笑向此中花。"]', '["莫歎乘軺道路賒，高楼日日望還家。","人到南康皆下泪，唯君笑向此中花。"]', '诗', 'shi', '', NULL, '送人往虔州 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17774136-42b0-4654-9f76-ba85f51636bd', '送僧往湖南', '送僧往湖南', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["閑出東林日影斜，稻苗深淺映袈裟。","船到南湖風浪靜，可憐秋水照蓮花。"]', '["闲出东林日影斜，稻苗深淺映袈裟。","船到南湖风浪静，可怜秋水照蓮花。"]', '诗', 'shi', '', NULL, '送僧往湖南 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d2b298-db42-432a-b85d-06e27c0fcb69', '送元使君自楚移越', '送元使君自楚移越', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["露冕行春向若耶，野人懷惠欲移家。","東風二月淮陰郡，唯見棠棃一樹花。"]', '["露冕行春向若耶，野人懷惠欲移家。","东风二月淮陰郡，唯见棠棃一樹花。"]', '诗', 'shi', '', NULL, '送元使君自楚移越 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59943608-abc3-4a86-bc2b-9f8b908e7de8', '移居深山謝別親故', '移居深山謝別親故', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["不食黃精不采薇，葛苗爲帶草爲衣。","孤雲更入深山去，人絕音書鴈自飛。"]', '["不食黄精不采薇，葛苗爲带草爲衣。","孤云更入深山去，人絕音书鴈自飞。"]', '诗', 'shi', '', NULL, '移居深山謝別親故 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9006f890-2596-4f9a-a3e3-d089ece014f9', '送王永二首 一', '送王永二首 一', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["君去春山誰共遊，鳥啼花落水空流。","如今送別臨溪水，他日相思來水頭。"]', '["君去春山誰共游，鸟啼花落水空流。","如今送別臨溪水，他日相思来水头。"]', '诗', 'shi', '', NULL, '送王永二首 一 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('371339b3-696f-43ab-8715-80ea68d66c43', '送王永二首 二', '送王永二首 二', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["綿衣似熱裌衣寒，時景雖和春已闌。","誠知暫別那惆悵，明日藤花獨自看。"]', '["綿衣似熱裌衣寒，时景雖和春已闌。","誠知暫別那惆悵，明日藤花独自看。"]', '诗', 'shi', '', NULL, '送王永二首 二 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb2df11c-a56d-4f06-99c6-3e6aebb5735a', '送別', '送別', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["灞岸青門有弊廬，昨來聞道半丘墟。","陌頭空送長安使，舊里無人可寄書。"]', '["灞岸青门有弊廬，昨来闻道半丘墟。","陌头空送长安使，旧里無人可寄书。"]', '诗', 'shi', '', NULL, '送別 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d26413-135b-4aca-a9e4-2fdb38e9f179', '送王貞', '送王貞', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["清陽玉潤復多才，邂逅佳期過早梅。","槿花亦可浮杯上，莫待東籬黃菊開。"]', '["清陽玉潤复多才，邂逅佳期過早梅。","槿花亦可浮杯上，莫待东籬黄菊开。"]', '诗', 'shi', '', NULL, '送王貞 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3745633d-edd0-42dd-b7d3-8282a9c4f717', '送薛六暫遊揚州', '送薛六暫游揚州', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["志在乘軒鳴玉珂，心期未快隱青蘿。","廣陵行路風塵合，城郭新秋砧杵多。"]', '["志在乘軒鳴玉珂，心期未快隐青蘿。","廣陵行路风塵合，城郭新秋砧杵多。"]', '诗', 'shi', '', NULL, '送薛六暫遊揚州 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8ebc78-ed9b-4fae-a972-2ebbae61ebce', '送楊行元赴舉', '送楊行元赴舉', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["晚渡邗溝惜別離，漸看烽火馬行遲。","千鈞何處穿楊葉，二月長安折桂枝。"]', '["晚渡邗溝惜別離，漸看烽火马行遲。","千鈞何处穿楊葉，二月长安折桂枝。"]', '诗', 'shi', '', NULL, '送楊行元赴舉 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46334573-2f4a-4e35-9e18-4deb7a7c8ac1', '行營送人', '行營送人', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["鞞鼓喧喧對古城，獨尋歸鳥馬蹄輕。","回來看覓鶯飛處，即是將軍細柳營。"]', '["鞞鼓喧喧对古城，独尋归鸟马蹄轻。","回来看覓鶯飞处，即是將軍細柳營。"]', '诗', 'shi', '', NULL, '行營送人 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b4b3ec-cdb5-4bc7-93a3-e3fbcd60a43d', '滑州送人先歸', '滑州送人先归', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["河水冰消鴈北飛，寒衣未足又春衣。","自憐漂蕩經年客，送別千回獨未歸。"]', '["河水冰消鴈北飞，寒衣未足又春衣。","自怜漂蕩經年客，送別千回独未归。"]', '诗', 'shi', '', NULL, '滑州送人先歸 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('110ef313-093d-49d2-b5f0-1ce203b9e115', '送濬上人', '送濬上人', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["木落前山霜露多，手持寒錫遠頭陀。","眼看庭樹梅花發，不見詩人獨詠歌。"]', '["木落前山霜露多，手持寒錫远头陀。","眼看庭樹梅花發，不见诗人独詠歌。"]', '诗', 'shi', '', NULL, '送濬上人 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a8cfd4-93a0-4db4-8448-3401f948ae00', '高郵送弟遇北遊', '高郵送弟遇北游', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["門臨楚國舟船路，易見行人易別離。","今日送君心最恨，孤帆水下又風吹。"]', '["门臨楚国舟船路，易见行人易別離。","今日送君心最恨，孤帆水下又风吹。"]', '诗', 'shi', '', NULL, '高郵送弟遇北遊 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9efe2dcf-cbd4-4c86-82f7-053e645ff62e', '送豆盧郎赴海陵', '送豆盧郎赴海陵', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["煙波極目已霑襟，路出東塘水更深。","看取海頭秋草色，一如江上別離心。"]', '["煙波極目已霑襟，路出东塘水更深。","看取海头秋草色，一如江上別離心。"]', '诗', 'shi', '', NULL, '送豆盧郎赴海陵 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b677e8-2657-4d20-9572-1a7479846124', '送女子', '送女子', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["青娥宛宛聚爲裳，烏鵲橋成別恨長。","惆悵梧桐非舊影，不悲鴻鴈暫隨陽。"]', '["青娥宛宛聚爲裳，烏鵲橋成別恨长。","惆悵梧桐非旧影，不悲鴻鴈暫隨陽。"]', '诗', 'shi', '', NULL, '送女子 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0490ac79-e0b9-40e7-bad3-08f6bdd09813', '酬道芬寄晝松', '酬道芬寄晝松', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["聞道鉛華學沈寧，寒枝淅瀝葉青青。","一株將比囊中樹，若箇年多有茯苓。"]', '["闻道鉛华学沈寧，寒枝淅瀝葉青青。","一株將比囊中樹，若箇年多有茯苓。"]', '诗', 'shi', '', NULL, '酬道芬寄晝松 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e7272cc-f032-47e6-abf5-bff9c8970617', '山翁持酒相訪以畫松酬之', '山翁持酒相訪以畫松酬之', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["白社風霜驚暮年，銅瓶桑落慰秋天。","憐君意厚留新畫，不著松枝當酒錢。"]', '["白社风霜驚暮年，銅瓶桑落慰秋天。","怜君意厚留新畫，不著松枝當酒錢。"]', '诗', 'shi', '', NULL, '山翁持酒相訪以畫松酬之 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0193ce9-d07b-4ee6-8424-c57ba5b5d7ee', '題潘師房', '題潘師房', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["渡水傍山尋石壁，白雲飛處洞門開。","仙人來往行無跡，石徑春風長綠苔。"]', '["渡水傍山尋石壁，白云飞处洞门开。","仙人来往行無跡，石徑春风长綠苔。"]', '诗', 'shi', '', NULL, '題潘師房 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545620e3-fea4-4afe-935e-3cd3c8f51abd', '謝自然却還舊居', '謝自然却還旧居', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["仙侶招邀自有期，九天升降五雲隨。","不知辭罷虛皇日，更向人間住幾時。"]', '["仙侶招邀自有期，九天升降五云隨。","不知辞罷虛皇日，更向人间住幾时。"]', '诗', 'shi', '', NULL, '謝自然却還舊居 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700e128d-c100-4b71-a469-14714de0e8c0', '寄李俌', '寄李俌', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["挂却衣冠披薜荔，世人應是笑狂愚。","年來漸覺髭鬚黑，欲寄松花君用無。"]', '["挂却衣冠披薜荔，世人應是笑狂愚。","年来漸覺髭鬚黑，欲寄松花君用無。"]', '诗', 'shi', '', NULL, '寄李俌 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80cd84e-66c5-4a2d-af2d-bafbb18166b6', '贈頭陀師', '贈头陀師', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["少壯從戎馬上飛，雪山童子未緇衣。","秋山年長頭陀處，說我軍前射虎歸。"]', '["少壯從戎马上飞，雪山童子未緇衣。","秋山年长头陀处，说我軍前射虎归。"]', '诗', 'shi', '', NULL, '贈頭陀師 劉商 shi');
